window.GENERATED_QUESTION_DATA = [{"id":"d1k1-deneme01-q001","number":1,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Bir hücrede ribozom ve DNA saptanıyor; ancak DNA çekirdek zarıyla çevrili değil ve membranlı organeller görülmüyor. Bu hücre için en uygun yorum hangisidir?","options":[{"label":"A","text":"Prokaryotik hücre organizasyonu gösterir.","imageOnly":false,"image":null},{"label":"B","text":"Hücre zarı bulunması yalnızca ökaryotlara özgüdür.","imageOnly":false,"image":null},{"label":"C","text":"DNA taşıdığı için mutlaka çekirdeği vardır.","imageOnly":false,"image":null},{"label":"D","text":"Membranlı organelleri bulunmadığından protein sentezleyemez.","imageOnly":false,"image":null},{"label":"E","text":"Ribozom taşıdığı için kesinlikle ökaryottur.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Prokaryotlarda DNA nükleoid bölgede bulunur; çekirdek zarı ve membranlı organeller yoktur. Ribozom hem prokaryotlarda hem ökaryotlarda bulunduğu için tek başına ayırt ettirmez.","topic":"Hücresel organizasyon","slideSources":[{"file":"Tıbbi Biyoloji/1-Tıbbi Biyolojiye Giriş.pdf","pages":[10,18],"pageKind":"PDF sayfası","evidence":[{"page":10,"text":"PROKARYOTIK\n▶Membranla çevrili organelleri yok \n▶Birkaç iç yapıya sahiptirler\n▶Tek hücreli organizmalar;\n▶Bakteriler,Arkeler ve virüsler\nhttp://library.thinkquest.org/C004535/prokaryotic_cells.html\n"},{"page":18,"text":"▶\nProkaryotik hücrelerin aksine, ökaryotik hücreler çekirdek ve membranlı \norganellere sahiplerdir. \nnucleus\ncell membrane\norganelles\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q002","number":2,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Bir deneyde plazma zarının iki yaprağındaki lipit dağılımının aynı olmadığı gösteriliyor. Bu gözlem hangi temel zar özelliğini doğrudan destekler?","options":[{"label":"A","text":"İç ve dış yaprakta glikolipit oranlarının zorunlu olarak eşit olmasını","imageOnly":false,"image":null},{"label":"B","text":"Zarın lipitlerinin tamamen hareketsiz olmasını","imageOnly":false,"image":null},{"label":"C","text":"Zarın iki yaprağının aynı fosfolipit oranlarını taşımasını","imageOnly":false,"image":null},{"label":"D","text":"Zardaki bütün proteinlerin yalnızca dış yaprakta bulunmasını","imageOnly":false,"image":null},{"label":"E","text":"Zarın lipit bileşimi açısından asimetrik olmasını","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Zarın iç ve dış yapraklarındaki lipit türleri ve oranları farklıdır. Bu asimetri, iki yaprağın aynı bileşimde olduğu anlamına gelen simetrik zar modelini dışlar. Zarın hidrofobik çekirdeği iyonların serbest geçişini sınırlar.","topic":"Zar asimetrisi","slideSources":[{"file":"Tıbbi Biyoloji/4-Membran Yapısı.pdf","pages":[7,8],"pageKind":"PDF sayfası","evidence":[{"page":8,"text":"Çift Katlı Lipid Yapının kompozisyonu\n•\nFosfolipidler çift zar tabakasının iki yarısına asimetrik olarak dağılırlar. Bu asimetri, dış ve iç yaprakta \nseçici olarak fosfolipid dağılımını gerçekleştiren taşıyıcılar sayesinde meydana gelir. \n•\nFosfatidil serinin baş kısmının negatif yüklü olması ve iç yapraktaki yoğun dağılımı hücre zarının \nsitozole bakan yüzünün negatif yüklenmesi ile sonuçlanır.\nDış yaprak\n1. Fosatidilkolin\n2. Sifingomiyelin\n3. Glikolipid\n4. Kolesterol\nİç yaprak\n1. Fosfatidiletanolamin\n2. Fosfatidilserin\n3. Fosfatidilinozitol\n4. Kolesterol\n"},{"page":7,"text":"Çift Katlı Lipid Yapının kompozisyonu\n• Hayvan hücrelerinin plazma zarları dört önemli fosfolipid içerir. \n1. Fosatidilkolin\n2. Fosfatidiletanolamin\n3. Fosfatidilserin\n4. Sifingomiyelin\n• Plazma zarlarının yapısında bulunan diğer önemli yağlar\n5. Fosfatidilinozitol\n6. Glikolipid\n7. Kolesterol\nBu yağlar plazma zar \nlipidlerinin yaklaşık %50-60’ını \noluştururlar \nBu yağlar plazma zar lipidlerinin \nyaklaşık %40’ını oluştururlar \n• E. Coli plazma zarının %80’ini fosfatidiletanolamin oluşturur\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q003","number":3,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Aynı sıcaklıkta ve aynı zincir uzunluğunda fosfolipitler içeren iki yapay zardan birinde cis çift bağların oranı artırılıyor. Diğer koşullar sabitken ne beklenir?","options":[{"label":"A","text":"Çift bağlar paketlenmeyi etkilemediğinden akışkanlık değişmez.","imageOnly":false,"image":null},{"label":"B","text":"Yağ asidi zincirlerinin sıkı paketlenmesi azalır ve akışkanlık artar.","imageOnly":false,"image":null},{"label":"C","text":"Zincirler daha sıkı paketlenir ve akışkanlık azalır.","imageOnly":false,"image":null},{"label":"D","text":"Geçiş sıcaklığı yükseldiği için akışkanlık azalır.","imageOnly":false,"image":null},{"label":"E","text":"Aynı sıcaklıkta cis ve doymuş zincirlerin paketlenmesi eşittir.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Cis çift bağlar zincirde kıvrılma oluşturur. Zincirlerin birbirine sıkı yaklaşması zorlaşınca, aynı sıcaklıkta zarın akışkanlığı artar. Zincir uzunluğu ve sıcaklığın sabit verilmesi diğer etkileri ayırır.","topic":"Zar akışkanlığı","slideSources":[{"file":"Tıbbi Biyoloji/4-Membran Yapısı.pdf","pages":[16,18],"pageKind":"PDF sayfası","evidence":[{"page":16,"text":"Plazma Zarı - Akışkan Mozaik Model \n(Jonathan Singer ve Garth Nicolson-1972)\n• Doğal fosfolipidlerin çoğunun yapısındaki yağ asitleri bir veya daha \nfazla çift bağ içerirler. Bu çift bağlar, hidrokarbon zincirlerin \nkıvrılmalarına neden olarak bir arada paketlenmelerini  güçleştirir ve \nplazma zarında serbestçe difüze olmalarını sağlar.\n• Böylece yağ asitlerinin hidrokarbon zincirleri zar içerisinde serbestçe \nhareket ederek, zara akışkanlık sağlar. Bu sayede proteinlerde zar \nyapısında hareket edebilirler.\nÇift bağ içeren yağ asitleri \ndoymamış yağ asidi olarak \nadlandırılır.\n"},{"page":18,"text":"Plazma Zarının Akışkanlığı ve Doymamış \nFosfolipidlerin Önemi\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q004","number":4,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Bir hücrenin Na⁺/K⁺ pompası bir ATP hidrolizlediğinde gerçekleşen taşıma hangisidir?","options":[{"label":"A","text":"Na⁺ ve K⁺ eşit sayıda hücre içine taşınır.","imageOnly":false,"image":null},{"label":"B","text":"2 Na⁺ hücre dışına, 3 K⁺ hücre içine taşınır.","imageOnly":false,"image":null},{"label":"C","text":"İki iyon da yalnızca derişim gradyanı yönünde taşınır.","imageOnly":false,"image":null},{"label":"D","text":"3 Na⁺ hücre dışına, 2 K⁺ hücre içine taşınır.","imageOnly":false,"image":null},{"label":"E","text":"3 Na⁺ hücre içine, 2 K⁺ hücre dışına taşınır.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Na⁺/K⁺-ATPaz her döngüde 3 Na⁺ dışarı, 2 K⁺ içeri taşır. ATP doğrudan kullanıldığı için birincil aktif taşımadır ve net bir pozitif yükün dışarı aktarılması nedeniyle elektrojeniktir.","topic":"Birincil aktif taşıma","slideSources":[{"file":"Tıbbi Biyoloji/5-Membran Transport Mek..pdf","pages":[37,42,43],"pageKind":"PDF sayfası","evidence":[{"page":37,"text":"Aktif Taşıma\n• Moleküllerin \ndüşük \nkonsantrasyondan \nyüksek \nkonsantrasyona doğru protein enerji kullanılarak taşınması \nolayıdır. \n• Aktif transportta kullanılan enerji ATP hidrolizinden elde \nedilebilir.\nTipik bir memeli hücresi \nplazma zarının iki yanındaki \niyon konsantrasyonu\n"},{"page":42,"text":"Na/K Pompası (Na+/K+ ATPaz gibi) \n• Na+ ve K+ iyonlarının hücre içi ve dışı arasındaki konsantrasyon farkını \nNa+/K+ Pompası oluşturmaktadır. \n• Her seferinde 3 Na+ dışarı pompalarken 2 K+ içeri pompalamaktadır. \n• Bu esnada 1 ATP harcanmaktadır. \n• Bu işlem hücre zarlarının elektrokimyasal potansiyeli için önemlidir. \n"},{"page":43,"text":"ATP hidrolizi ile desteklenen Na+-K+ pompasının \nçalışma modeli\nHücre içinde kalan \nbölgelere 3 Na+  iyonu \nbağlanır\nNa+’nun bağlanması \npompanın ATP-bağımlı \nfosforilasyonunu uyarır\nFosforilasyon, NA+ bağlanma \nbölgelerini hücre yüzeyine açar ve \nbağlanma afinitelerini düşürerek \nNa+’un hücre dışına serbest \nbırakılmasını sağlar.\nAynı anda, hücre yüzeyine \naçık olan, yüksek afiniteli \nbölgelere 2K+ bağlanır\nK+’un bağlanması pompanın \ndefosforilasyonunu uyarır\nBundan sonra, pompa başlangıçtaki \nyapısına dönerken K+’un hücre içine \nserbest bırakır\nİçi\nDış\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q005","number":5,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Yüksüz bir molekül, ATP tüketilmeden kendi derişim gradyanı yönünde bir taşıyıcıyla hücreye giriyor. Dış derişim çok yükseltildiğinde taşıma hızı plato çiziyor. En uygun mekanizma hangisidir?","options":[{"label":"A","text":"Lipit tabakadan basit difüzyon","imageOnly":false,"image":null},{"label":"B","text":"Fagositoz","imageOnly":false,"image":null},{"label":"C","text":"Birincil aktif taşıma","imageOnly":false,"image":null},{"label":"D","text":"Ekzositoz","imageOnly":false,"image":null},{"label":"E","text":"Taşıyıcı aracılı kolaylaştırılmış difüzyon","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"ATP harcanmaması ve gradyan yönünde hareket pasif taşımayı gösterir. Hızın doygunluğa ulaşması, sınırlı sayıdaki taşıyıcının tümünün çalışmasıyla açıklanır; bu özellik basit difüzyondan ayırır.","topic":"Kolaylaştırılmış difüzyon","slideSources":[{"file":"Tıbbi Biyoloji/5-Membran Transport Mek..pdf","pages":[6,11,12],"pageKind":"PDF sayfası","evidence":[{"page":6,"text":"Plazma Zarından Taşınma Şekilleri\n•\nKüçük Moleküllerin Taşınması\n– Membran proteinine ihtiyaç olmadan gerçekleşen taşıma \n• Basit Difüzyon\n– Membran proteini aracılığı ile gerçekleşen taşınım\n• Kolaylaştırılmış Difüzyon (Pasif Transport) \n– Taşıyıcı Proteinler\n– İyon Kanalları\n• Aktif Transport\n•\nMakro Moleküllerin Taşınması (Endositoz)\n– Fagositoz\n– Pinositoz\n"},{"page":11,"text":"Sodyum ve Glukozun  Simportırlar ile Taşınması\n•Bağırsaklardan \nve \nböbrek \ntübüllerinden glukozun hücre içine \nalınımı konsantrasyon gradiyentine \nkarşı gerçekleştirilir. \n•Bu hücreler 2 Na+ / 1 Glukoz \nsimportır taşıyıcısı denen taşıyıcı \nkanal proteinleri gerçekleştirilir. \n•Hücre dışında fazla olan Na+  \nhücre \niçine \nenerji \nharcamadan \nalınırken glukozu da beraberinde \ntaşır. \n"},{"page":12,"text":""}]}],"sourceNotes":"Transport slaydının 10. sayfası kolaylaştırılmış difüzyon ile sekonder aktif taşımayı başlıkta karıştırmaktadır. Bu soruda pasif taşıma ve gradyana karşı eşleşmiş taşıma ayrımı kullanılmıştır."},{"id":"d1k1-deneme01-q006","number":6,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Bir hücrede glukozun içeri alınması, Na⁺ iyonlarının elektrokimyasal gradyan yönünde hücreye girmesine bağlanmıştır. Taşıyıcı ATP hidrolizlemiyorsa enerji kaynağı nedir?","options":[{"label":"A","text":"Na⁺ iyonlarının gradyanına karşı hareketinden açığa çıkan enerji","imageOnly":false,"image":null},{"label":"B","text":"Na⁺ elektrokimyasal gradyanında depolanmış enerji","imageOnly":false,"image":null},{"label":"C","text":"Glukoz taşıyıcısının her döngüde doğrudan ATP hidrolizlemesi","imageOnly":false,"image":null},{"label":"D","text":"Glukozun hücre içindeki yüksek derişiminin içeri taşınmayı kendiliğinden sürdürmesi","imageOnly":false,"image":null},{"label":"E","text":"Na⁺ ile glukozun zorunlu olarak zıt yönlerde taşınması","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"İkincil aktif taşımada bir iyonun gradyan yönündeki hareketi, başka bir maddenin gradyanına karşı taşınmasına enerji sağlar. Na⁺ gradyanı genellikle Na⁺/K⁺-ATPaz tarafından oluşturulur; kotransporter doğrudan ATP tüketmez.","topic":"İkincil aktif taşıma","slideSources":[{"file":"Tıbbi Biyoloji/5-Membran Transport Mek..pdf","pages":[21,22],"pageKind":"PDF sayfası","evidence":[{"page":21,"text":"• Glukoz ile Na+’un eşgüdümlü alınımı, iki molekülün aynı \nyönde taşınması anlamına gelen simport’a örnektir.\n• Bunun aksine, glukozun kolaylaştırılmış difüzyonu uniport \nyani tek molekülün taşınmasına bir örnektir. \n• Na+-K+ pompası ile aktif taşıma, iki molekülün zıt yönlere \ntaşınması, yani antiport şeklinde de görülür. \nSimport-Uniport-Antiport Taşıma\n"},{"page":22,"text":"Amino Asitlerin  Simportırlar ile Taşınması\n• Hücre dışında düşük konsantrasyonda olan \namino \nasitler, \nNa+/amino \nasit \nsimporterları aracılığı ile  konsantrasyon \ngradientine karşı taşınırlar. \n• Bir \niyonun \nkonsantrasyonundan \nyararlanılarak, ATP kullanılmadan yapılan \nbu tür simporter taşımalar sekonder aktif \ntaşıma olarak adlandırılır. \n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q007","number":7,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Salgı proteininin N-terminal ER sinyal dizisi siliniyor; başka bir hedefleme dizisi de bulunmuyor. En olası erken sonuç hangisidir?","options":[{"label":"A","text":"Protein sinyal gerektirmeden ER lümenine aynı verimle girer.","imageOnly":false,"image":null},{"label":"B","text":"Salgı proteininin sentezi yalnızca Golgi üzerinde tamamlanır.","imageOnly":false,"image":null},{"label":"C","text":"Polipeptidin ER lümenine kotranslasyonel aktarımı aksar.","imageOnly":false,"image":null},{"label":"D","text":"Protein trans-Golgi’den ER’ye geri taşınarak salgılanır.","imageOnly":false,"image":null},{"label":"E","text":"Proteinin çekirdeğe aktif taşınması zorunlu olarak artar.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"ER sinyal dizisini SRP tanır ve ribozom-polipeptit kompleksinin ER translokonuna yönlenmesini sağlar. Dizinin kaybı bu proteinin ER yoluna girişini aksatır; diğer proteinlerin sentezinin tümü bundan zorunlu olarak etkilenmez.","topic":"ER hedeflenmesi","slideSources":[{"file":"Tıbbi Biyoloji/6-Hücrede Protein Trafiği.pdf","pages":[14,16],"pageKind":"PDF sayfası","evidence":[{"page":14,"text":"Proteinlerin ER’ e hedeflenmesi:\n1.\nKo-translasyonel translokasyon: Ribozomlar üzerinde protein sentezi devam \nederken gerçekleşir.\n2.\nPost-translasyonel translokasyon: Serbest ribozomlarda sitozolde sentezlenen \npolipeptid zincirlerinin sentez bittikten sonra ER’ e hedeflenmesi\n"},{"page":16,"text":"Proteinlerin ER’ e hedeflenmesi: \n• Sentezlenen Polipeptid zincirindeki Sinyal Peptid Dizisi Signal \nRecognition Particle (SRP) tarafından tanımlanır ve bağlanır. \n• Bu iki yapı da ER membranı üzerinde bulunan SRP reseptörüne \nbağlanır. \n• SRP yapıdan iki molekül GTP hidrolizi ile uzaklaştırılır. \n• Ribozomun translokon’a bağlanmasını takiben proteinin ER \nlümenine translokasyonu gerçekleşir.\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q008","number":8,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"ER’de sentezlenmiş bir salgı proteini doğru katlandığı hâlde cis-Golgi’ye ulaşamıyor. ER’den ileri yönlü tomurcuklanmada görevli hangi kılıfın bozukluğu öncelikle düşünülür?","options":[{"label":"A","text":"COPI","imageOnly":false,"image":null},{"label":"B","text":"Lamin","imageOnly":false,"image":null},{"label":"C","text":"Konneksin","imageOnly":false,"image":null},{"label":"D","text":"Klatrin","imageOnly":false,"image":null},{"label":"E","text":"COPII","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"COPII, ER’den Golgi’ye ileri taşınmada görev yapar. COPI daha çok geri kazanım yollarıyla; klatrin ise plazma zarından endositoz ve trans-Golgi kaynaklı bazı yollarla ilişkilidir. Konneksin ve lamin vezikül kılıfı değildir.","topic":"Vezikül kılıfları","slideSources":[{"file":"Tıbbi Biyoloji/11-Endositoz.pptx","pages":[19],"pageKind":"Slayt","evidence":[{"page":19,"text":"ER’da\n \nkatlanmış\n \nmodifiye\n \nedilmiş\n \nproteinler\n COPII \nvezikülü\n \nile\n \ncis-Golgiye\n \ntaşınırlar\n.\nProteinler\n \ncis-Golgide\n \ntekrar\n \ntasnif\n \nedilirler\n. \nYanlış\n \nproteinler\n COPI \nkılıflı\n \nveziküllerle\n \nER’a\n \ngeri\n \ngönderilir\n.\nMedial \ngolgide\n \nilave\n \ngereken\n protein \nmodifikasyonyarı\n \ngerçekleştirilir\n.\nTrans-\ngolgi\n \nsalınacak\n \nproteinler\n \niçin\n \nönemli\n \nbir\n \nkavşaktır\n. \nProteinler\n, \nburadan\n \nlizozoma\n \nya\n da \nhücre\n \nmembranına\n \ngönderilirler\n."}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q009","number":9,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Bir vezikül hedef bölgeye ulaşabiliyor; ancak vezikül zarı ile hedef zarın füzyonu gerçekleşmiyor. Hangi etkileşimin bozulması bu durumu en doğrudan açıklar?","options":[{"label":"A","text":"COPII ile aktin arasındaki bağın","imageOnly":false,"image":null},{"label":"B","text":"v-SNARE ile t-SNARE eşleşmesinin","imageOnly":false,"image":null},{"label":"C","text":"Konneksin ile konnekson arasındaki bağın","imageOnly":false,"image":null},{"label":"D","text":"Kohezin ile kardeş kromatitler arasındaki bağın","imageOnly":false,"image":null},{"label":"E","text":"Kaderin ile katenin arasındaki bağın","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Rab proteinleri hedefe yönlenme ve bağlanma süreçlerine katılır. Uygun v-SNARE ve t-SNARE kompleksinin kurulması ise iki zarın yakınlaşıp kaynaşmasında temel basamaktır.","topic":"Vezikül hedeflenmesi","slideSources":[{"file":"Tıbbi Biyoloji/11-Endositoz.pptx","pages":[16,17,18],"pageKind":"Slayt","evidence":[{"page":16,"text":"Vezikül\n \noluşup\n \ndonör\n \nmembrandan\n \nayrıldıktan\n \nsonra\n protein \nkılıf\n \ndökülür\n. Protein \nkılıfın\n \ndökülmesi\n GTP \ngerektirir\n.\nGTPaz"},{"page":17,"text":"Kargo\n \nproteini\n \ntaşıyan\n \nvezikülün\n \nhedef\n \nmembran\n \nile\n \nfüzyonunda\n \nrol\n \noynayan\n \nproteinler\n: v-SNARE \nve\n t-SNARE"},{"page":18,"text":"Rab\n \nproteinleri\n \nkargo\n \nproteini\n \ntaşıyan\n \nvezikülün\n \nhedef\n \nmembrana\n \nyönlenmesini\n \nsağlar"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q010","number":10,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"LDL reseptörünün hücre yüzeyinde LDL bağladığı, fakat reseptör-LDL kompleksinin kaplı çukurlarda toplanamadığı gösteriliyor. Hangi süreç öncelikle azalır?","options":[{"label":"A","text":"LDL’nin yalnızca basit difüzyonla hücreye girmesi","imageOnly":false,"image":null},{"label":"B","text":"Salgı proteinlerinin ekzositozu","imageOnly":false,"image":null},{"label":"C","text":"LDL’nin reseptör aracılı endositozu","imageOnly":false,"image":null},{"label":"D","text":"Hücre içindeki organellerin otofajiyle yıkılması","imageOnly":false,"image":null},{"label":"E","text":"Na⁺/K⁺ pompasının birincil aktif taşıması","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"LDL’nin hücreye alınması reseptör aracılı endositozla gerçekleşir. Bağlanmanın normal olması, içeri alınmanın da normal olacağını garanti etmez; kaplı çukurlara toplanma ve vezikül oluşumu da gereklidir.","topic":"Reseptör aracılı endositoz","slideSources":[{"file":"Tıbbi Biyoloji/11-Endositoz.pptx","pages":[21,23,31],"pageKind":"Slayt","evidence":[{"page":21,"text":"Endositik\n \nSistemler\n:\nReseptör\n \nAracılı\n \nEndositoz\nBazı\n \nmakromoleküllerin\n \nhücre\n \nyüzeyinde\n \nreseptörleri\n \nbulunur\n.\nMolekül\n \nreseptöre\n \nbağlandığında\n protein \nkılıflı\n \nçukur\n \noluşur\n. \nReseptör-molekül\n \nkompleksi\n \noluşan\n \nendozom\n \nile\n \nhücre\n \niçerisine\n \nalınır"},{"page":23,"text":"LDLR’ a \nbağlanan\n LDL \nmolekülü\n \nklatrin\n \nkaplı\n \nveziküller\n \nile\n \nhücre\n \niçerisine\n \nalınır\n."},{"page":31,"text":"Ailesel\n \nHiperkolesterolemi\nLDLR gen \nmutasyonları\nLDL’in\n \nkandan\n \ndokularda\n \nhücrelere \nalınması\n \nbozulur\n.\nHeterozigot\n \nbireylerde\n (\nbir\n \nkopya\n normal, \nbir\n \nkopya\n \nmutasyon\n \ntaşıyan\n) \nkan\n LDL \nseviyesi\n \nsağlıklı\n \nbireylere\n \ngöre\n \niki\n \nkat\n \nyüksektir\n.\nHomozigot\n \nbireylerde\n \nise\n 4-6 \nkat\n LDL \nseviyesi\n \nyüksektir\n.\nArtmış\n \nkalp\n \nrahatsızlığı\n \nriski\n."}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q011","number":11,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Besin yetersizliğinde bir hücre kendi hasarlı organellerini çift zarlı bir yapı içinde toplayıp lizozomal yıkıma gönderiyor. Bu olay hangisidir?","options":[{"label":"A","text":"Makrootofaji","imageOnly":false,"image":null},{"label":"B","text":"Fagositoz","imageOnly":false,"image":null},{"label":"C","text":"Basit difüzyon","imageOnly":false,"image":null},{"label":"D","text":"Konstitutif ekzositoz","imageOnly":false,"image":null},{"label":"E","text":"Reseptör aracılı LDL alımı","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Makrootofajide sitoplazmik bileşenler ve organeller otofagozom içinde paketlenir, ardından lizozomal yıkıma aktarılır. Fagositoz hücre dışındaki büyük partiküllerin alınmasıdır.","topic":"Otofaji","slideSources":[{"file":"Tıbbi Biyoloji/11-Endositoz.pptx","pages":[26,27],"pageKind":"Slayt","evidence":[{"page":26,"text":"Hücrede\n \nsindirilecek\n \nmoleküller\n \nçeşitli\n \nyollarla\n \nlizozomlara\n \niletilir\n: \nEndositoz\n, \nFagositoz\n \nve\n \nOtofaji"},{"page":27,"text":"Otofaji\n: \nİntraselüler\n \nyıkım\n \nsistemi\n‘\nHücrenin\n \nkendi\n \nkendini\n \nyemesi\n’\nHücrelerde\n \nsitoplazmanın\n \nbir\n \nkısmı\n (\nsitozolik\n \nproteinler\n) \nveya\n \nbir\n \norganelin\n \ntamamı\n \nlizozomlarda\n \nsindirilmesi\n \nolayı\n.\nOtofajik\n \nvezikül-otofagazom\nFizyolojik\n \nve\n \npatofizyolojik\n \ndurumlarda\n \nolabilir\n.\nRol\n \nalan\n \nproteinler\n \nhalen\n \naydınlatılmaktadır\n.\nHücrenin\n \nuzun\n \nsüreli\n \naçlığa\n \nbırakılması\nÇalışmayan\n \nmitokondrilerin\n \nortadan\n \nkaldırılması\n \ngibi\n \ndurumlarda\n \ngörülür\n."}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q012","number":12,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Bir hücrede lizozom lümeninin asidik kalması engelleniyor. En doğrudan hangi işlevin azalması beklenir?","options":[{"label":"A","text":"Çekirdek porlarından RNA taşınması","imageOnly":false,"image":null},{"label":"B","text":"Asit hidrolazlarla makromolekül yıkımı","imageOnly":false,"image":null},{"label":"C","text":"Mitokondri matriksinde DNA replikasyonu","imageOnly":false,"image":null},{"label":"D","text":"Ribozomların amino asitler arasında peptit bağı oluşturması","imageOnly":false,"image":null},{"label":"E","text":"Sitozolik proteazomların ubikitinli proteinleri tanıması","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Lizozomal hidrolazlar asidik ortamda etkili çalışır. Lümen pH’sının yükselmesi, enzimler mevcut olsa bile sindirim kapasitesini düşürebilir. Bu bozukluk tüm hücresel ATP kullanımının durması anlamına gelmez.","topic":"Organel işlevleri","slideSources":[{"file":"Tıbbi Biyoloji/3-Organel.pdf","pages":[20],"pageKind":"PDF sayfası","evidence":[{"page":20,"text":"Lizozomal Asit Hidrolazlar ve \nLizozomal Depo Hastalıkları  \n•\nLizozomlar, DNA, RNA, polisakkarid ve \nlipidleri hidrolize eden 50 kadar farklı \nyıkım enzimini barındırır. Bu enzimleri \nkodlayan genlerdeki mutasyonlar, etkilenen \nkişilerde lizozom içi materyalin birikimi \nnedeniyle, lizozomal depo hastalıkları \nolarak tanımlanan 30’dan fazla genetik \nhastalıktan sorumludur.\n•\nTüm lizozomal enzimler lizozom içi asit \npH’sında (5 civarı) aktif hale gelirler. \nSitoplazmanın 7.2 pH’sında inaktif olurlar. \n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q013","number":13,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Normal diploid bir insan somatik hücresi S fazını tamamlıyor; mitoz henüz başlamamıştır. G1’e kıyasla hangi değişim doğrudur?","options":[{"label":"A","text":"Kromozom sayısı 23’e iner.","imageOnly":false,"image":null},{"label":"B","text":"DNA miktarı iki katına çıkar, kromozom sayısı değişmez.","imageOnly":false,"image":null},{"label":"C","text":"Her kromozom yalnızca tek kromatit içerir.","imageOnly":false,"image":null},{"label":"D","text":"DNA miktarı ve kromozom sayısı birlikte yarıya iner.","imageOnly":false,"image":null},{"label":"E","text":"DNA miktarı değişmez, kromozom sayısı iki katına çıkar.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"S fazında DNA eşlenir ve her kromozom iki kardeş kromatit taşır. Sentromer sayısına göre sayılan kromozom sayısı 46 kalırken DNA miktarı 2C’den 4C’ye yükselir. Kromatit sayısı ile kromozom sayısı karıştırılmamalıdır.","topic":"DNA ve kromozom sayısı","slideSources":[{"file":"Tıbbi Biyoloji/8-Hücre Döngüsü ve Bölünmesi.pdf","pages":[7,22,26],"pageKind":"PDF sayfası","evidence":[{"page":7,"text":"Hücre döngüsünün 4 fazı\n• G1 (Gap1, İlk aralık): RNA ve \nprotein sentezi, organeller iki katına\nçıkar, DNA için sentez hazırlığı.\n• S  fazı:  DNA sentezi\n• G2 (Gap2, İkinci aralık): DNA \nsentezi tamamlanır, RNA ve protein \nsentezi devam eder\n• M fazı: Çekirdek ve sitoplazma \nbölünmesi olur.\nG1 ve G2 fazı sadece bir zaman aralığı oluşturmak için değil aynı zamanda internal ve eksternal olarak \nhücre bölünmesi için gerekli koşulların sağlanıp sağlanmadığı ve hazırlıkların tamamlanıp \ntamamlanmadığı konusunda kontrollerin yapılması için de gereklidir.\n"},{"page":22,"text":"S Fazı\n• DNA ve DNA’ya bağlı olan proteinlerin \nhepsi bu fazda dublike olur\n• Sentriollerin replikasyonu gerçekleşir, DNA \ntamiri gerekli ise yapılır\n• Replikasyon mutasyonları minimize \netmek için olağanüstü düzeyde kontrollü \nbir şekilkde olmalıdır. \n• Her nükleotid sadece 1 kere dublike\nolmalı ve böylelikle gen amplifikasyonu\nönlenmelidir.\n"},{"page":26,"text":"G2: Mitoza Hazırlık\n• Mitoz için gerekli RNA ve proteinler sentezlenir.\n• Sentrioller olgunlaşır.\n• G2 – Mitoz’a geçişte kontrol noktası\n• Mitoz için enerji üretilir ve depolanır.\n• Hasarlı DNA’nın tamiri yapılır \n• Tubulin sentezi gerçekleşir.\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q014","number":14,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"APC/C’nin sekürini yıkıma işaretlemesi engellenirse aşağıdakilerden hangisi en doğrudan beklenir?","options":[{"label":"A","text":"Separazın etkinleşmesi hızlanır ve anafaz erkene çekilir.","imageOnly":false,"image":null},{"label":"B","text":"Kohezin sekürin tarafından doğrudan kesilmeye başlar.","imageOnly":false,"image":null},{"label":"C","text":"Kardeş kromatitler sekürinden bağımsız olarak zorunlu biçimde ayrılır.","imageOnly":false,"image":null},{"label":"D","text":"Homolog kromozomlar ayrılır, kardeş kromatitler mayoz II’ye kalır.","imageOnly":false,"image":null},{"label":"E","text":"Separaz baskılanmış kalır ve kardeş kromatitlerin ayrılması aksar.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Sekürin separazı inhibe eder. APC/C sekürinin yıkımını başlatınca separaz serbestleşir ve kardeş kromatitleri bir arada tutan kohezin kompleksini keser. Sekürin yıkılmadığında bu zincir aksar.","topic":"Anafazın başlatılması","slideSources":[{"file":"Tıbbi Biyoloji/8-Hücre Döngüsü ve Bölünmesi.pdf","pages":[17,25,42],"pageKind":"PDF sayfası","evidence":[{"page":17,"text":"Metafaz-Anafaz geçişi\n• Anafaz–destekleyici kompleks \n(Anaphase-promoting complex) ya da \nSiklozom (cyclosome)\n• APC/C\n• Ubikitin ligaz: spesifik regülatör \nproteinlerin proteolitik yıkımı\n• Sekürinkardeş proteinleri bir arada \ntutuyor (seperazı inhibe ederek)\n• S-siklin ve M-siklin\n"},{"page":25,"text":"Kohezin\n• Kardeş kromatitleri bir arada tutar\n• İki adet SMC proteininden ve Scc\nproteininden oluşur.\n"},{"page":42,"text":"Anafazda kardeş kromatitlerin ayrılması\n• APC/C’nin Seperaz denilen bir proteini\ninhibe eden sekürin proteinini\nubikitinleyip yıkımına sebep olması ile\nbaşlayan süreç\n• Tüm kinetokorlar doğru şekilde\nbağlanmadığında APC/C bloklanıyor\nve anafaz başlamıyor\n• APC/C aynı zamanda S- ve M-\nsiklinleride degrede ettiğinden diğer \nCdklar anafazda inaktif durumdalar\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q015","number":15,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Metafazdaki bir hücrede tek bir kromozomun kinetokoru iğ mikrotübüllerine uygun biçimde bağlanmamıştır. Kontrol sistemi çalışıyorsa hangi olay geciktirilir?","options":[{"label":"A","text":"Anafaza geçiş","imageOnly":false,"image":null},{"label":"B","text":"DNA eşlenmesinin G1’den S’ye geçişte başlatılması","imageOnly":false,"image":null},{"label":"C","text":"Endositoz vezikülünün erken endozomla birleşmesi","imageOnly":false,"image":null},{"label":"D","text":"Sitozoldeki bir salgı proteininin ER’ye hedeflenmesi","imageOnly":false,"image":null},{"label":"E","text":"Homologların zigotende sinaps yapması","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"İğ kontrol noktası, tüm kromozomlar uygun biçimde bağlanmadan kardeş kromatitlerin ayrılmasını engeller. Böylece yanlış kromozom dağılımı riski azaltılır; geçmişte tamamlanan S fazı geriye dönük olarak durdurulmaz.","topic":"İğ kontrol noktası","slideSources":[{"file":"Tıbbi Biyoloji/8-Hücre Döngüsü ve Bölünmesi.pdf","pages":[11,30,40],"pageKind":"PDF sayfası","evidence":[{"page":11,"text":"Hücre Döngüsü Kontrol Sistemi\n•\nG1 kontrol noktası(Start-Restriksiyon noktası-ilk karar noktası)\n•\nHücrenin yeteri kadar büyüyüp-büyümediği ve DNA’ da hasar olup-\nolmadığı kontrol edilir.\n•\nHücre yeteri kadar büyümüş ise ve DNA’ da hasar yoksa başla\nsinyali verilir.\n•\nBöylece S evresi başlar.\n•\nG2/M kontrol noktası:\n•\nDNA eşlemesinin doğru yapılıp-yapılmadığı kontrol edilir.\n•\nDNA eşlemesinde hata yoksa devam et sinyali verilir.\n•\nBöylece M evresi başlar.\n•\nM kontrol noktasıMetafaz-Anafaz Geçişi\n•\nMetafaz evresinde gerçekleşir.\n•\nİğ ipliklerinin, kromozomların kinetokorlarına bağlanıp-bağlanmadığı\nkontrol edilir.\n•\nİğ ipliklerinin kromozomlara bağlanmasında hata yoksa devam et \nsinyali verilir ve kardeş kromatitlerin ayrılması stimule edilir.\n"},{"page":30,"text":"Metafaz\n• Kromozomlar ekvatorda dizilirler.\n• Kinetokor mikrotübülleri kromozomları \nmetafaz plağında hareket ettirirler. \n"},{"page":40,"text":"Kromozomların alternatif bağlanma şekilleri\n• Bipolar bir bağlanma söz konusu\n• Dene-Yanıl yöntemi ile bağlanıyor\n• Bir gerginlik algılayan mekanizma \nile kontrol ediliyoryüksek \ngerginlik oluşunca inhibitör \nmekanizmalar devredışı kalıyor ve \ndaha çok mikrotübül bağlanıp bir \nfiber oluşturuyor.\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q016","number":16,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Bir kültürde hücrelerin apoptozu azalıyor; buna karşın hücrelerin S fazına giriş oranında artış saptanmıyor. Eklenen sinyal için en uygun sınıflama hangisidir?","options":[{"label":"A","text":"Kardeş kromatitlerin ayrılmasını başlatan separaz","imageOnly":false,"image":null},{"label":"B","text":"Başlıca sağkalım etkisi gösteren faktör","imageOnly":false,"image":null},{"label":"C","text":"Öncelikle hücre kütlesini artıran büyüme sinyali","imageOnly":false,"image":null},{"label":"D","text":"İğ mikrotübüllerine bağlanan yapısal tübülin","imageOnly":false,"image":null},{"label":"E","text":"Başlıca hücre döngüsüne girişi uyaran mitojen","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Sağkalım faktörleri hücreyi apoptozdan korur. Mitojenlerin temel etkisi hücre döngüsüne ilerlemeyi uyarmaktır. Hayatta kalma ile bölünme birbirinden ayrılabilen süreçlerdir.","topic":"Ekstrasellüler sinyaller","slideSources":[{"file":"Tıbbi Biyoloji/9-Hücre Döngüsü Kontrolü.pdf","pages":[3,18,22],"pageKind":"PDF sayfası","evidence":[{"page":3,"text":"EKTRASELÜLER SİNYAL \nMOLEKÜLLERİ\n1) Mitojenler Hücre bölünmesi, G1/S-Cdk aktivitesi \n2) Büyüme FaktörleriHücre büyümesi, protein sentezi ve protein \nyıkımının inhibe edilmesi\n3) Yaşama (Sağkalım) Faktörleri Hücrenin yaşaması, apoptozu \nbaskılayarak\n"},{"page":18,"text":"YAŞAMA (SAĞKALIM) FAKTÖRLERİ\n• Hücrelerin apoptozdan korunmasını, \nhayatta kalmasını ve homeostatik \ndengeyi sürdürmesini sağlayan \nekstrasellüler sinyal molekülleridir.\n• Büyüme faktörleri proliferasyonu \nuyarırken sağkalım faktörleri \nprogramlı hücre ölümünü (apoptozu) \nengeller.\n"},{"page":22,"text":"Hücre döngüsündeki kontrol etkisi\n• Sağkalım faktörleri, G₁/S kontrol noktasında hücrenin “ölüm mü, \nbüyüme mi?” kararını etkiler.\n• DNA hasarı veya büyüme sinyali eksikliğinde p53 → Bax → apoptoz\naktivasyonu olur.\n• Aktif sağkalım sinyalleri p53 aktivitesini baskılayarak hücre \ndöngüsünün devamına izin verir.\n• Dolayısıyla, sağkalım faktörleri hücre döngüsü inhibitörlerinin \n(örneğin p21, p27) baskılanmasına dolaylı katkı sağlar.\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q017","number":17,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Bir germ hücresinde homolog kromozomlar zıt kutuplara giderken kardeş kromatitler birlikte hareket ediyor. Hücre hangi evrededir?","options":[{"label":"A","text":"Telofaz II","imageOnly":false,"image":null},{"label":"B","text":"Anafaz II","imageOnly":false,"image":null},{"label":"C","text":"Anafaz I","imageOnly":false,"image":null},{"label":"D","text":"Mayoz öncesi S fazı","imageOnly":false,"image":null},{"label":"E","text":"Mitoz anafazı","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Mayoz I’de homolog kromozomlar ayrılır ve kardeş kromatitler aynı kutba gider. Mayoz II’de ve mitozda ise kardeş kromatitler birbirinden ayrılır.","topic":"Mayozda ayrılma","slideSources":[{"file":"Tıbbi Biyoloji/10-Mayoz Bölünme.pptx","pages":[6,9,12],"pageKind":"Slayt","evidence":[{"page":6,"text":"Mayoz iki bölümlüdür\n6\nHomolog\nlar\nayrılır\nKardeş\n kromatidler\nayrılır\nHer bir gamet bir kromozomdan bir kopya kalır.\n.\nHaploid\nDiploid\nM\nayoz\n I\n(red\nüksiyon\nbölünmesi\n)\nM\nayoz\n II\n(e\nşitlik\nbölünmesi\n)\nHaploid\nMayoz cinsiyetin temelidir.\nZ\ni\ngot\nYumurta\nSperm\nMayoz, gametleri oluşturan bir bölünmedir. İki haploid gamet bir araya gelerek zigotu oluşturur. "},{"page":9,"text":"Mayoz I: \nProfaz I \t\t        \nMeta\nf\na\nz\n I\n            \nAna\nf\na\nz\n I\n         \nTelo\nf\na\nz \nI\n9\nHomolog \nkromozomlar ekvator  plağında yerleşirler\n.\nHomolog\nlar\n \nayrılır ve Kutuplara hareket ederler\n.\n Kardeş kromatidler\n \nSentromerle bağlı olarak kalır\n.\nNu\nk\nle\nus\n \nzarı oluşur\n.\n İğ yok olur\n.\n Sitokinez\n \nhücreyi ikiye böler\n.\nErken \npro\nf\na\nz\nHomolog\nlar \n \neşleşir\n. \nK\nrossing over \nolur\n.\nGeç\n pro\nf\na\nz\nK\nromo\nzomlar\n \nkondense olur\n.\nİğ ipliği oluşur\n.\nNu\nk\nle\nus\n \nzarı\n \nparçalanır\n."},{"page":12,"text":"M\nayoz\n II\n12\nPro\nf\na\nz\n II\n \n(haploid)\nNu\nk\nle\nus\n \nzarı parçalanır İğ oluşur\n.\nMeta\nf\na\nz\n II\n \n(\nn\n)\nKromozomlar ekvator plağında dizilirler.\nAna\nf\na\nz\n II\n \n(\nn\n)\n \nKardeş kromatidler ayrılırlar ve zıt kutuplara giderler\n.\nTelo\nf\na\nz\n II\n \n(\nn\n)\nNukleus zarı oluşur\n.\n K\nromo\nzomlar\n \ndekondanse olurlar\n.\n İğ kaybolur\n.\n Sitokinezle iki hücre oluşur\n.\nNon-İdentik\n4 yavru hücre (n)\nHücrede sadece homologlardan biri bulunur. \nMitoz bölünme karekteri gösterir, \n4\n tane genetik olarak  farklı\n  haploid gamet\n verir\n.\nM\nayoz\n II \nsonucu her kromozomun tek kopyası, yani tek allel bulunur. "}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q018","number":18,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Tek bir homolog çiftinde yalnızca mayoz II’de, iki hücreden birinde ayrılamama gelişiyor; diğer bölünmeler normaldir. Dört ürünün kromozom sayısı dağılımı hangisidir?","options":[{"label":"A","text":"İki n+1, iki n−1","imageOnly":false,"image":null},{"label":"B","text":"Dört n+1","imageOnly":false,"image":null},{"label":"C","text":"Bir 2n, üç n","imageOnly":false,"image":null},{"label":"D","text":"Dört n−1","imageOnly":false,"image":null},{"label":"E","text":"İki n, bir n+1, bir n−1","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Mayoz I normal olduğu için bir hücrenin mayoz II ürünleri normaldir. Diğer hücrede kardeş kromatitlerin ayrılamaması bir n+1 ve bir n−1 ürün oluşturur. Mayoz I ayrılamamasında ise dört ürünün tümü etkilenir.","topic":"Ayrılamama","slideSources":[{"file":"Tıbbi Biyoloji/10-Mayoz Bölünme.pptx","pages":[20,21],"pageKind":"Slayt","evidence":[{"page":20,"text":"Mayoz I\n’\nde \nNondisjunction:\n Ayrılamama\nAnafaz I\n’\nde n\nondisjunction \n(kromozomların ayrılamaması) \nn+1\n  kromozomlu iki gamet ve \nn-1\n kromozomlu iki gamet verir.\nHem paternal (baba) hem de maternal (anne) kaynaklı kopyalar mevcuttur.\n20\nn\n + 1\nn\n + 1\nn\n – 1\nn\n – 1\nKromozom sayıları\nMayoz I’de \nNondisjunction\n \nNormal\nm\nayoz\n \nII\nGamet\nl\ne\nr"},{"page":21,"text":"Mayoz II\n’\nde \nNondisjunction:\n Ayrılamama\nMayoz II; Anafaz II\n’\ndeki n\nondisjunction \nise iki\n normal \nve iki\n anormal gamet\n verir\n.\nHem maternal hem de paternal kromozomlarda gözlenir.\n21\nn\n + 1\nn\n \n-\n 1\nn\nn\nKromozom sayıları\nNormal \nMayoz I\nMayoz II’de\nNondisjunction\nGamet\nl\ne\nr"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q019","number":19,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Aşağıdaki olaylardan hangisi mayoz sırasında yeni alel kombinasyonları oluşmasına doğrudan katkı sağlar?","options":[{"label":"A","text":"Homolog kromozomların kardeş olmayan kromatitleri arasında crossing-over","imageOnly":false,"image":null},{"label":"B","text":"Kardeş kromatitlerin daima birbirinin aynısı kalmasının zorunlu olması","imageOnly":false,"image":null},{"label":"C","text":"Gametlerin mitozla diploid hâle getirilmesi","imageOnly":false,"image":null},{"label":"D","text":"Bütün maternal homologların her zaman aynı kutba gitmesi","imageOnly":false,"image":null},{"label":"E","text":"Mayoz I ile mayoz II arasında DNA’nın yeniden eşlenmesi","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Crossing-over homologların kardeş olmayan kromatitleri arasında genetik materyal değişimidir. Bağımsız dağılım da çeşitlilik sağlar. Mayoz I ile II arasında yeni bir DNA replikasyonu gerçekleşmez.","topic":"Genetik çeşitlilik","slideSources":[{"file":"Tıbbi Biyoloji/10-Mayoz Bölünme.pptx","pages":[15,16,18],"pageKind":"Slayt","evidence":[{"page":15,"text":"Mayozun Avantajı \n?\nGenetik Çeşitlilik\nG\n \nE\n \nN\n \nE\n \nT\n İ K\n \nÇEŞİTLİLİK !!!\nGenetik Çeşitliliğin Kaynakları\nProfaz I\n’\nde Kross-over\nMetafaz I\n’\nde Bağımsız Dağılım (kromozom)\nRandom Fertilizasyon\n15"},{"page":16,"text":"1. Rekombinasyon (k\nrossing\n o\nver\n )\nHem anneden hemde babadan parçalar içeren rekombinant kromozomları üretir. \nHomolog kromozomların kromatidleri arasında parça değişimi.\nYeni kombinasyonlar oluşur\nP\nro\nf\na\nz\n \nMayoz\n I\n, Genetik çeşitlilik oluşturur.\nPro\nf\na\nz\n I\nmayoz\nNon\n-\nsister\nk\nromatid\nler\nTetrad\nCrossing\noverde\nKiazma\nbölgesi\nMeta\nf\na\nz\n I\nMeta\nf\na\nz\n II\nKardeş\nhücreler\nRe\nk\nombinant\nk\nromo\nz\nom\nlar\na\nb\nc\nd\ne\nf\nA\nB\nC\nD\nE\nF\nA\nB\nC\nD\nE\nF\na\nb\nc\nd\ne\nf"},{"page":18,"text":"2. Bağımsız Dağılım\nM\naternal \nve\n paternal homolog\n kromozomların her birinin kardeş hücrelere dağılımı diğer çiftlerinden bağımsızdır\nAnahtar\nMaternal\nK\nromo\nz\nom\n takımı\nPaternal \nK\nromo\nzom takımı\n1. Olasılık\nMetafaz I\n’\nde\n \nHer iki olasılıkta\nmümkündür\n2. Olasılık \nMeta\nf\na\nz\n II\nKardeş\nhücreler\nK\nombina\nsy\non 1\nK\nombina\nsy\non 2\nK\nombina\nsy\non 3\nK\nombina\nsy\non 4\n23 \nçift kromozom Kombinasyon sayısı yumurta ve sperm de \n \n2\n23\n  =   8,388,608\nDöllerdeki kombinasyon sayısı\n  \n2\n23\n  X   2\n23\n   =   70,368,744,177,664\n \nYeni kombinasyonlar oluşturur. \nGen-Genotip sayısı\n = 3\n3\n0,000 \n  = 10\n19100\n ?"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q020","number":20,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Bir hücrede Arp2/3 kompleksinin etkinliği seçici olarak azaltılıyor. Hangi yapılanmanın doğrudan azalması beklenir?","options":[{"label":"A","text":"Konneksinlerin altılı kanal kompleksi oluşturması","imageOnly":false,"image":null},{"label":"B","text":"Ara filaman tetramerlerinin bir araya gelmesi","imageOnly":false,"image":null},{"label":"C","text":"Miyozin II’nin ATP hidrolizlemesi","imageOnly":false,"image":null},{"label":"D","text":"Paralel mikrotübül demetlerinin tübülinden kurulması","imageOnly":false,"image":null},{"label":"E","text":"Dallanmış aktin ağlarının oluşması","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Arp2/3 aktin filamanlarından yeni dalların çekirdeklenmesini destekler. Profilin, kofilin ve aktin bağlayıcı proteinler farklı basamakları düzenler; nükleer lamin ve tübülin başka iskelet sistemlerine aittir.","topic":"Aktin düzenlenmesi","slideSources":[{"file":"Tıbbi Biyoloji/Hucre Iskelet Sistemi-2020.pptx","pages":[13,14],"pageKind":"Slayt","evidence":[{"page":13,"text":"Aktin Flamanlarının Dallanması \nArp2/3 kompleksi\nARP2 ve ARP3 \nmonomerik\n \naktin\n ile yakın ilişki içindedir. \nAktin filamanların dallanması \nArp2/3 kompleksi ile gerçekleşir.\nAktin\n yapılanması; \nhücre hareketi, fagositoz, \npinositoz\n \nve\n hücre içi \norganel\n hareketi için önemlidir. "},{"page":14,"text":"Aktin\n \nDepolimerizasyonu\n ve \nPolimerizasyonu\n:\nADF/Kofilin ve Profilin\nADF/Kofilin \naktin\n filamanlarının eksi ucuna bağlanır ve \naktin\n-ADP \nmonomerlerinin\n ayrışma oranını artırır. \nKofilin; ADP-\naktine\n bağlanma eğilimindedir. Böylece ADP-\naktin\n \nmonomerlerinin\n filamana yeniden bağlanmasını engeller.\nProfilin;\n ADP-\naktini\n ATP-\naktine\n çeviri ve \naktinin\n \npolimerizasyona\n katılmasına olanak sağlar.\nADF/Kofilin\nProfilin"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q021","number":21,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Bir hücre iskeleti elemanı yaklaşık 10 nm çapındadır; kutupsuz yapı gösterir ve dokuya mekanik dayanıklılık sağlar. Hangisidir?","options":[{"label":"A","text":"Mikrotübül","imageOnly":false,"image":null},{"label":"B","text":"Aktin mikrofilamanı","imageOnly":false,"image":null},{"label":"C","text":"Klatrin kafesi","imageOnly":false,"image":null},{"label":"D","text":"Kromatin lifi","imageOnly":false,"image":null},{"label":"E","text":"Ara filaman","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Ara filamanlar yaklaşık 10 nm çapında, mekanik desteğe uygun ve kutupsuz yapılardır. Aktin filamanları daha ince, mikrotübüller yaklaşık 25 nm çapındadır; bu iki sistem kutupludur.","topic":"Ara filamanlar","slideSources":[{"file":"Tıbbi Biyoloji/Hucre Iskelet Sistemi-2020.pptx","pages":[27,28,30],"pageKind":"Slayt","evidence":[{"page":27,"text":"Ara Filamanların Yapılanması\nBütün \nAF’lerde\n 310-350 \naa’lik\n korunmuş bir alfa \nheliks\n yapı bulunur\nAF’ler\n \napolardır\n. Artı ve eksi uçları yoktur.\nN ve C uçlar alfa \nheliks\n olmayıp her \nAF’de\n farklı uzunluktadır. Bu gölge \nAF’lere\n farklılıklarını kazandırır.\n50’den fazla farklı ara flaman tipi tanımlanmıştır.\nAra filamanlar amino \nasid\n dizileri arasındaki benzerliklere göre \n6 grupta (Tip I-VI) sınıflandırılmışlardır. "},{"page":28,"text":"Ara filamanlar\nAktin filamanlar 6-8 \nnm\n \nçapında, \nmikrotübüller\n yaklaşık 25 \nnm\n çapındadır. Ara flamanlar \naktin\n flamanlar ile \nmikrotübüller\n arasında bir ölçüye \n10 \nnm\n) sahip olduğu için ara flaman olarak adlandırılmaktadır. \nHücre hareketlerine doğrudan katılmazlar\n. Bunun yerine \nhücre ve dokulara mekanik güç sağlayarak\n yapısal rol oynarlar."},{"page":30,"text":"Ara \nFilamaların\n, Aktin filamanlardan ve \nMikrotübüllerden\n Ayrılan Bir Dizi Özelliği Vardır\nBiyokimyasal olarak \nyüksek seviyede heterojen\n, evrimsel olarak ilişkili ve farklı dokularda eksprese olan bir protein ailesidir.\nSaç ve tırnaklarda da görüleceği gibi \nyüksek gerilme gücüne sahiptir\n.\nMikrofilament\n ve \nmikrotübüller\n gibi iç \npolariteye sahip değildir\n. \nPolar olmadıkları için üzerlerinde \nmotor proteinler ilerlemez\n.\nAlt birim değiştirme yönünde dinamik olmalarına rağmen \nmikrofilament\n ve \nmikrotübüllere\n kıyasla çok \ndaha fazla stabildirler\n. \nÜzerlerinde \nnükleotid bağlama bölgesi yoktur\n.\nFungus\n ve bitkilerde bulunmazlar.\nBöcekler ise sadece bir grup ara filamana (\nlamin\n A/C ve B) sahiptir."}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q022","number":22,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Bir aksonda kargo, mikrotübüllerin eksi uçlarının bulunduğu hücre gövdesine doğru taşınıyor. Bu taşınma en çok hangi motorla ilişkilidir?","options":[{"label":"A","text":"Konneksin","imageOnly":false,"image":null},{"label":"B","text":"Miyozin II","imageOnly":false,"image":null},{"label":"C","text":"Kaderin","imageOnly":false,"image":null},{"label":"D","text":"Sitoplazmik dinein","imageOnly":false,"image":null},{"label":"E","text":"Desmoplakin","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Sitoplazmik dinein mikrotübülün eksi ucuna doğru taşınmada görev yapar. Aksondaki bu yön çoğunlukla retrograd taşınmaya karşılık gelir. Miyozinler aktin üzerinde çalışır; diğer seçenekler bağlantı proteinleridir.","topic":"Motor proteinler","slideSources":[{"file":"Tıbbi Biyoloji/Hucre Iskelet Sistemi-2020.pptx","pages":[51,52,53],"pageKind":"Slayt","evidence":[{"page":51,"text":"Mikrotübüller\n ve Hareket\nMikrotübüller\n çeşitli hücre hareketinden sorumludur. Bunlar;\nHücre içi moleküllerin taşınması, \nZar \nvesiküllerinin\n ve \norganellerin\n yer değiştirmesi, \nMitozda kromozomların ayrılması, \nSil ve kamçıların hareketi olarak sınıflandırılabilir.\nMikrotübüller\n boyunca hareket, ATP hidrolizinden elde ettiği enerjiyi kullanabilen motor proteinler sayesinde gerçekleşir.\nİki büyük motor protein ailesinin üyeleri olan \nkinezinler\n ve \ndineinler\n \nmikrotübüllerin\n katıldığı hareketten sorumludur."},{"page":52,"text":"Mikrotübül\n Motor Proteinleri\nDineinler\n:       Kargolarını (+) uçtan (-) uca taşırlar\nKinesinler\n:  Kargolarını (-) uçtan (+) uca taşırlar"},{"page":53,"text":"Hücre İçi Taşınım ve \nOrganellerin\n Düzenlenmesi\nSinir hücreleri 1 metreden daha uzun aksonlara sahiptirler. Ribozomlar ise yalnızca hücre gövdesinde ve \ndendritlerde\n bulunurlar.  \nKinesinler\n: \nProteinler, salgı \nvesikülleri\n ve \norganeller\n (mitokondri) hücre gövdesinden aksonlara taşınır.  \nDineinler\n: \nAksonlardan \nendositoz\n ile hücre içine alınan \nvesiküller\n de hücre gövdesine taşınırlar.  \nDiğer hücre tiplerinde de taşınma benzer şekilde gerçekleşir.\nZarla \nkaplı \norganellerin\n \n(ER, GB, \nLizozom\n, Mitokondri) hücre içi yerleşimini düzenler"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q023","number":23,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Hareketli bir silde aksonemal dinein kolları çalışmıyor; mikrotübül çiftleri ise yerinde bulunuyor. Hangi işlev doğrudan bozulur?","options":[{"label":"A","text":"Kaderinlerin komşu hücreye kalsiyuma bağımlı bağlanması","imageOnly":false,"image":null},{"label":"B","text":"Komşu mikrotübül çiftleri arasındaki kaymaya bağlı sil hareketi","imageOnly":false,"image":null},{"label":"C","text":"Aktin filamanlarının miyozin üzerinde kaymasına bağlı kasılma","imageOnly":false,"image":null},{"label":"D","text":"Kohezinin separazla kesilmesine bağlı kromatit ayrılması","imageOnly":false,"image":null},{"label":"E","text":"Kinezinle mikrotübülün artı ucuna doğru kargo taşınması","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Aksonemal dinein ATP kullanarak mikrotübül çiftleri arasında kayma kuvveti üretir. Aksonemin bağlantı düzeni bu kaymayı bükülmeye dönüştürür; yapısal çiftlerin bulunması motor işlevinin sağlam olduğu anlamına gelmez.","topic":"Sil hareketi","slideSources":[{"file":"Tıbbi Biyoloji/Hucre Iskelet Sistemi-2020.pptx","pages":[56,57,58],"pageKind":"Slayt","evidence":[{"page":56,"text":"Silialar\n ve Kamcılar\nSilialar\n, solunum yolunda bulunur ve sıvı ya da mukusun \nepitel\n tabaka üzerinde hareket etmesini sağlar.\nKamçı, spermlerde bulunur ve spermin hareketinden sorumludur.\nLung\n \nCilia\nSperm \nCell"},{"page":57,"text":"Silialar\n ve Kamcıların yapısı ve \nMikrotübül\nHem \nsilia\n hem de kamçının temel yapısı \nmikrotübüller\n ile ilişkili proteinlerden oluşan \naksonemdir\n.\n \nAksonem\n(\nAxoneme\n)\nAksonemlerin\n (-) uçları dokuz adet \nmikrotübül\n üçlüsü içeren ve yapısı \nsentriole\n benzeyen \nbazal \ncisime\n \ntutunmaktadır\nbazal body "},{"page":58,"text":"Silialar\n ve Kamçıların Hareketi\nSilia\n ve kamçıların hareketleri, \naksonem\n yapısındaki dış \nmikrotübül\n çiftlerinden birinin diğerine göre hareketi  sonucu oluşmaktadır. \nBu hareket \naksonema\n \ndineinin\n \nmotor aktivitesi sonucu oluşmaktadır."}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q024","number":24,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Bağırsak epitelinde hücreler arası kaçak artarken apikal ve bazolateral zar bölgelerinin ayrımı da bozuluyor. Hangi bağlantıdaki kusur iki bulguyu birlikte açıklar?","options":[{"label":"A","text":"Desmozom","imageOnly":false,"image":null},{"label":"B","text":"Hemidesmozom","imageOnly":false,"image":null},{"label":"C","text":"Gap junction","imageOnly":false,"image":null},{"label":"D","text":"Tight junction","imageOnly":false,"image":null},{"label":"E","text":"Fokal adezyon","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Sıkı bağlantılar parasellüler geçişi sınırlar ve apikal-bazolateral zar bileşenlerinin karışmasını azaltır. Gap junction iletişim sağlar; desmozom ve hemidesmozomların temel görevi mekanik tutunmadır.","topic":"Sıkı bağlantı","slideSources":[{"file":"Tıbbi Biyoloji/12-Adezyon.pptx","pages":[8,9,10,11],"pageKind":"Slayt","evidence":[{"page":8,"text":"Tight\n \njunctions\n (Sıkı Kavşaklar/\nOccluding \nJ\nunctions\n)\nİnce bağırsağın iç yüzeyini kaplayan \nepitel\n hücreleri, \nTight\n \njunctions\n \nile bağırsak içeriğini bağırsak lümeninde tutar."},{"page":9,"text":"Tight\n \njunctions\n (Tıkayıcı Kavşaklar) (\nOccluding junctions\n)\nBarsak lümeninden besin emilimi iki grup \nmembran\n taşıma proteini ile gerçekleştirilir.\n1. Tepe yüzeyinde yerleşik \n(etkin taşıma)\n2. \nBazolateral\n yüzeyde yerleşik \n(kolaylaştırılmış difüzyon)\nTight\n \njunctions\n, \nbu proteinlerin birbirlerinin bulunduğu bölgelere geçmesine izin vermez."},{"page":10,"text":"Tight\n \njunctions\n (Tıkayıcı Kavşakların) Güncel Modeli\nTight\n \njunction\n, temel olarak \nklaudinler\n \nve \noklidinler\n  olarak adlandırılan, karşılıklı plazma zarlarına gömülü olup hücre dışı \ndomainleri\n birbirleri ile etkileşim içinde bulunan  proteinlerden oluşur."},{"page":11,"text":"Klaudin\n ve \nOklidinler\n hücre içi bir protein olan \nZO (\nzonula\n \noccludens\n) \nproteinleri aracılığı ile \naktin\n hücre iskeletine bağlanır\n.\nTight\n \njunctionın\n yapısına dahil olan \nbaşka proteinlerde \nbulunmaktadır. \nTight\n \nJunction\n ve Yapıya Katılan Proteinler"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q025","number":25,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Bir epitel hücresinin komşu hücrelere tutunması korunuyor; ancak bazal laminaya ara filamanlar üzerinden tutunması bozuluyor. Hangi bağlantı öncelikle etkilenmiştir?","options":[{"label":"A","text":"Desmozom","imageOnly":false,"image":null},{"label":"B","text":"Tight junction","imageOnly":false,"image":null},{"label":"C","text":"Hemidesmozom","imageOnly":false,"image":null},{"label":"D","text":"Hücre-hücre adherens bağlantısı","imageOnly":false,"image":null},{"label":"E","text":"Gap junction","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Hemidesmozom hücreyi integrinler aracılığıyla bazal laminaya bağlar ve hücre içinde ara filamanlarla ilişkilidir. Desmozomlar da ara filamanlara bağlanır fakat hücre-hücre bağlantısıdır.","topic":"Hücre-matriks bağlantısı","slideSources":[{"file":"Tıbbi Biyoloji/12-Adezyon.pptx","pages":[21,24,25,28],"pageKind":"Slayt","evidence":[{"page":21,"text":"Desmozomlar\nHücreleri birbirlerine perçinleyen, \ngerilimin ya da yırtıcı kuvvetlerin \nepitele\n dağılmasını sağlayan \ndüğme benzeri hücreler arası temas noktalarıdır.\nDesmozomalar\n bir hücrenin ara filamanlarını komşu hücrenin ara filamanlarına bağlar.\nDesmosomlarda\n \ndesmoglein\n ve \nDesmokollin\n olarak adlandırılan özelleşmiş \nkaderinler\n rol alır. \nDesmozomlara\n tutunan ara filamanlar hücrenin tipine göre değişir.\nEpitel\n hücrelerinde: \nkeratin\n filamanlar\n,\nKalp kas hücrelerinde: \ndesmin\n ara filamanları\nCadherin\n(\nDesmoglein\n, \nDesmokollin\n)\nSitoplazmik\n plak\n(\nPlakoglobin\n,\nDesmoplakin\n,\nKeratin\n \nflamanları\n)\nPlakoglobin\nDesmoplakin\nDesmoglein\n \nDesmokollin"},{"page":24,"text":"Hemidesmozom\nMorfolojik olarak \ndesmozomlara\n benzerler. Ancak \nhücre-hücre\n arasında değil, \nhücre-bazal \nlamina\n \narasında bağlantı kurarlar.\nHücrenin maruz kaldığı \ngerilim ya da yırtıcı kuvvetleri bazal \nlaminaya\n dağıtırlar.\nDesmozom\nHemidesmozom\nBasal\n \nlamina\nAra filaman"},{"page":25,"text":"Hemidesmozom\nHemidesmozomlar\n, \nintegrinler\n \nile \nbazal \nlaminaya\n (ECM) \nperçinlenir.\nİntegrinler\n \nplektin\n aracılığı ile \nara filamanlara \nbağlanır.\nİntegrin\nPlectin\nAra flaman\nHücre dışı \nmatriks\n (\nLamin\n proteini)\nKeratin5/14"},{"page":28,"text":"Gap\n \nJunction\n6 adet \nkonneksin\n bir araya gelerek \nkonneksonları\n oluşturur. İki adet \nkonnekson\n ise bir araya gelerek \nGap\n \njunctionları\n \noluşturur.\nİnsanlarda 14 farklı \nkonneksin\n (\nconnexin\n) geni tanımlanmıştır.\nGap\n \njunctionlar\n bir hücrenin sitoplazmasından diğer hücrenin sitoplazmasına inorganik iyonların ve suda çözünen moleküllerin \n(şekerler, amino sitler, nükleotidler, vitaminler, ve \ncAMP\n, IP\n3\n gibi)\n doğrudan geçişlerine izin verir.\nPlazma zarını 4 kez kat eden protein"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q026","number":26,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Komşu iki hücre arasında küçük iyonların doğrudan geçişi engelleniyor; mekanik tutunma büyük ölçüde korunuyor. Hangi yapının kusuru en uygundur?","options":[{"label":"A","text":"Konneksinlerden oluşan gap junction kanalları","imageOnly":false,"image":null},{"label":"B","text":"Kollajen liflerinin çapraz bağları","imageOnly":false,"image":null},{"label":"C","text":"Aktin-miyozin kontraktil halkası","imageOnly":false,"image":null},{"label":"D","text":"Kaderinlere bağlı desmozom plağı","imageOnly":false,"image":null},{"label":"E","text":"İntegrinlere bağlı hemidesmozom","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Gap junction iki hücrenin sitoplazması arasında küçük moleküller ve iyonlar için doğrudan iletişim sağlar. Altı konneksin bir konneksonu, karşılıklı iki konnekson ise hücreler arası kanalı oluşturur.","topic":"Hücreler arası iletişim","slideSources":[{"file":"Tıbbi Biyoloji/12-Adezyon.pptx","pages":[28],"pageKind":"Slayt","evidence":[{"page":28,"text":"Gap\n \nJunction\n6 adet \nkonneksin\n bir araya gelerek \nkonneksonları\n oluşturur. İki adet \nkonnekson\n ise bir araya gelerek \nGap\n \njunctionları\n \noluşturur.\nİnsanlarda 14 farklı \nkonneksin\n (\nconnexin\n) geni tanımlanmıştır.\nGap\n \njunctionlar\n bir hücrenin sitoplazmasından diğer hücrenin sitoplazmasına inorganik iyonların ve suda çözünen moleküllerin \n(şekerler, amino sitler, nükleotidler, vitaminler, ve \ncAMP\n, IP\n3\n gibi)\n doğrudan geçişlerine izin verir.\nPlazma zarını 4 kez kat eden protein"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q027","number":27,"year":"Deneme 01","subject":"Tıbbi Biyoloji","stem":"Aynı koşullarda agaroz jelde yürütülen doğrusal, çift zincirli iki DNA parçasından biri 400, diğeri 1600 baz çiftidir. Genel olarak hangi sonuç beklenir?","options":[{"label":"A","text":"1600 baz çiftlik parça negatif kutba daha fazla ilerler.","imageOnly":false,"image":null},{"label":"B","text":"Parça büyüklüğü göçü hiçbir biçimde etkilemez.","imageOnly":false,"image":null},{"label":"C","text":"Parçalar yalnızca baz dizilerine göre zıt kutuplara gider.","imageOnly":false,"image":null},{"label":"D","text":"Her iki parça DNA pozitif yüklü olduğu için negatif kutba gider.","imageOnly":false,"image":null},{"label":"E","text":"400 baz çiftlik parça pozitif kutba doğru daha fazla ilerler.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"DNA’nın fosfat omurgası negatiftir; bu nedenle pozitif elektroda göç eder. Aynı jelde doğrusal küçük parçalar gözeneklerden daha kolay geçerek genellikle daha uzağa ilerler. Bu, yöntemin kuramsal ilkesini sorgulayan teorik sorudur.","topic":"Elektroforezin ilkesi","slideSources":[{"file":"Tıbbi Biyoloji/13-Tıbbi Biyolojide Araçlar.pptx","pages":[14,23,26],"pageKind":"Slayt","evidence":[{"page":14,"text":"DNA\n’\nnın Özellikleri\n,\nNegatif yüklüdür,\nSuda çözünebilir,\nAlkolde çözünmez."},{"page":23,"text":"Agaroz Jel Elektroforezi\nDNA, RNA ve Proteinleri büyüklüklerine göre ayırma işleminde kullanılır. \nNegatif yüklü moleküllerin elektriksel alanda hareket ettirilmesi ile gerçekleştirilir. \nKısa (küçük) moleküller daha hızlı hareket ederek hızlı göç ederler."},{"page":26,"text":"Agarozun Ayırma Gücü\n30-40 bp\n’\nlik uzunluk farkı olan DNA fragmanları kolayca ayrılabilir.\nDNA zinciri uzadıkça jelin ayrım gücü azalır.\nJelin konsantrasyonu arttıkça uygun çalışma aralığında ayırma gücü artar. "}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q028","number":28,"year":"Deneme 01","subject":"Organik Kimya","stem":"CH₃CH₂OH ile CH₃OCH₃ arasındaki ilişki hangisidir?","options":[{"label":"A","text":"Birbirlerinin cis-trans izomerleridir.","imageOnly":false,"image":null},{"label":"B","text":"Molekül formülleri farklıdır.","imageOnly":false,"image":null},{"label":"C","text":"Aynı molekül formülüne sahip yapı izomerleridir.","imageOnly":false,"image":null},{"label":"D","text":"Aynı bileşiğin rezonans yapılarıdır.","imageOnly":false,"image":null},{"label":"E","text":"Aynı atom bağlantısına sahip konformerlerdir.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"İki bileşiğin molekül formülü C₂H₆O’dur; fakat atomların bağlanma sırası farklıdır. Etanol alkol, dimetil eter eterdir. Rezonansta atom bağlantıları değişmez.","topic":"Yapı izomerliği","slideSources":[{"file":"Organik Kimya/1-Karbon Bileşikleri.pdf","pages":[6,7],"pageKind":"PDF sayfası","evidence":[{"page":6,"text":"Chapter 1\n6\n●Isomers\n●Isomers are diﬀerent molecules with the same molecular formula\n●Many types of isomers exist\n●Example\n●\nConsider two compounds with molecular formula C2H6O\n●\nThese compounds cannot be distinguished based on molecular formula; however \nthey have diﬀerent structures\n●\nThe two compounds diﬀer in the connectivity of their atoms\n"},{"page":7,"text":"Chapter 1\n7\n●Constitutional Isomers\n●Constitutional isomers are one type of isomer\n●They are diﬀerent compounds that have the same molecular \nformula but diﬀerent connectivity of atoms\n●They often diﬀer in physical properties (e.g. boiling point, melting \npoint, density) and chemical properties\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q029","number":29,"year":"Deneme 01","subject":"Organik Kimya","stem":"HC≡CH molekülündeki karbon-karbon bağı ve karbon hibritleşmesi hangi seçenekte birlikte doğru verilmiştir?","options":[{"label":"A","text":"Bir σ ve bir π bağı; sp³ hibritleşmesi","imageOnly":false,"image":null},{"label":"B","text":"Üç σ bağı; sp³ hibritleşmesi","imageOnly":false,"image":null},{"label":"C","text":"Yalnızca iki π bağı; sp² hibritleşmesi","imageOnly":false,"image":null},{"label":"D","text":"Bir σ ve iki π bağı; sp hibritleşmesi","imageOnly":false,"image":null},{"label":"E","text":"İki σ ve bir π bağı; sp² hibritleşmesi","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Üçlü bağ bir sigma ve iki pi bağından oluşur. Her karbon sp hibritleşmiştir; bağ yapımına katılan iki hibritleşmemiş p orbitali iki pi bağını oluşturur. Molekül karbonlar çevresinde doğrusaldır.","topic":"Hibritleşme ve bağlar","slideSources":[{"file":"Organik Kimya/1-Karbon Bileşikleri.pdf","pages":[19,21,22],"pageKind":"PDF sayfası","evidence":[{"page":19,"text":"Chapter 1\n19\n●Overlap of sp2 orbitals in ethylene results in formation of a σ \nframework\n●\nOne sp2 orbital on each carbon overlaps to form a carbon-carbon σ bond; the \nremaining sp2 orbitals form bonds to hydrogen\n●The leftover p orbitals on each carbon overlap to form a bonding π \nbond between the two carbons \n●Α π bond results from overlap of p orbitals above and below the \nplane of the σ bond\n●\nIt has a nodal plane passing through the two bonded nuclei and  between the two \nlobes of the π molecular orbital\n"},{"page":21,"text":"Chapter 1\n21\n●The carbon in ethyne is sp hybridized\n●\nOne s and one p orbital are mixed to form two sp orbitals\n●\nTwo p orbitals are left unhybridized\n●The two sp orbitals are oriented 180o relative to each other around \nthe carbon nucleus\n●\nThe two p orbitals are perpendicular to the axis that passes through the center of \nthe sp orbitals\n"},{"page":22,"text":"Chapter 1\n22\n●In ethyne the sp orbitals on the two carbons overlap to form a σ \nbond\n●\nThe remaining sp orbitals overlap with hydrogen 1s orbitals\n●The  p orbitals on each carbon overlap to form two π bonds\n●The triple bond consists of one σ and two π bonds\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q030","number":30,"year":"Deneme 01","subject":"Organik Kimya","stem":"NH₃ molekülünde azot çevresinde üç bağ çifti ve bir ortaklanmamış elektron çifti bulunur. Atomların oluşturduğu molekül geometrisi hangisidir?","options":[{"label":"A","text":"Düzlemsel üçgen","imageOnly":false,"image":null},{"label":"B","text":"Üçgen piramidal","imageOnly":false,"image":null},{"label":"C","text":"Doğrusal","imageOnly":false,"image":null},{"label":"D","text":"Düzgün dörtyüzlü","imageOnly":false,"image":null},{"label":"E","text":"Kare düzlemsel","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Dört elektron bölgesi elektron çifti geometrisini tetrahedral yapar. Ancak molekül geometrisi atomların konumlarına göre adlandırılır; bir köşeyi yalnız çift tuttuğu için NH₃ üçgen piramidaldir.","topic":"VSEPR","slideSources":[{"file":"Organik Kimya/1-Karbon Bileşikleri.pdf","pages":[24,26],"pageKind":"PDF sayfası","evidence":[{"page":24,"text":"Chapter 1\n24\n⧫Molecular Geometry: The Valence Shell Electron \nPair Repulsion (VSEPR) Model\n●This is a simple theory to predict the geometry of molecules\n●All sets of valence electrons are considered including:\n●\nBonding pairs involved in single or multiple bonds\n●\nNon-bonding pairs which are unshared\n●Electron pairs repel each other and tend to be as far apart as \npossible from each other\n●Non-bonding electron pairs tend to repel other electrons more \nthan bonding pairs do (i.e. they are “larger”)\n●The geometry of the molecule is determined by the number of sets \nof electrons by using geometrical principles\n"},{"page":26,"text":"Chapter 1\n26\n●Ammonia\n●When the bonding and nonbonding electrons are considered there \nare 4 sets of electrons\n●The molecule is essentially tetrahedral but the actual shape of the \nbonded atoms is considered to be trigonal planar\n●The bond angles are about 107o and not 109.5o because the \nnon-bonding electrons in eﬀect are larger and compress the \nnitrogen-hydrogen bond\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q031","number":31,"year":"Deneme 01","subject":"Organik Kimya","stem":"Karbonat iyonunun rezonans gösterimi hakkında hangisi doğrudur?","options":[{"label":"A","text":"Gerçek yapının enerjisi bütün katkı yapılarından daha yüksektir.","imageOnly":false,"image":null},{"label":"B","text":"Her rezonans yapısında oksijen atomlarının yerleri değişir.","imageOnly":false,"image":null},{"label":"C","text":"Rezonans yapıları birbirinin yapı izomeridir.","imageOnly":false,"image":null},{"label":"D","text":"Gerçek yapı, elektronların delokalize olduğu bir rezonans hibritidir.","imageOnly":false,"image":null},{"label":"E","text":"İyon üç farklı yapı arasında sürekli atom değiştirir.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Rezonans yapıları aynı atom iskeletindeki farklı elektron dağılımlarını gösterir. Gerçek yapı bunlardan birine dönüşüp duran bir yapı değil, daha kararlı delokalize hibrittir.","topic":"Rezonans","slideSources":[{"file":"Organik Kimya/1-Karbon Bileşikleri.pdf","pages":[11,12,13],"pageKind":"PDF sayfası","evidence":[{"page":11,"text":"Chapter 1\n11\n⧫Resonance\n●Often a single Lewis structure does not accurately represent the \ntrue structure of a molecule\n●The real carbonate ion is not represented by any of the structures \n1,2 or 3\n●Experimentally carbonate is known not to have two \ncarbon-oxygen single bonds and one double bond;  all bonds are \nequal in length and the charge is spread equally over all three \noxygens\n"},{"page":12,"text":"Chapter 1\n12\n●The real carbonate ion can be represented by a drawing in which \npartial double bonds to the oxygens are shown and partial \nnegative charge exists on each oxygen\n●The real structure is a resonance hybrid or mixture of all three \nLewis structures\n●Double headed arrows are used to show that the three Lewis \nstructures are resonance contributors to the true structure\n●\nThe use of equilibrium arrows is incorrect since the three structures do not \nequilibrate; the true structure is a hybrid (average) of all three Lewis structures\n"},{"page":13,"text":"Chapter 1\n13\n●The energy of the actual molecule is lower than the energy of any \nsingle contributing form\n●\nThe lowering of energy is called resonance stabilization\n●Equivalent resonance forms make equal contributions to the \nstructure of the real molecule\n●\nStructures with equivalent resonance forms tend to be greatly stabilized\n●\nExample: The two resonance forms of benzene contribute equally and greatly \nstabilize it\n●Unequal resonance structures contribute based on their relative \nstabilities \n●\nMore stable resonance forms contribute more to the structure of the real molecule \n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q032","number":32,"year":"Deneme 01","subject":"Organik Kimya","stem":"CH₃–CO–NH₂ bileşiği, karbonil karbonuna doğrudan bağlı atom dikkate alındığında hangi sınıfa girer?","options":[{"label":"A","text":"Amid","imageOnly":false,"image":null},{"label":"B","text":"Eter","imageOnly":false,"image":null},{"label":"C","text":"Amin","imageOnly":false,"image":null},{"label":"D","text":"Ester","imageOnly":false,"image":null},{"label":"E","text":"Keton","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Karbonil karbonuna doğrudan azotun bağlanması amid grubunu oluşturur. Aminlerde karbonile doğrudan bağlı azot zorunlu değildir; esterde karbonile bir oksijen bağlıdır.","topic":"Fonksiyonel grup tanıma","slideSources":[{"file":"Organik Kimya/2-Fonksiyonel Gruplar.pdf","pages":[17,18,19],"pageKind":"PDF sayfası","evidence":[{"page":17,"text":"Chapter 2 \n17\n●Aldehydes and Ketones\n●Both contain the carbonyl group\n●Aldehydes have at least one carbon attached to the carbonyl group\n●Ketones have two organic groups attached to the carbonyl group\n●The carbonyl carbon is sp2 hybridized \n●\nIt is trigonal planar and has bond angle about 120o\n"},{"page":18,"text":"Chapter 2 \n18\n●Carboxylic Acids, Esters and Amides\n●All these groups contain a carbonyl group bonded to an oxygen or \nnitrogen\n●Carboxylic Acids\n●\nContain the carboxyl (carbonyl + hydroxyl) group\n●Esters\n●\nA carbonyl group is bonded to an alkoxyl (OR’) group\n"},{"page":19,"text":"Chapter 2 \n19\n●Amide\n●\nA carbonyl group is bonded to a nitrogen derived from ammonia or an amine\n●Nitriles \n●An alkyl group is attached to a carbon triply bonded to a nitrogen\n●\nThis functional group is called a cyano group\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q033","number":33,"year":"Deneme 01","subject":"Organik Kimya","stem":"C₆H₅– ve C₆H₅–CH₂– gruplarının adları sırasıyla hangisidir?","options":[{"label":"A","text":"Benzil ve fenil","imageOnly":false,"image":null},{"label":"B","text":"Sikloheksil ve fenil","imageOnly":false,"image":null},{"label":"C","text":"Fenil ve benzil","imageOnly":false,"image":null},{"label":"D","text":"Fenil ve etil","imageOnly":false,"image":null},{"label":"E","text":"Benzil ve metil","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Benzenden bir H uzaklaştırılınca fenil (C₆H₅–) oluşur. Toluenin metil grubundan bir H uzaklaştırılınca benzil (C₆H₅CH₂–) oluşur. Aradaki CH₂ grubu ayrımı belirler.","topic":"Fenil ve benzil","slideSources":[{"file":"Organik Kimya/2-Fonksiyonel Gruplar.pdf","pages":[13],"pageKind":"PDF sayfası","evidence":[{"page":13,"text":"Chapter 2 \n13\n●A benzene ring with a hydrogen removed is called a phenyl and \ncan be represented in various ways\n●Toluene (methylbenzene) with its methyl hydrogen removed is \ncalled a benzyl group\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q034","number":34,"year":"Deneme 01","subject":"Organik Kimya","stem":"CH₃–CH(CH₃)–CH₂–CH₂–CH₃ bileşiğinin IUPAC adı hangisidir?","options":[{"label":"A","text":"2,2-dimetilbutan","imageOnly":false,"image":null},{"label":"B","text":"4-metilpentan","imageOnly":false,"image":null},{"label":"C","text":"2-etilbutan","imageOnly":false,"image":null},{"label":"D","text":"2-metilpentan","imageOnly":false,"image":null},{"label":"E","text":"3-metilpentan","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"En uzun sürekli zincir beş karbonludur: pentan. Metil grubuna en küçük konumu veren uçtan numaralandırılır; konum 2 olur. Toplam altı karbon olması ana zincirin mutlaka hekzan olduğu anlamına gelmez.","topic":"Alkan adlandırma","slideSources":[{"file":"Organik Kimya/3-Alkanlar.pdf","pages":[8,9],"pageKind":"PDF sayfası","evidence":[{"page":8,"text":"Chapter 4 \n8\n●Nomenclature of Branched-Chain Alkanes (IUPAC)\n●Locate the longest continuous chain of carbons; this is the parent \nchain and determines the parent name.\n●Number the longest chain beginning with the end of the chain \nnearer the substituent\n●Designate the location of the substituent \n●When two or more substituents are present, give each substituent \na number corresponding to its location on the longest chain\n●\nSubstituents are listed alphabetically\n"},{"page":9,"text":"Chapter 4 \n9\n●When two or more substituents are identical, use the preﬁxes di-, \ntri-, tetra- etc.\n●\nCommas are used to separate numbers from each other\n●\nThe preﬁxes are used in alphabetical prioritization\n●When two chains of equal length compete to be parent, choose \nthe chain with the greatest number of substituents\n●When branching ﬁrst occurs at an equal distance from either end \nof the parent chain, choose the name that gives the lower number \nat the ﬁrst point of diﬀerence\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q035","number":35,"year":"Deneme 01","subject":"Organik Kimya","stem":"Aşağıdaki bileşiklerden hangisi cis-trans izomerliği gösterebilir?","options":[{"label":"A","text":"2-metilpropen","imageOnly":false,"image":null},{"label":"B","text":"Eten","imageOnly":false,"image":null},{"label":"C","text":"Etan","imageOnly":false,"image":null},{"label":"D","text":"2-büten","imageOnly":false,"image":null},{"label":"E","text":"Propen","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"2-bütende çift bağın her karbonuna iki farklı grup (H ve CH₃) bağlıdır. Eten, propen ve 2-metilpropende çift bağın en az bir karbonunda iki aynı grup bulunduğundan cis-trans çifti oluşmaz; etanda çift bağ yoktur.","topic":"Geometrik izomerlik","slideSources":[{"file":"Organik Kimya/3-Alkanlar.pdf","pages":[16,17],"pageKind":"PDF sayfası","evidence":[{"page":16,"text":"Chapter 4 \n16\n●If two identical groups occur on the same side of the double bond \nthe compound is cis\n●If they are on opposite sides the compound is trans\n●Several alkenes have common names which are recognized by \nIUPAC\n"},{"page":17,"text":"Chapter 4 \n17\n⧫Disubstitued Cycloalkanes\n●Can exist as pairs of cis-trans stereoisomers\n●\nCis: groups on same side of ring\n●\nTrans: groups on opposite side of ring\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q036","number":36,"year":"Deneme 01","subject":"Organik Kimya","stem":"1 mol propenin, katalizör varlığında 1 mol H₂ ile tam hidrojenasyonu sonucu hangi ana organik ürün oluşur?","options":[{"label":"A","text":"Propin","imageOnly":false,"image":null},{"label":"B","text":"Propanal","imageOnly":false,"image":null},{"label":"C","text":"Propan","imageOnly":false,"image":null},{"label":"D","text":"Propenol","imageOnly":false,"image":null},{"label":"E","text":"Propanon","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Hidrojenasyon C=C bağına H₂ katılmasıdır. Propenin çift bağı tek bağa dönüşür, üç karbonlu iskelet korunur ve propan oluşur. Oksijen içeren ürünler bu tepkimeyle kendiliğinden ortaya çıkmaz.","topic":"Hidrojenasyon","slideSources":[{"file":"Organik Kimya/3-Alkanlar.pdf","pages":[18],"pageKind":"PDF sayfası","evidence":[{"page":18,"text":"Chapter 4 \n18\n⧫Synthesis of Alkanes and Cycloalkanes\n●Hydrogenation of Alkenes and Alkynes\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q037","number":37,"year":"Deneme 01","subject":"Organik Kimya","stem":"Propen, peroksit bulunmayan koşullarda HBr ile tepkimeye sokuluyor. Başlıca ürün hangisidir?","options":[{"label":"A","text":"2-bromopropan","imageOnly":false,"image":null},{"label":"B","text":"1-bromopropan","imageOnly":false,"image":null},{"label":"C","text":"1,2-dibromopropan","imageOnly":false,"image":null},{"label":"D","text":"2-bromopropen","imageOnly":false,"image":null},{"label":"E","text":"Bromobenzen","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Normal iyonik katılmada Markovnikov yönlenmesi görülür: H terminal karbona, Br daha fazla sübstitüe karbona bağlanır. Böylece 2-bromopropan başlıca üründür. Peroksit koşulu özellikle dışlanmıştır.","topic":"Markovnikov katılması","slideSources":[{"file":"Organik Kimya/4-Alken Alkin.pdf","pages":[8],"pageKind":"PDF sayfası","evidence":[{"page":8,"text":"Chapter 8\n8\n⧫Addition of Hydrogen Halides to Alkenes: \nMarkovnikov’s Rule\n●Addition of HBr to propene occurs to give 2-bromopropane as the \nmajor product\n●Markovnikov’s Rule (Original): addition of HX to an alkene \nproceeds so that the hydrogen atom adds to the carbon that \nalready has the most hydrogen atoms\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q038","number":38,"year":"Deneme 01","subject":"Organik Kimya","stem":"1-büten önce BH₃, ardından H₂O₂/OH⁻ ile tepkimeye sokuluyor. Başlıca alkol ürünü hangisidir?","options":[{"label":"A","text":"2-metil-2-propanol","imageOnly":false,"image":null},{"label":"B","text":"Bütanal","imageOnly":false,"image":null},{"label":"C","text":"1-bütanol","imageOnly":false,"image":null},{"label":"D","text":"2-bütanol","imageOnly":false,"image":null},{"label":"E","text":"Bütanon","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Hidroborasyon-oksidasyon suyun anti-Markovnikov yönlenmesiyle net katılmasını sağlar. OH daha az sübstitüe, uç karbona gelir; 1-büten 1-bütanole dönüşür. Asit katalizli hidratasyonun yönlenmesi farklıdır.","topic":"Hidroborasyon-oksidasyon","slideSources":[{"file":"Organik Kimya/4-Alken Alkin.pdf","pages":[10,11,12],"pageKind":"PDF sayfası","evidence":[{"page":10,"text":"Chapter 8\n10\n⧫Alcohols from Alkenes Through \nOxymercuration-Demercuration: Markovnikov \nAddition\n●The procedure gives high yields of alcohols and avoids \nrearrangements\n●The reaction shows Markovnikov selectivity\n"},{"page":11,"text":"Chapter 8\n11\n⧫Alcohols from Alkenes through \nHydroboration-Oxidation: Anti-Markovnikov Syn \nHydration\n●The reaction leads to syn and anti-Markovnikov addition of water \nto alkenes\n●Hydroboration: Synthesis of Alkylboranes\n●The elements of hydrogen and boron are added across the double \nbond\n●\nIn practice, a borane complex with the solvent tetrahydrofuran (THF) is often used\n"},{"page":12,"text":"Chapter 8\n12\n●Hydroboration of methylcyclopentene gives the anti-Markovnikov \nproduct with syn addition of the elements of water\n●Summary of Alkene Hydration Methods\n●Acid-catalyzed hydrolysis: Markovnikov addition\n●Oxymercuration: Markovnikov addition \n●Hydroboration-Oxidation: anti-Markovnikov and syn addition\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q039","number":39,"year":"Deneme 01","subject":"Organik Kimya","stem":"Sikloheksen Br₂ ile, suyun nükleofil olarak yarışmadığı inert çözücüde tepkimeye sokuluyor. Hangi ürün sınıfı beklenir?","options":[{"label":"A","text":"Komşu karbonlarda iki Br taşıyan bir vicinal dibromür","imageOnly":false,"image":null},{"label":"B","text":"Doğrudan bir karboksilik asit","imageOnly":false,"image":null},{"label":"C","text":"Yalnızca aromatik halka","imageOnly":false,"image":null},{"label":"D","text":"Çift bağı değişmeden kalan bir alkol","imageOnly":false,"image":null},{"label":"E","text":"Aynı karbonda üç Br taşıyan ürün","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Alkenin pi bağına Br₂ katıldığında iki brom komşu karbonlara bağlanır. Su bulunmayan inert ortam ifadesi bromohidrin oluşumu olasılığını dışlar; bromun rengi tüketildikçe kaybolur.","topic":"Halojen katılması","slideSources":[{"file":"Organik Kimya/4-Alken Alkin.pdf","pages":[13],"pageKind":"PDF sayfası","evidence":[{"page":13,"text":"Chapter 8\n13\n⧫Addition of Bromine and Chlorine to Alkenes\n●Addition produces vicinal dihalides \n●This reaction is used as a test for alkenes because the red color of \nthe bromine reagent disappears when an alkene (or alkyne) is \npresent\n●\nAlkanes do not react with bromine in the dark\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q040","number":40,"year":"Deneme 01","subject":"Organik Kimya","stem":"2-bütenin ozonolizi ve ardından Zn/asetik asit ile indirgen işlenmesi sonucunda hangi karbonil bileşiği oluşur?","options":[{"label":"A","text":"Propanon","imageOnly":false,"image":null},{"label":"B","text":"Etanon","imageOnly":false,"image":null},{"label":"C","text":"Etanal","imageOnly":false,"image":null},{"label":"D","text":"Bütanal","imageOnly":false,"image":null},{"label":"E","text":"Metanal","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"CH₃–CH=CH–CH₃ çift bağı ikiye ayrılır. Her çift bağ karbonunda bir H bulunduğu için iki tarafta da CH₃CHO, yani etanal oluşur. İndirgen işleme aldehitlerin asitlere ileri yükseltgenmesini sınırlar.","topic":"Ozonoliz","slideSources":[{"file":"Organik Kimya/4-Alken Alkin.pdf","pages":[16],"pageKind":"PDF sayfası","evidence":[{"page":16,"text":"Chapter 8\n16\n●Ozonolysis of Alkenes\n●Cleavage of alkenes with ozone and workup with zinc in acetic \nacid leads to less highly oxidized carbons than products from \ncleavage with hot KMnO4\n●\nUnsubstituted carbons are oxidized to formaldehyde, monosubstituted carbons \nare oxidized to aldehydes and disubstituted carbons are oxidized to ketones\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q041","number":41,"year":"Deneme 01","subject":"Organik Kimya","stem":"CH₃Br ile OH⁻ tepkimesinde CH₃OH ve Br⁻ oluşuyor. Bu tepkimede nükleofil hangisidir?","options":[{"label":"A","text":"Ayrılan Br grubu","imageOnly":false,"image":null},{"label":"B","text":"Oluşan CH₃OH’nin metil karbonu","imageOnly":false,"image":null},{"label":"C","text":"C–Br bağının elektron kabul eden ucu","imageOnly":false,"image":null},{"label":"D","text":"CH₃Br’nin elektronca yoksul karbon merkezi","imageOnly":false,"image":null},{"label":"E","text":"OH⁻","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Nükleofil elektron çifti vererek elektronca yoksul karbona saldırır. Burada OH⁻ nükleofildir; brom ayrılan gruptur. Karbon atomu ise saldırıya uğrayan elektrofilik merkezdir.","topic":"Nükleofilik yer değiştirme","slideSources":[{"file":"Organik Kimya/5-Alkil Halojenur.pdf","pages":[4,5],"pageKind":"PDF sayfası","evidence":[{"page":4,"text":"Chapter 6\n4\n⧫Nucleophilic Substitution Reactions\n●In this reaction a nucleophile is a species with an unshared \nelectron pair which reacts with an electron deﬁcient carbon\n●A leaving group is substituted by a nucleophile\n●Examples of nucleophilic substitution\n"},{"page":5,"text":"Chapter 6\n5\n⧫Nucleophile\n●The nucleophile reacts at the electron deﬁcient carbon\n●A nucleophile may be any molecule with an unshared electron pair\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q042","number":42,"year":"Deneme 01","subject":"Organik Kimya","stem":"Benzer koşullarda halojenür iyonlarının ayrılan grup yeteneği için hangi sıralama genel olarak doğrudur?","options":[{"label":"A","text":"Cl⁻ > F⁻ > I⁻ > Br⁻","imageOnly":false,"image":null},{"label":"B","text":"I⁻ > Br⁻ > Cl⁻ > F⁻","imageOnly":false,"image":null},{"label":"C","text":"Br⁻ > F⁻ > Cl⁻ > I⁻","imageOnly":false,"image":null},{"label":"D","text":"Hepsi her koşulda aynı yetenektedir.","imageOnly":false,"image":null},{"label":"E","text":"F⁻ > Cl⁻ > Br⁻ > I⁻","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Daha kararlı ve daha zayıf baz olan anyonlar daha iyi ayrılan gruptur. Halojenürlerde genel sıra I⁻ > Br⁻ > Cl⁻ > F⁻ şeklindedir; florür güçlü C–F bağı ve bazlık özellikleri nedeniyle genellikle zayıf ayrılan gruptur.","topic":"Ayrılan grup","slideSources":[{"file":"Organik Kimya/5-Alkil Halojenur.pdf","pages":[6,7],"pageKind":"PDF sayfası","evidence":[{"page":6,"text":"Chapter 6\n6\n⧫Leaving Group\n●A leaving group is a substituent that can leave as a relatively \nstable entity\n●It can leave as an anion or a neutral species\n"},{"page":7,"text":"Chapter 6\n7\n●The Nature of the Leaving Group\n●The best leaving groups are weak bases which are relatively \nstable\n●\nThe leaving group can be an anion or a neutral molecule\n●Leaving group ability of halides:\n●This trend is opposite to basicity:\n●Other very weak bases which are good leaving groups:\n●The poor leaving group hydroxide can be changed into the good \nleaving group water by protonation\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q043","number":43,"year":"Deneme 01","subject":"Organik Kimya","stem":"NH₃ molekülü BF₃’e ortaklanmamış elektron çiftini vererek bağ oluşturuyor. Lewis tanımına göre rolleri hangisidir?","options":[{"label":"A","text":"Lewis asidi mutlaka OH⁻ vermelidir.","imageOnly":false,"image":null},{"label":"B","text":"Elektron aktarımı olmadığı için asit-baz tepkimesi değildir.","imageOnly":false,"image":null},{"label":"C","text":"NH₃ asit, BF₃ bazdır.","imageOnly":false,"image":null},{"label":"D","text":"NH₃ baz, BF₃ asittir.","imageOnly":false,"image":null},{"label":"E","text":"Her ikisi yalnızca proton vericisidir.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Lewis bazı elektron çifti verici, Lewis asidi elektron çifti alıcıdır. NH₃ çiftini verir; elektronca eksik BF₃ kabul eder. Lewis tanımı için proton alışverişi zorunlu değildir.","topic":"Asit-baz tanımları","slideSources":[{"file":"Organik Kimya/6-Asit ve Bazlar.pdf","pages":[5,7],"pageKind":"PDF sayfası","evidence":[{"page":5,"text":"Chapter 3 \n5\n⧫Introduction to Acid-Base Chemistry\n●Brønsted-Lowry Deﬁnition of Acids and Bases\n●Acid: a substance that can donate a proton\n●Base: a substance that can accept a proton\n●Example\n●\nHydrogen chloride is a very strong acid and essentially all hydrogen chloride \nmolecules transfer their proton to water\n"},{"page":7,"text":"Chapter 3 \n7\n●Lewis Deﬁnition of Acids and Bases\n●Lewis Acid: electron pair acceptor\n●Lewis Base: electron pair donor\n●Curved arrows show movement of electrons to form and break \nbonds\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q044","number":44,"year":"Deneme 01","subject":"Organik Kimya","stem":"Bir kovalent bağ kırılırken bağ elektronlarından birini bir atom, diğerini öteki atom alıyor. Bu kırılma nasıl adlandırılır?","options":[{"label":"A","text":"Rezonans","imageOnly":false,"image":null},{"label":"B","text":"Protonasyon","imageOnly":false,"image":null},{"label":"C","text":"Homolitik kırılma","imageOnly":false,"image":null},{"label":"D","text":"Heterolitik kırılma","imageOnly":false,"image":null},{"label":"E","text":"Hidrojenasyon","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Homolizde bağdaki elektronlar eşit paylaşılır ve radikal merkezler oluşur. Heterolizde iki bağ elektronu da aynı tarafa gider; iyon oluşumu söz konusu olabilir.","topic":"Bağ kırılması","slideSources":[{"file":"Organik Kimya/6-Asit ve Bazlar.pdf","pages":[3],"pageKind":"PDF sayfası","evidence":[{"page":3,"text":"Chapter 3 \n3\n●Rearrangements\n⧫Cleavage of Covalent Bonds\n●Homolysis\n●Heterolysis\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q045","number":45,"year":"Deneme 01","subject":"Organik Kimya","stem":"(CH₃)₃C–OH bileşiği, OH taşıyan karbonun bağlarına göre hangi alkol sınıfındadır?","options":[{"label":"A","text":"Primer alkol","imageOnly":false,"image":null},{"label":"B","text":"Tersiyer alkol","imageOnly":false,"image":null},{"label":"C","text":"Aldehit","imageOnly":false,"image":null},{"label":"D","text":"Fenol","imageOnly":false,"image":null},{"label":"E","text":"Sekonder alkol","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"OH’nin bağlı olduğu karbon üç başka karbona bağlıdır; dolayısıyla tersiyerdir. Sınıflama moleküldeki toplam karbon sayısına değil, OH taşıyan karbonun karbon komşularına göre yapılır.","topic":"Alkol sınıflandırması","slideSources":[{"file":"Organik Kimya/7-Alkol.pdf","pages":[3],"pageKind":"PDF sayfası","evidence":[{"page":3,"text":"Chapter 2 \n3\n●Alcohols\n●In alcohols the hydrogen of the alkane is replaced by the hydroxyl \n(-OH) group\n●\nAn alcohol can be viewed as either a hydroxyl derivative of an alkane or an alkyl \nderivative of water\n●Alcohols are also classiﬁed according to the carbon the hydroxyl \nis directly attached to\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q046","number":46,"year":"Deneme 01","subject":"Organik Kimya","stem":"Benzer mol kütleli etanol ve dimetil eter karşılaştırıldığında etanolün kaynama noktasının daha yüksek olmasının temel nedeni hangisidir?","options":[{"label":"A","text":"Dimetil eter moleküllerinin birbirlerine etanolden daha güçlü hidrojen bağı vermesi","imageOnly":false,"image":null},{"label":"B","text":"Etanolün daha az polar olması nedeniyle dipol çekiminin zayıflaması","imageOnly":false,"image":null},{"label":"C","text":"Etanol moleküllerinin kendi aralarında hidrojen bağı kurabilmesi","imageOnly":false,"image":null},{"label":"D","text":"Her iki bileşiğin de kendi arasında eşit sayıda hidrojen bağı kurması","imageOnly":false,"image":null},{"label":"E","text":"Etanol molekülleri arasında yalnızca London kuvvetleri bulunması","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Etanol O–H grubu sayesinde kendi molekülleri arasında hidrojen bağı oluşturabilir. Eterin oksijeni hidrojen bağı kabul edebilse de eter moleküllerinde uygun O–H vericisi yoktur; saf dimetil eter kendi arasında bu tür hidrojen bağı ağı kurmaz.","topic":"Hidrojen bağı ve kaynama","slideSources":[{"file":"Organik Kimya/7-Alkol.pdf","pages":[9],"pageKind":"PDF sayfası","evidence":[{"page":9,"text":"Chapter 11\n9\n⧫Physical Properties of Alcohols and Ethers\n●Ether boiling points are roughly comparable to hydrocarbons of \nthe same molecular weight\n●\nMolecules of ethers cannot hydrogen bond to each other\n●Alcohols have considerably higher boiling points \n●\nMolecules of alcohols hydrogen bond to each other\n●Both alcohols and ethers can hydrogen bond to water and have \nsimilar solubilities in water\n●\nDiethyl ether and 1-butanol have solubilites of about 8 g per 100 mL in water  \n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q047","number":47,"year":"Deneme 01","subject":"Organik Kimya","stem":"Düzlemsel, halkalı ve kesintisiz konjuge bir sistemde 6 π elektronu bulunuyor. Hückel kuralına göre en uygun yorum hangisidir?","options":[{"label":"A","text":"Düzlemsel olması tek başına aromatik olduğunu kanıtlar.","imageOnly":false,"image":null},{"label":"B","text":"Kesintisiz konjugasyon, aromatikliği engelleyen bir özelliktir.","imageOnly":false,"image":null},{"label":"C","text":"4n koşulunu n=1 için sağladığından antiaromatiktir.","imageOnly":false,"image":null},{"label":"D","text":"4n+2 koşulunu n=1 için sağladığından aromatik olabilir.","imageOnly":false,"image":null},{"label":"E","text":"6 π elektronu 4n+2 koşulunu hiçbir tam sayı n için sağlamaz.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Aromatiklik için halkalı, düzlemsel ve kesintisiz konjugasyon yanında 4n+2 π elektronu koşulu aranır. Altı elektron için 4×1+2=6 elde edilir. Yalnızca elektron sayısı, diğer yapısal koşullar olmadan yeterli değildir.","topic":"Hückel kuralı","slideSources":[{"file":"Organik Kimya/8-Aromatik Bileşikler.pdf","pages":[9,10],"pageKind":"PDF sayfası","evidence":[{"page":9,"text":"Chapter 14\n9\n⧫Huckel’s kuralı\n●4n+2π electron\n●Düzlemsel yapı\n"},{"page":10,"text":"Chapter 14\n10\n●Aromatik, Antiaromatik, Aromatik olmayan Bileşikler\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q048","number":48,"year":"Deneme 01","subject":"Organik Kimya","stem":"Benzen halkasının tipik elektrofilik tepkimelerinde katılma yerine yer değiştirme ürünlerinin sık görülmesinin temel nedeni hangisidir?","options":[{"label":"A","text":"Yer değiştirme sonunda aromatik sistemin yeniden kurulabilmesi","imageOnly":false,"image":null},{"label":"B","text":"Benzendeki tüm C–C bağlarının iyonik olması","imageOnly":false,"image":null},{"label":"C","text":"Yer değiştirmede hiçbir bağın kırılmaması","imageOnly":false,"image":null},{"label":"D","text":"Halkanın yalnızca tek karbon atomundan oluşması","imageOnly":false,"image":null},{"label":"E","text":"Benzende hiçbir π elektronunun bulunmaması","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Elektrofilik aromatik sübstitüsyonda ara basamakta aromatiklik geçici olarak bozulur; proton ayrılmasıyla yeniden kazanılır. Kalıcı katılma ise aromatik sistemin kaybına yol açacağından bu kararlılık tercihleri etkiler.","topic":"Aromatik sübstitüsyon","slideSources":[{"file":"Organik Kimya/8-Aromatik Bileşikler.pdf","pages":[13],"pageKind":"PDF sayfası","evidence":[{"page":13,"text":"Chapter 15\n13\n⧫Electrophilic Aromatic Substitution\n●Arene (Ar-H) is the generic term for an aromatic hydrocarbon\n●\nThe aryl group (Ar)  is derived by removal of a hydrogen atom from an arene\n●Aromatic compounds undergo electrophilic aromatic substitution \n(EAS)\n●\nThe electrophile has a full or partial positive charge\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q049","number":49,"year":"Deneme 01","subject":"Organik Kimya","stem":"CH₃CH₂CHO ve CH₃COCH₃ için doğru sınıflama sırasıyla hangisidir?","options":[{"label":"A","text":"Keton ve aldehit","imageOnly":false,"image":null},{"label":"B","text":"Alkol ve eter","imageOnly":false,"image":null},{"label":"C","text":"Amid ve amin","imageOnly":false,"image":null},{"label":"D","text":"Aldehit ve keton","imageOnly":false,"image":null},{"label":"E","text":"Karboksilik asit ve ester","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"İlk bileşikte karbonil karbonuna bir H bağlıdır: propanal, bir aldehittir. İkincide karbonil karbonu iki karbon grubuna bağlıdır: propanon, bir ketondur.","topic":"Karbonil sınıflandırması","slideSources":[{"file":"Organik Kimya/2-Fonksiyonel Gruplar.pdf","pages":[17],"pageKind":"PDF sayfası","evidence":[{"page":17,"text":"Chapter 2 \n17\n●Aldehydes and Ketones\n●Both contain the carbonyl group\n●Aldehydes have at least one carbon attached to the carbonyl group\n●Ketones have two organic groups attached to the carbonyl group\n●The carbonyl carbon is sp2 hybridized \n●\nIt is trigonal planar and has bond angle about 120o\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q050","number":50,"year":"Deneme 01","subject":"Organik Kimya","stem":"Asetik asidin etanolden daha asidik olması, konjuge bazlar karşılaştırıldığında en iyi nasıl açıklanır?","options":[{"label":"A","text":"Etanolün konjuge bazı pozitif yüklüdür.","imageOnly":false,"image":null},{"label":"B","text":"Asetat iyonunda oksijen bulunmaz.","imageOnly":false,"image":null},{"label":"C","text":"Asetat iyonundaki negatif yük iki oksijen arasında rezonansla kararlılaşır.","imageOnly":false,"image":null},{"label":"D","text":"Asetik asit hiç proton kaybedemez.","imageOnly":false,"image":null},{"label":"E","text":"Etoksitte negatif yük iki oksijen arasında dağılır.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Asetatın iki eşdeğer rezonans katkısı negatif yükü iki oksijen arasında delokalize eder. Etoksitte benzer bir rezonans kararlılığı yoktur. Konjuge bazın kararlılaşması asidin proton verme eğilimini artırır.","topic":"Karboksilik asitlerin asitliği","slideSources":[{"file":"Organik Kimya/10-Karboksilik Asitler.pdf","pages":[6],"pageKind":"PDF sayfası","evidence":[{"page":6,"text":"Chapter 18\n6\n●Acidity of Carboxylic Acids\n●The carboxyl proton of most carboxylic acids has a pKa = 4 - 5\n●\nCarboxylic acids are readily deprotonated by sodium hydroxide or sodium \nbicarbonate to form carboxylate salts\n●\nCarboxylate salts are more water soluble than the corresponding carboxylic acid \n●Electron-withdrawing groups near the carboxyl group increase the \ncarboxylic acid’s acidity\n●\nThey stabilize the carboxylate anion by inductive delocalization of charge\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q051","number":51,"year":"Deneme 01","subject":"Organik Kimya","stem":"CH₃COOCH₂CH₃ bileşiğinin uygun adı hangisidir?","options":[{"label":"A","text":"Etil etanoat (etil asetat)","imageOnly":false,"image":null},{"label":"B","text":"Metil propanoat","imageOnly":false,"image":null},{"label":"C","text":"Etil metanoat","imageOnly":false,"image":null},{"label":"D","text":"Etanamid","imageOnly":false,"image":null},{"label":"E","text":"Propil etanoat","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Esterin oksijene bağlı alkil kısmı etildir; asit kökenli CH₃COO– kısmı etanoattır. Ester adında önce alkil, sonra karboksilat kısmı belirtilir.","topic":"Ester adlandırma","slideSources":[{"file":"Organik Kimya/10-Karboksilik Asitler.pdf","pages":[7],"pageKind":"PDF sayfası","evidence":[{"page":7,"text":"Chapter 18\n7\n●Esters\n●The names of esters are derived from the names of the \ncorresponding carboxylic acid and alcohol from which the ester \nwould be made\n●\nThe alcohol portion is named ﬁrst and has the ending -yl\n●\nThe carboxylic acid portion follows and its name ends with -ate or -oate\n●Esters cannot hydrogen bond to each other and therefore have \nlower boiling points than carboxylic acids\n●\nEsters can hydrogen bond to water and have appreciable water solubility\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q052","number":52,"year":"Deneme 01","subject":"Tıp Tarihi ve Etik","stem":"Tarih öncesi bir kafatasında trepanasyon deliği çevresinde kemik iyileşmesi görülüyor. Bu bulgudan en güvenli hangi sonuç çıkarılır?","options":[{"label":"A","text":"İyileşme dokusu, deliğin ölümden sonra açıldığını kanıtlar.","imageOnly":false,"image":null},{"label":"B","text":"Tek örnekten bütün trepanasyonların başarılı olduğu anlaşılır.","imageOnly":false,"image":null},{"label":"C","text":"Bulgudan kişinin ameliyat sırasında öldüğü kesinleşir.","imageOnly":false,"image":null},{"label":"D","text":"Kişi işlemden sonra kemik iyileşmesine yetecek bir süre yaşamıştır.","imageOnly":false,"image":null},{"label":"E","text":"İşlemin kesinlikle epilepsi için yapıldığı kanıtlanmıştır.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Kemik yenilenmesi işlem sonrası yaşamı destekleyen doğrudan kanıttır. Ancak ameliyatın amacı, anestezi yöntemi ve bütün hastaların sonucu tek bir kafatasından kesinleştirilemez; kanıt ile yorum ayrılmalıdır.","topic":"Tarihsel kanıtın yorumlanması","slideSources":[{"file":"Tıp Tarihi ve Etik/1-Giriş Tarih Öncesi Zaman.pdf","pages":[17,18,19],"pageKind":"PDF sayfası","evidence":[{"page":17,"text":"PREHİSTORİK DÖNEMDE \nCERRAHİ\n• Arkeologların keşfettiği diğer bir \nçeşit buluntu kafataslarında delikler \nolan tarih öncesi insan kalıntılarıdır.\n• Bu uygulamaya trepanasyon\ndenmektedir.\n• Kafataslarında bu uygulamanın \nbaşarılı olduğuna dair bazı işaretler \nbulunuyordu. \nTrephined skull of Neolithic period\nNationalmuseet, Kopenhagen\n"},{"page":18,"text":"• Arkeologlar, birçok delinmiş \nkafatasında, hastanın prosedürden sağ \nkaldığını gösteren kemik rejenerasyonu\nkanıtı gördüler. \n• Yani deliğin kenarındaki yara izi, bize bu \nameliyattan sonra bazı kişilerin epey bir \nsüre yaşadığını göstermektedir. \n• Ek olarak, vakaların çoğunda enfeksiyon \nbelirtisi yoktu, bu yüzden enfeksiyonları \nönleyecek yöntemleri bildikleri \ndüşünülmektedir\n"},{"page":19,"text":"TREPENASYON\n• Peki bu uygulamayı neden yapıyorlardı, \ntarih öncesi insanlar bu tehlikeli ve zor \noperasyonu neden gerçekleştirmiş \nolabilirlerdi? \n• İskeletler bize her şeyi anlatmaz ve bazen \narkeolojik kanıtları yorumlamak zor \nolabilmektedir. \n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q053","number":53,"year":"Deneme 01","subject":"Tıp Tarihi ve Etik","stem":"Mezopotamya’da bir görevli hastaya bitkisel ilaç hazırlayıp uygularken, diğeri kötü ruhları uzaklaştırmaya yönelik ritüel yürütüyor. Bu rollerin eşleştirilmesi hangisidir?","options":[{"label":"A","text":"İlaç uygulayan Bârû; ritüel yürüten Asû","imageOnly":false,"image":null},{"label":"B","text":"İlaç uygulayan Asklepios; ritüel yürüten Susruta","imageOnly":false,"image":null},{"label":"C","text":"İlaç uygulayan Asipu; ritüel yürüten Bârû","imageOnly":false,"image":null},{"label":"D","text":"İlaç uygulayan Galenos; ritüel yürüten Asû","imageOnly":false,"image":null},{"label":"E","text":"İlaç uygulayan Asû; ritüel yürüten Asipu","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Slaytta Asû farmakolojik uygulamalarla, Asipu büyü ve ritüellerle, Bârû ise kehanetle ilişkilendirilir. Bu sınıflama dönemin tıbbi ve dinsel rollerinin birlikte var olduğunu gösterir.","topic":"Mezopotamya hekimleri","slideSources":[{"file":"Tıp Tarihi ve Etik/2-Mezopotamya.pptx","pages":[8],"pageKind":"Slayt","evidence":[{"page":8,"text":"Hekim Tipleri: Bârû, Asû ve Asipu\nMezopotamya’da tıp tek bir meslek değil, üç uzmanlık alanının ortaklığıdır: \nBârû\n (kehanet yapan; karaciğer falı kullanır), \nAsû \n(ilaç hazırlayan ve uygulayan; bitkisel-farmakolojik bilgiye sahip) ve \nAsipu \n(büyü ve ritüellerle uğraşan). Bir vaka çoğu zaman bu üç disiplinin birlikte çalışmasını gerektirir.\nBârû\nKehanet, karaciğer falı, ritüel prognostik değerlendirme.\nAsû\nİlaç hazırlama, merhem ve şurup uygulamaları, klinik gözlem.\nAsipu\nBüyüsel ritüeller, kötücül ruhları kovma, koruyucu tılsımlar."}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q054","number":54,"year":"Deneme 01","subject":"Tıp Tarihi ve Etik","stem":"Hammurabi Kanunları’nda cerrahi işlemin sonucuna göre ücret ve ceza belirlenmesi, öncelikle hangi alanın tarihsel gelişimine örnektir?","options":[{"label":"A","text":"Tedavi sonuçlarının toplumsal statüden bütünüyle bağımsız olması","imageOnly":false,"image":null},{"label":"B","text":"Tıbbi hataların yalnızca mikrobiyolojik nedenlerle açıklanması","imageOnly":false,"image":null},{"label":"C","text":"Hekimin yalnızca meslektaşlar tarafından değerlendirilmesi","imageOnly":false,"image":null},{"label":"D","text":"Modern aydınlatılmış onamın bütün unsurlarıyla uygulanması","imageOnly":false,"image":null},{"label":"E","text":"Hekimin mesleki sorumluluğunun hukuken düzenlenmesi","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Hammurabi düzenlemeleri hekimlik faaliyetini ücret ve yaptırımlarla ilişkilendirir. Bu, mesleki sorumluluğun tarihine örnektir; günümüzün adalet, eşitlik ve tıbbi kusur ölçütleriyle birebir aynı sistem değildir.","topic":"Tıbbi sorumluluğun tarihi","slideSources":[{"file":"Tıp Tarihi ve Etik/2-Mezopotamya.pptx","pages":[11],"pageKind":"Slayt","evidence":[{"page":11,"text":"Hammurabi Kanunları: Tıbbi Sorumluluk ve Hukuk\nMÖ 18. yüzyılda Hammurabi Kanunları doktorların mesleki sorumluluklarını düzenler. Başarılı cerrah ücret alırken, başarısızlık ağır cezalarla sonuçlanabilirdi (örneğin, soylu bir hastanın ölümünde cerrahın cezası sertti). Bu düzenlemeler tıpta hukuksal sorumluluk fikrinin erken örneğidir.\nÖdül ve Ceza\nBaşarı durumunda ücret; başarısızlık halinde fiziksel cezalar veya mal tazminatı.\nProfesyonel\n \nStandart\nHekimliğin toplum tarafından düzenlenmesi ve mesleki beklentilerin yazılı hale gelmesi."}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q055","number":55,"year":"Deneme 01","subject":"Tıp Tarihi ve Etik","stem":"Antik Mısır tıbbını inceleyen bir araştırmacı, Mezopotamya’nın kil tabletleri yerine hangi kaynak grubunu öncelikle kullanmalıdır?","options":[{"label":"A","text":"Regimen Sanitatis Salernitanum’u","imageOnly":false,"image":null},{"label":"B","text":"On dokuzuncu yüzyıl bakteriyoloji kültür kayıtlarını","imageOnly":false,"image":null},{"label":"C","text":"De Motu Cordis’i","imageOnly":false,"image":null},{"label":"D","text":"De Humani Corporis Fabrica’yı","imageOnly":false,"image":null},{"label":"E","text":"Ebers ve Edwin Smith gibi tıbbi papirüsleri","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Mısır tıbbının temel yazılı kaynakları tıbbi papirüslerdir. Ebers ve Edwin Smith bu gruptadır. Diğer eserler daha sonraki Avrupa tıbbının kaynaklarıdır.","topic":"Eski tıp kaynakları","slideSources":[{"file":"Tıp Tarihi ve Etik/2-Mezopotamya.pptx","pages":[15],"pageKind":"Slayt","evidence":[{"page":15,"text":"Mısır Tıbbı — Kaynaklar ve Papirüsler\nMısır tıbbının ana kaynakları \ntıbbi papirüsler\ndir. \nAntik\n \nMısır\n \ntıbbında\n \nen\n \nçok\n \nöne\n \nçıkan\n \niki\n \nkaynak\n \nEbers\n \nve\n \nEdwin Smith \npapirüsleridir\n.\nPapirüsler \ncerrahi, tanı, reçete ve ritüelleri\n içerir.\nEdwin Smith Cerrahi Papirüsü en bilimsel olanıdır (yaralar, kırıklar, kafa travmaları ayrıntılı). Ebers Papirüsü ~250 hastalık ve 875 reçete ile geniş bir kodekstir\nBazı vakalarda:\n“Tedavi edilebilir”\n“Mücadele edilebilir”\n“Tedavi edilemez”\nşeklinde sınıflandırma yapılmıştır.\nBu, erken klinik karar verme örneğidir."}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q056","number":56,"year":"Deneme 01","subject":"Tıp Tarihi ve Etik","stem":"Hint tıbbında cerrahi aletler, ameliyat teknikleri ve burun rekonstrüksiyonu üzerine çalışan bir öğrenci hangi isimle en doğrudan karşılaşır?","options":[{"label":"A","text":"Galenos","imageOnly":false,"image":null},{"label":"B","text":"Caraka","imageOnly":false,"image":null},{"label":"C","text":"William Harvey","imageOnly":false,"image":null},{"label":"D","text":"Robert Koch","imageOnly":false,"image":null},{"label":"E","text":"Susruta","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Susruta cerrahi uygulamalar ve rinoplastiyle öne çıkar; Caraka daha çok iç hastalıkları ve klinik sınıflamayla ilişkilidir. Sorunun belirleyici ipucu cerrahidir.","topic":"Hint tıbbı","slideSources":[{"file":"Tıp Tarihi ve Etik/2-Mezopotamya.pptx","pages":[30,31],"pageKind":"Slayt","evidence":[{"page":30,"text":"Büyük Hekimler: Caraka ve Susruta\nCaraka\nİç hastalıkları ve klinik sınıflama\n600'den fazla ilaç tarifi\nHastalık nedenlerini doğal faktörlere bağlar\nSusruta\nAntik dünyanın en büyük cerrahi ustası\n121 cerrahi alet tanımlamıştır\nKatarakt, rinoplasti ve sezaryen operasyonları"},{"page":31,"text":"Cerrahinin Zirvesi: Susruta'nın Mirası\nAmeliyatlar\nMesane taşı, katarakt, tonsillektomi, sezaryen ve rinoplasti (burun rekonstrüksiyonu)\nTeknik Düzey\n121 farklı cerrahi alet tarif edilmiş; anestezik olarak \nalkol\n kullanılmıştır\nTarihsel Önemi\nAntik dünyada herhangi bir medeniyetle kıyaslanabilir en ileri cerrahi sistemdir"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q057","number":57,"year":"Deneme 01","subject":"Tıp Tarihi ve Etik","stem":"Bir hekim epilepsiyi yalnızca kutsal bir ceza olarak görmek yerine doğal nedenlerini ve hastanın çevresini araştırıyor. Bu tutum hangi dönüşümü en iyi temsil eder?","options":[{"label":"A","text":"Kan dolaşımının nicel olarak hesaplanmasını","imageOnly":false,"image":null},{"label":"B","text":"Bütün hastalıklarda yalnızca kehaneti yeterli saymayı","imageOnly":false,"image":null},{"label":"C","text":"Hastalığın nedenlerini araştırmayı gereksiz gören yaklaşımı","imageOnly":false,"image":null},{"label":"D","text":"Hastalığı doğal nedenlerle açıklamaya yönelen Hipokratik yaklaşımı","imageOnly":false,"image":null},{"label":"E","text":"Mikroorganizmaların kültürde gösterilmesini","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Hipokratik geleneğin önemli yönü hastalıkları doğaüstü açıklamalarla sınırlamayıp doğal nedenler, gözlem ve çevre bağlamında ele almaktır. Bu yaklaşım, modern mikrop teorisinin zaten bilindiği anlamına gelmez.","topic":"Hipokratik yaklaşım","slideSources":[{"file":"Tıp Tarihi ve Etik/3-Antik Yunan.pptx","pages":[9,10,11],"pageKind":"Slayt","evidence":[{"page":9,"text":"Hippokrates\nDoğum ve Eğitim\nM.Ö. 460'ta Kos adasında doğdu. Asklepios soyundan gelen bir hekim ailesine mensuptu.\nKatkıları\nAkla ve deneye dayalı bir sistem kurdu. Tabiatüstü sebepler yerine tabiî sebepler.\nTeoriden çok klinik gözlem.\nHipokratik\n \nKülliyat\n, \nfarklı\n \ndönemlere\n \nait\n \nyaklaşık\n \naltmış\n \neserden\n \noluşur\n.\nMezopotamya\n, Mısır ve Yunan tıp bilgisini sistemleştirmiştir\nHekimlik ahlakının temellerini attı.\nHumoral Patoloji Teorisi"},{"page":10,"text":"Hippokrates'in Öğretileri\nTabiat Hekimdir\nİnsanın \nt\nabiat\nı\n \nhastalıkların hekimidir. Hekimin görevi tabiatın iyileştirici gücüne yardımcı olmaktır.\nGözlem ve Teşhis\nHastalıkların sebeplerini araştırarak tedavi etmek \ngerektiğini\n \nsavundu\n.\nKoruyucu Hekimlik\nSadece tedavi değil, sağlık koşulları konusunda da bilgilendirme yaptı\n\"Hekimlikte esas hastaya zarar vermemektir.\""},{"page":11,"text":"Hip\np\nokrat\nes’in\n önemi\n1. Hastalığın doğallaştırılması:\nE\npilepsi\n \nörneği\n \nmükemmel\n. \nEpilepsinin\n “\nkutsal\n” \nolduğu\n \niçin\n \ndeğil\n, \ndoğal\n \nbir\n \nhastalık\n \nolduğu\n \niçin\n \naraştırılması\n \ngerektiğini\n \nsavunuyor\n.\nÖnemli soru: «\nBir\n \nhastalığın\n \ntanrısal\n \ndeğil\n \ndoğal\n \nolduğunu\n \nsöylemek\n, \nyalnızca\n \nhastalığın\n \nnedenini\n mi \ndeğiştirir\n, \nyoksa\n \nkimin\n \nhastalık\n \nhakkında\n \nkonuşma\n \nyetkisine\n \nsahip\n \nolduğunu\n da \nmı\n \ndeğiştirir\n?”\n \nR\nahipten\n \nhekime\n epistemik \n‘\notorite\n’\n \nkayması\n.\n2. \nH\nastalıktan \nçok hastaya \nbakmak\n: \nHippokratik\n \nyaklaşımda mevsim, coğrafya, beslenme, yaşam biçimi, kişinin bünyesi ve hastalığın seyri önem taşıyor\n.\n3. \nPrognoz\n:\nHekimin değeri yalnız hastalığa isim vermesinde değil, hastalığın nasıl seyredeceğini öngörebilmesinde yatıyor."}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q058","number":58,"year":"Deneme 01","subject":"Tıp Tarihi ve Etik","stem":"Tarihsel humoral kurama göre kan, balgam, sarı safra ve kara safranın dengesi hangi kavramla ilişkilendirilir?","options":[{"label":"A","text":"Antibiyotik etki spektrumu","imageOnly":false,"image":null},{"label":"B","text":"DNA replikasyonunun doğruluğu","imageOnly":false,"image":null},{"label":"C","text":"ABO kan gruplarının kalıtımı","imageOnly":false,"image":null},{"label":"D","text":"Koch postülalarının karşılanması","imageOnly":false,"image":null},{"label":"E","text":"Sağlık durumu","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Humoral kuram sağlığı dört hıltın dengesi, hastalığı bu dengenin bozulmasıyla açıklar. Bu tarihsel açıklama güncel fizyolojik mekanizma veya tedavi önerisi değildir.","topic":"Humoral patoloji","slideSources":[{"file":"Tıp Tarihi ve Etik/3-Antik Yunan.pptx","pages":[12],"pageKind":"Slayt","evidence":[{"page":12,"text":"Humoral Patoloji Teorisi\nEvrenin dört unsuru (su, toprak, hava, ateş) insan vücudunda dört sıvı olarak bulunur. Bu sıvıların dengesi sağlık, dengesizliği hastalık yaratır.\nKan\nSıcak-yaş. İlkbaharda artar. Kalp ve akciğerlerde bulunur.\nBalgam\nSoğuk-yaş. Kışın artar. Beyinde bulunur.\nSafra\nSıcak-kuru. Yazın artar. Karaciğerde bulunur.\nKara Safra\nSoğuk-kuru. Sonbaharda artar. Dalakta bulunur."}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q059","number":59,"year":"Deneme 01","subject":"Tıp Tarihi ve Etik","stem":"Roma’da su kemerleri, kanalizasyon ve askerî sağlık örgütlenmesi birlikte değerlendirildiğinde hangi özellik öne çıkar?","options":[{"label":"A","text":"Roma’da hastalıkların yalnızca yeni kuramlarla önlenmesi","imageOnly":false,"image":null},{"label":"B","text":"Sağlığın altyapı ve kurumsal organizasyonla desteklenmesi","imageOnly":false,"image":null},{"label":"C","text":"Sağlık kurumlarının şehir yaşamıyla ilişkisiz olması","imageOnly":false,"image":null},{"label":"D","text":"Bireysel hekimliğin altyapıdan tamamen bağımsız değerlendirilmesi","imageOnly":false,"image":null},{"label":"E","text":"Sağlık hizmetlerinin bütünüyle tapınak içi ritüellere indirgenmesi","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Roma örneğinde su ve kent altyapısı ile askerî sağlık kurumları, sağlık tarihinin yalnızca yeni teorilerden oluşmadığını gösterir. Kurumsal hizmet ve organizasyon da önemli katkılardır.","topic":"Roma ve toplum sağlığı","slideSources":[{"file":"Tıp Tarihi ve Etik/4-Antik Yunan ve Roma.pptx","pages":[18,19,20,27],"pageKind":"Slayt","evidence":[{"page":18,"text":"Roma'nın Bilimsel Yaklaşımı\nPratik Odaklılık\nTeorik\n \nkonulara\n (Yunanlar kadar)\n \nilgi duymadılar. \nYapısal\n \nBaşarılar\n (önemli)\nYol, köprü, \nsu\n \nkemerleri\n, hamamlar\n \ninşa ettiler. \nÖzgün Teori Yok\nMezopotamya, Mısır ve Yunan bilgilerine sahip olmalarına rağmen özgün teori geliştiremediler.\nBugün\n \nsağlık\n \nkurumu\n \ndeyince\n \nhastane\n \ndüşünüyoruz\n.\n \nRoma’da \nise\n: hamam\n, kaplıca, askeri \nhastane, \nAsklepieionlar\n farklı \nsağlık \nmekanlarıdır\n."},{"page":19,"text":"Tıp tarihi yalnızca keşiflerin tarihi değildir; kurumların, altyapının ve organizasyonun da tarihidir."},{"page":20,"text":"S\nağlık\n \nartık\n \nsadece\n \nbireysel\n hasta-\nhekim\n \nilişkisinden\n \nibaret\n \ndeğil\n. \nOn \nbinlerce\n \naskerin\n, \nbüyük\n \nkentlerin\n, \nyolların\n, \ngarnizonların\n \nve\n \nnüfus\n \nhareketlerinin\n \nyönetilmesi\n \ngerekiyor\n.\nÖnemli soru: \nBinlerce\n \nkişilik\n \nbir\n \norduyu\n \nsavaşabilir\n \nhalde\n \ntutmak\n \ntıbbi\n \nbir\n \nmesele\n \nmidir\n?\nYara tedavisi, enfeksiyon, temiz su, beslenme, dinlenme, salgınlar, askeri hastaneler\n...\nYani\n tıp \nartık\n \nyalnızca\n:\n “Hasta bireyi iyileştirmek\n” değil;\n \n     \n“\nbir\n \nnüfusu\n \nişlevsel\n \nhalde\n \ntutmak\n” \nmeselesi\n \nhaline\n \ngeliyor\n."},{"page":27,"text":"Roma Tıbbının Mirası\nYunan Bilgilerini Koruma\nYunan tıbbi eserlerini koruyup sonraki kuşaklara aktarma\nKurumsal Sağlık\nAskeri hastaneler ve sağlık birlikleri kurma\nYazılı Miras\nDe Medicina, Materia Medica gibi eserlerin Avrupa'da etkisi\n\"Nereye gidersek gidelim, ayaklarımızın altında Romalıların döşediği yolları buluruz.\""}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q060","number":60,"year":"Deneme 01","subject":"Tıp Tarihi ve Etik","stem":"Antik tıp eserlerinin farklı dillerde çevrilmesi, yorumlanması ve yeni terimlerle işlenmesi nasıl değerlendirilmelidir?","options":[{"label":"A","text":"Yalnızca sözcüklerin mekanik biçimde değiştirilmesi olarak","imageOnly":false,"image":null},{"label":"B","text":"Bilginin aktarılırken aynı zamanda dönüştürüldüğü bir süreç olarak","imageOnly":false,"image":null},{"label":"C","text":"Antik bilginin hiçbir zaman okunmadığının kanıtı olarak","imageOnly":false,"image":null},{"label":"D","text":"Tıbbi gözlemin bütün medeniyetlerde yasak olması olarak","imageOnly":false,"image":null},{"label":"E","text":"Matbaa öncesinde bilgi aktarımının imkânsızlığı olarak","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Slaytlar Cündişapur ve İslam medeniyetindeki çeviri ağlarını yalnızca koruma değil, yeni bilimsel dil ve yorum geliştirme süreci olarak ele alır. Çeviri, kavram ve bilgi üretimine de katkı yapar.","topic":"Bilginin aktarılması","slideSources":[{"file":"Tıp Tarihi ve Etik/5-Ortacagdan-Ronesansa-Avrupa-Tibbi.pptx","pages":[6,7,8],"pageKind":"Slayt","evidence":[{"page":6,"text":"Antik \ndünyanın tıbbi bilgisi Roma İmparatorluğu'nun \nçözülmesinden \nsonra nereye \ngitti?\nFarklı \nmedeniyetler bu bilgiyi nasıl dönüştürdü\n?\nBilgi nereden nereye dolaştı?\n\nİskenderiye, \nCündişapur\n, Bağdat, Şam, Kahire, \nKurtuba\n, \nToledo\n, \nSalerno\n gibi merkezler.\nKimler \ntaşıdı?\n\nYunan, Süryani, Müslüman, Yahudi ve Hıristiyan mütercimler; hekimler; tüccarlar; saraylar; kütüphaneler\n.\nBilgi \nyeni yere geldiğinde ne oldu?\n\nTercüme edildi, yorumlandı, eleştirildi, öğretildi ve yeni kurumlarda kullanıldı\n.\n* Bilginin \ndolaşımı yalnız \ncoğrafi bir \nhareket değildir; aynı zamanda \nepistemik\n dönüşümdür."},{"page":7,"text":"Antik \ndünyanın tıbbi bilgisi Roma İmparatorluğu'nun \nçözülmesinden \nsonra nereye \ngitti?\nFarklı \nmedeniyetler bu bilgiyi nasıl dönüştürdü\n?\nİlk önemli durak: \nCündişapur\n\nİslam fetihleriyle birlikte Müslüman siyasi hâkimiyeti, zaten mevcut olan İskenderiye, \nCündişapur\n, \nEdessa\n/Urfa ve benzeri bilim merkezlerini içine aldı\n.\nAğırlık \nBağdat'a kayıyor\n\nTercüme \nfaaliyetleri, \nBeyt’ül\n \nhikme\n. \nAMA \nbir \nbilgi altyapısı gerekiyor.\n        Metin \n+ dil bilen insan + para + siyasi himaye + kütüphane + eğitim ortamı + metni kullanacak uzmanlar.\nHuneyn\n b. \nİshak (önemli figür)\n\nMetni \nbulmak gerekiyor; hangi nüshanın güvenilir olduğunu belirlemek gerekiyor; Yunanca/Süryanice/Arapça arasında kavramsal karşılıklar üretmek gerekiyor; başka hekimlerin kullanabileceği bir tıp dili ortaya çıkarmak gerekiyor."},{"page":8,"text":"Antik \ndünyanın tıbbi bilgisi Roma İmparatorluğu'nun \nçözülmesinden \nsonra nereye \ngitti?\nFarklı \nmedeniyetler bu bilgiyi nasıl dönüştürdü\n?\nTercüme \n= kelime değiştirme değildir\n\nBu süreçte yeni bir bilimsel terminoloji ortaya çıkıyor. Dolayısıyla, \ntercüme\n, bilginin yeniden kurulmasıdır\n.\nDolaşan bilgi yalnız Yunan bilgisi değil\n\nİslam medeniyetinin oluşturduğu Arapça bilim ortamında farklı \ndini \nve etnik topluluklardan âlimler antik ve geç antik bilgi geleneklerini Arapçaya taşıdılar\n.\nPeki neden tercüme yaptılar?\n\nSarayın \nhekimlere ihtiyacı var, hastaların tedavi edilmesi gerekiyor, ilaç bilgisinin sistemleştirilmesi gerekiyor, hekim yetiştirmek gerekiyor, hastaneler kuruluyor. T\nercüme \nhareketini yalnız “entelektüel merak” olarak \ndeğil.\nTercüme edildi, \npeki sonra\n?\n \n      Yaratıcı \ndönem: gözlem, deney ve yeni tıbbi bilgilerle bu mirasın \ngeliştirilmesi\n: \nRâzî\n, \nİbn\n \nSînâ\n, \nZehrâvî\n, \nİbn\n \nZühr\n, \nİbnü'n-Nefîs"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q061","number":61,"year":"Deneme 01","subject":"Tıp Tarihi ve Etik","stem":"Vesalius’un anatomi çalışmalarında otorite metniyle kadavra gözlemi çeliştiğinde doğrudan gözleme ağırlık vermesi neden dönüştürücüdür?","options":[{"label":"A","text":"Geleneksel anatomik bilgiyi insan diseksiyonuyla sınamayı mümkün kıldığı için","imageOnly":false,"image":null},{"label":"B","text":"Kan gruplarını keşfettiği için","imageOnly":false,"image":null},{"label":"C","text":"Antiseptik cerrahiyi başlattığı için","imageOnly":false,"image":null},{"label":"D","text":"Mikroorganizmaların DNA’sını dizilediği için","imageOnly":false,"image":null},{"label":"E","text":"Gözlemi tamamen dışlayıp yalnızca ezberi güçlendirdiği için","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Vesalius insan kadavralarını doğrudan inceleyerek Galenik anatominin bazı yanlışlarını sorguladı. Yenilik, otoriteyi gözlemle sınamaktır; kan grupları ve antisepsi başka dönem ve kişilere aittir.","topic":"Anatomide yöntem değişimi","slideSources":[{"file":"Tıp Tarihi ve Etik/5-Ortacagdan-Ronesansa-Avrupa-Tibbi.pptx","pages":[12],"pageKind":"Slayt","evidence":[{"page":12,"text":"Andreas Vesalius: Modern Anatominin Babası\n1\n1543\nDe Humani Corporis Fabrica - çığır açan eser\n2\nGalen'in yanlış bilgilerini düzeltiyor.\n3\nDisseksiyon masalarına insan kadavrası getiriyor"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q062","number":62,"year":"Deneme 01","subject":"Tıp Tarihi ve Etik","stem":"Harvey’in kalbin pompaladığı kan miktarını hesaplayarak kanın sürekli yeniden üretildiği düşüncesini sorgulaması hangi yöntemi öne çıkarır?","options":[{"label":"A","text":"Hastalıkları yıldızların konumuna bağlamayı","imageOnly":false,"image":null},{"label":"B","text":"Nicel gözlem ve deneyle kuramı sınamayı","imageOnly":false,"image":null},{"label":"C","text":"Yalnızca eski otoritelerin metnini tekrar etmeyi","imageOnly":false,"image":null},{"label":"D","text":"Klinik gözlemleri sayısal veriden tamamen ayırmayı","imageOnly":false,"image":null},{"label":"E","text":"Kemik rejenerasyonundan ameliyat amacını kesin belirlemeyi","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Harvey dolaşımı açıklarken gözlem ve nicel değerlendirmeyi kullandı. Kalbin pompaladığı miktar üzerine akıl yürütmek, sürekli üretim-tüketim modelinin sorgulanmasına ve dolaşım fikrine destek verdi.","topic":"Dolaşımın açıklanması","slideSources":[{"file":"Tıp Tarihi ve Etik/5-Ortacagdan-Ronesansa-Avrupa-Tibbi.pptx","pages":[14],"pageKind":"Slayt","evidence":[{"page":14,"text":"William Harvey: Kan Dolaşımı\n20 Yıllık Araştırma\nGalenus'un 1500 yıllık teorisini çürütmek\n1628: De Motu Cordis\nKan dolaşımını kantitatif metotlarla açıklamak\n1661: Malphighi\nKılcal damarları keşfediyor"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q063","number":63,"year":"Deneme 01","subject":"Tıp Tarihi ve Etik","stem":"Bir tarih dersinde “el temizliğiyle lohusa ateşinden ölümleri azaltma” ve “fenol kullanarak cerrahi enfeksiyonları azaltma” örnekleri veriliyor. Doğru isim sırası hangisidir?","options":[{"label":"A","text":"Semmelweis ve Lister","imageOnly":false,"image":null},{"label":"B","text":"Koch ve Hipokrat","imageOnly":false,"image":null},{"label":"C","text":"Lister ve Semmelweis","imageOnly":false,"image":null},{"label":"D","text":"Jenner ve Galenos","imageOnly":false,"image":null},{"label":"E","text":"Harvey ve Vesalius","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Semmelweis doğum servisinde el temizliğinin önemini gösterdi. Lister karbolik asit (fenol) ile antiseptik cerrahi uygulamalar geliştirdi. Benzer hedefe yönelik olsalar da örnekler farklı kişilere aittir.","topic":"Enfeksiyon kontrolü","slideSources":[{"file":"Tıp Tarihi ve Etik/7-19. Yüz Yıl.pdf","pages":[11,12,13,18,19],"pageKind":"PDF sayfası","evidence":[{"page":11,"text":"ENFEKSİYON FİKRİ\n• Mikroplar mikroskopla gözlemlenmesine \nrağmen enfeksiyonların nedeni bilinmiyordu. \n• Ignaz Semmelweis (1818-1865), kirlilik ve \nenfeksiyonlar arasındaki ilişkiyi ilk \ngözlemleyen isim oldu. \n• Viyana Genel Hastanesi kadın doğum \nservisinde doktor olarak çalışırken, tıp \nöğrencilerinin eğitim gördüğü servislerden \nbirinde yıllık anne ölüm oranının yüzde \n10'un üzerinde olduğunu ve bazı aylarda bu \noranın neredeyse yüzde yirmiye ulaştığını \nfark etti. Genellikle de ölüm sebebi lohusa \nhummasıydı. \n• Ancak sadece ebelerin çalıştığı diğer serviste \nölüm oranı daha düşüktü. \n"},{"page":12,"text":"• Kadınlar çoğunlukla ebelerin gözetiminde değil doktorların \ngözetimindeyken ölüyordu. \n• Bu nedenle lohusa ateşinin yayılmasında doktorların rolü olduğu \nkanaatine vardı.\n• Bunun sebebini düşündü ve gözlemler yaptı. \n• Tıp öğrencilerinin otopsi sonrası ellerini yıkamadan kliniğe \ngeldiklerini ve hastalara bu kirli ellerle baktıklarını fark etti. Bu \nyüzden, doktorların hastalığı cesetlerden hastalara taşıdıklarını \ndüşündü. \n• Bu hipotezi test etmek için, sorumlu doktorların ve öğrencilerin \nkliniğe veya koğuşa girmeden önce ellerini sabun ve suyla \nyıkamalarını, klorlu solüsyona batırmalarını ve bunu her muayeneden \nönce tekrar etmelerini istedi. \n"},{"page":13,"text":"• Ignaz Semmelweiss, hastalarını \ntedavi etmeden önce doktorların \nellerini yıkamasını sağlayarak \n1847'de doğum servisindeki ölüm \noranını düşürdü. \n• Böylece, lohusa ateşinin el \nyıkayarak önlenebileceğini ispat \netti\n"},{"page":18,"text":"• Pasteur, şarapların bozulmasına havayla temas sırasında mikropların \netki etmesinin yol açtığını ispatlayınca Lister kendi arayışıyla bir \nbağlantı kurdu\n• Yaralardaki enfeksiyonlar kendiliğinden ortaya çıkıyorsa, onları \niyileştirmek için yapılabilecek hiçbir şey olmadığını biliyordu. Ancak \nenfeksiyon yaralara dışardan giren mikroplar nedeniyle gelişiyorsa \nönlenebilmeleri için bir umut vardı\n"},{"page":19,"text":"• Lister, bir süredir karbolik asidin (fenol) kanalizasyonda bulunan parazitleri \ngüvenli bir şekilde öldürmek için kullanıldığını duymuştu. \n• Böylece cerrahi aletlerini, ellerini ve yara sargılarını yıkamak için seyreltilmiş bir \nkarbolik asit formülasyonu kullanmaya karar verdi. \n• Ayrıca mikropları ortadan kaldırmak için ameliyathanedeki havaya karbolik asit \nkarışımı püskürtmeye başladı\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q064","number":64,"year":"Deneme 01","subject":"Tıp Tarihi ve Etik","stem":"Jenner’in vaksinasyon uygulamasını önceki insan çiçeği kaynaklı variolasyondan ayıran temel özellik hangisidir?","options":[{"label":"A","text":"İnsan çiçeği lezyonunu her durumda daha yüksek dozda kullanması","imageOnly":false,"image":null},{"label":"B","text":"İnek çiçeği materyalinden yararlanması","imageOnly":false,"image":null},{"label":"C","text":"Antibiyotik kullanması","imageOnly":false,"image":null},{"label":"D","text":"Hastaya doğrudan fenol uygulaması","imageOnly":false,"image":null},{"label":"E","text":"Kan gruplarını eşleştirmesi","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Slaytta variolasyon insan çiçeği materyaliyle, Jenner’in vaksinasyonu ise inek çiçeği materyaliyle ilişkilendirilir. Bu ayrım aşı tarihinin temel noktalarındandır; antibiyotik ve kan grubu eşleştirmesiyle ilgili değildir.","topic":"Variolasyon ve vaksinasyon","slideSources":[{"file":"Tıp Tarihi ve Etik/6-Rönesans.pdf","pages":[52,53],"pageKind":"PDF sayfası","evidence":[{"page":52,"text":"TIBBİ KEŞİFLER\n• 18. yüzyılın en önemli tıbbi keşiflerinden biri çiçek aşısıdır. \n• Çiçek hastalığı o dönemde Avrupa’da en ölümcül \nhastalıklardan biriydi. \n• İngiltere'nin Osmanlı Büyükelçisinin eşi Leydi Mary Montagu\n(1689-1762), Osmanlı Devleti'nde çiçek hastalığını önlemek \niçin bir çeşit aşılama kullanıldığını gözlemledi.\n• Osmalıdaki aşıcı kadınlar hasta kişilerin çiçek lezyonlarındaki \npüstüllerden bir miktar alıp, sağlıklı çocukların derisinde \naçtıkları bir çiziğin içine serpiyorlar ve böylece bir aşılama \nyapıyorlardı: variyolasyon tipi aşılama \n• Leydi Mary Montagu gözlemlediği bu uygulamayı 1717 \nyılında İngilteredeki arkadaşına yazdığı mektupta anlatarak \ntanıttı\nLady Mary Montagu is in \nOttoman costume\n"},{"page":53,"text":"• İngiliz hekim Edward Jenner (1749-1823) variyolasyon tipi çiçek \naşısından yola çıkarak vaksinasyon tipi çiçek aşısını geliştirdi\n• Vaksinasyonun variyolasyondan farkı insanlardan alınan püstüller \nyerine hayvanlardan alınan püstüllerin kullanılmasıdır.\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q065","number":65,"year":"Deneme 01","subject":"Histoloji ve Embriyoloji","stem":"Bir dokuda hücresel enzimlere bağlı otolizi ve bakteriyel bozulmayı sınırlandırıp morfolojiyi korumayı amaçlayan işlem hangisidir?","options":[{"label":"A","text":"Dehidrasyon","imageOnly":false,"image":null},{"label":"B","text":"Mikrotomi","imageOnly":false,"image":null},{"label":"C","text":"Fiksasyon","imageOnly":false,"image":null},{"label":"D","text":"Montaj","imageOnly":false,"image":null},{"label":"E","text":"Şeffaflandırma","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Fiksasyon dokuyu canlıdaki yapısına yakın biçimde korumayı ve bozulmayı durdurmayı hedefler. Dehidrasyon suyu uzaklaştırır, şeffaflandırma gömme ortamına geçişi sağlar, mikrotomi kesit alma işlemidir.","topic":"Fiksasyonun amacı","slideSources":[{"file":"Histoloji/1-Histolojide Çalışma Metodları.pdf","pages":[16,17],"pageKind":"PDF sayfası","evidence":[{"page":16,"text":"              Fiksasyon (Tespit) \n■Dokuların enzimler tarafından otolizisini \nönlemek \nveya \nbakteriler \ntarafından \nparçalanmasını önlemek ve fizyolojik \nyapıyı korumak için organ-doku parçaları \nalınır alınmaz hemen kimyasal işleme \nalınmalıdır.\n■ Canlıdakine en yakın şekliyle hücre ve \ndokuların bu şekilde korunması işlemine \n“fiksasyon (tespit)” denir.\n■Dokuları muhafaza eden, fikse eden \nkimyasal \nmaddelere \n“fiksatif” \ndenilmektedir. \n"},{"page":17,"text":"Fiksasyon işlemi\n■Amaç:\n■l-Otolizi ve bakteriyel bozulma ve çürümeyi önlemek \nveya durdurmak\n■2-Kolaylıkla diffüzyon olan maddelerin kaybını \nönlemek\n■3-Kesit hazırlama basamaklarındaki sağlığa zararlı \nkötü etkilere karşı dokuyu kuvvetlendirmek (Örnek \ndehidrasyon, şeffaflandırma, parafine gömme gibi)\n■4-Dokuyu boyalarla ve diğer reaktiflerle diferensiyel \nboyamayı kolaylaştıran bir    duruma getirmek\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q066","number":66,"year":"Deneme 01","subject":"Histoloji ve Embriyoloji","stem":"Rutin parafin takibinde fiksasyondan sonra suyun uzaklaştırılması ve ardından parafinle uyumlu ara ortama geçilmesi hangi sıraya karşılık gelir?","options":[{"label":"A","text":"Montaj → fiksasyon → kesit alma","imageOnly":false,"image":null},{"label":"B","text":"Şeffaflandırma → dehidrasyon → fiksasyon","imageOnly":false,"image":null},{"label":"C","text":"Parafine gömme → fiksasyon → dehidrasyon","imageOnly":false,"image":null},{"label":"D","text":"Dehidrasyon → şeffaflandırma → parafine gömme","imageOnly":false,"image":null},{"label":"E","text":"Kesit alma → gömme → fiksasyon","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Parafin suyla karışmadığından doku önce alkollerle susuzlaştırılır. Ardından alkolün yerini parafinle uyumlu şeffaflandırıcı alır; sonra gömme yapılır. Sıralama bu fizikokimyasal uyuma dayanır.","topic":"Doku takibinin mantığı","slideSources":[{"file":"Histoloji/1-Histolojide Çalışma Metodları.pdf","pages":[15,24,30],"pageKind":"PDF sayfası","evidence":[{"page":15,"text":"Mikrotomla kesitleri \nalınan dokuların takibi\n■Fiksasyon\n■Dehidrasyon\n■Şeffaflandırma\n■Bloklama\n■Kesit alma\n■Kesitlerin boyanması\n■Monte\n"},{"page":24,"text":"              Doku Takibi\n■Mikrotomla ince kesitler (5-10 μm) alabilmek için \ndokular, fiksasyondan sonra sert bir kıvam veren \ngömme maddelerinin içerisine yerleştirilir. Bunu \niçin önce fikse olan dokular;\n■Dehidrasyon \n(yoğunluğu \nartan \n% \n50-70-80-90-100 alkol serileri),\n■Şeffaflandırma=saydamlaştırma \n(gömme \nmateryali ile karışabilen bir çözücü; parafin \ngömme materyali için Ksilen),\n■EM için Propilen oksit ile infiltrasyon ve oda \nsıcaklığında sertleşen Plastik resin içine gömme.\n"},{"page":30,"text":"             Gömme\n■Işık mikroskobu (IM)’nda 59-60° C’da \netüvde sıvı parafinde bekletme ve \ngömme.\n■IM’da gömme materyali=Parafin\n■EM’da plastik resinler: Epon, Araldit, \nVestopal\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q067","number":67,"year":"Deneme 01","subject":"Histoloji ve Embriyoloji","stem":"Protein sentezi yüksek bir hücrede ribozomlardan zengin bölgelerin H&E ile mavi-mor görünmesi en iyi nasıl açıklanır?","options":[{"label":"A","text":"Bütün boyalar bütün hücre bileşenlerini aynı renge boyar.","imageOnly":false,"image":null},{"label":"B","text":"Mavi renk hücrede kesinlikle DNA bulunmadığını gösterir.","imageOnly":false,"image":null},{"label":"C","text":"RNA’nın asidik grupları hematoksilenle bazofilik boyanma oluşturur.","imageOnly":false,"image":null},{"label":"D","text":"Eozin nükleik asitleri seçici olarak maviye boyar.","imageOnly":false,"image":null},{"label":"E","text":"Ribozomlar yalnızca nötral yağ içerir.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Nükleik asitlerin fosfat grupları asidiktir. Ribozomal RNA’dan zengin bölgeler bu nedenle bazofili gösterir ve hematoksilenle mavi-mor görünür. Eozin ise proteinlerden zengin yapılarda pembe tonlar oluşturur.","topic":"Bazofili","slideSources":[{"file":"Histoloji/1-Histolojide Çalışma Metodları.pdf","pages":[53,54,62,67],"pageKind":"PDF sayfası","evidence":[{"page":53,"text":"Kimyalarına göre         \nsınıflandırma\n❑ \nDokuda \nbazik \nyapılar \nasit \nboyalarla, asit yapılar bazik \nboyalarla boyanırlar.\n❑ Bazik \nboyalarla \nboyanan \nyapılara \nBazofil Yapılar (bazofilik);\n❑ Asit \nboyalarla \nboyanan \nkısımlara \nAsidofil \nYapılar \n(eozinofilik, \nasidofilik) denir.\n"},{"page":54,"text":"   Bazik Boyalar\n■İyonize \nolan \nve \nbazik \nboyalarla \nreaksiyona \ngiren \ndokuların ana komponentleri \nyapılarında \nnukleoproteinler \nve glikozaminoglikanlar gibi \nasitleri içerirler.\n■Bazik \nboyalara \nörnekler: \nHematoksilen, \nToluidin \nmavisi, Metilen mavisi \n"},{"page":62,"text":"Hematoksilen ve Eosin \n(H&E)\n■En çok kullanılan rutin boyama \nyöntemidir.\n■Hematoksilen nukleusu ve RNA’dan \nzengin organeller içeren asidik yapıları \nmaviye boyar.\n■Eosin ise hücrenin sitoplazmasını ve bağ \ndokusu ara maddesine ait olan kollajen \nlifleri pembeye boyar.\n"},{"page":67,"text":"Hematoxvlin and eosin (H&E) En yaygın laboratuvar \nboyasıdır. \nHematoksilen mavi/mor bir boyadır; eozin kırmızıdır. \nNükleer kromatin, yüksek bir nükleik asit içeriğine \nsahiptir ve bu nedenle mavi, daha bazik boyayla (yani \nbazofiliktir) boyanır.\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q068","number":68,"year":"Deneme 01","subject":"Histoloji ve Embriyoloji","stem":"Bir histokimyasal yöntemde periyodik asitle aldehit grupları açığa çıkarılıyor ve Schiff ayıracıyla renk elde ediliyor. Hangi yöntem tanımlanmıştır?","options":[{"label":"A","text":"H&E boyaması","imageOnly":false,"image":null},{"label":"B","text":"PAS reaksiyonu","imageOnly":false,"image":null},{"label":"C","text":"Demirli hematoksilen","imageOnly":false,"image":null},{"label":"D","text":"Gram boyaması","imageOnly":false,"image":null},{"label":"E","text":"Gümüş impregnasyonu","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"PAS, periodic acid–Schiff yöntemidir. Uygun karbohidrat gruplarının oksidasyonuyla oluşan aldehitler Schiff ayıracıyla reaksiyona girer. Glikojen ve bazı glikokonjugatlar gibi yapıları göstermede kullanılır.","topic":"PAS reaksiyonu","slideSources":[{"file":"Histoloji/1-Histolojide Çalışma Metodları.pdf","pages":[88,89,93],"pageKind":"PDF sayfası","evidence":[{"page":88,"text":"PAS REAKSİYONU\n■Vücutta \nproteine \nbağlanmayan \nve \nvücudun her yerinde yaygın olarak \nbulunan bir polisakkartit olan glikojen \nPAS reaksiyonu ile gösterilebilir. Bu \ntekikle doku ve hücrelerde bulunan \naldehit grupları gösterilebilir. \n■Dokularda \nglikojeni \nve \nGAG \nları \n(mukopolisakkaritleri) \ndepolayan \nhastalıklara sahip hastalardan  alınan \ndokuların \nbiyopsilerinde \n \nPAS \nreaksiyonu rutin olarak kullanılır.\n"},{"page":89,"text":"PAS REAKSİYONU\n■Bu reaksiyonda öncelikle,  periyodik \nasitle okside edilen dokulardaki aldehit \ngrupları açığa çıkarılır. Daha sonra \nAldehid grupları Schiff ayracı ile \nreaksiyona girer ve magenta renkli \nbileşiği oluşturur.\n"},{"page":93,"text":"Periyodik asit-Schiff reaksiyonunun bir \nörneğidir. \nPAS boyası karbohidratlara özeldir. Bu \nyöntemde glikol grupları asidin etkisiyle \nreaktif aldehitlere dönüştürülür; ve Schiff \nReaktifi onları parlak magenta rengine \nboyar.\n \nPolisakkaritler bu yöntemle çok güçlü bir \nşekilde boyanır. Bu görüntüdeki kırmızı \nnoktalar, \nkadeh \nhücrelerinin \nmüsin \ndamlacıklarıdır. \nPAS reaksiyonu, teşhis çalışmalarında \n(H&E'den sonra) en sık kullanılan ikinci \nboyadır. \nKarbonhidratların dağılımı genellikle bir \ndokunun ve parçası olduğu organların \ndoğası hakkında önemli bir ipucudur.\nGoblet hücreleri, PAS\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q069","number":69,"year":"Deneme 01","subject":"Histoloji ve Embriyoloji","stem":"Rutin parafin takibi sonrasında dokudaki nötral yağların yerinde boşluklar görülmesi, hangi yorumla en iyi açıklanır?","options":[{"label":"A","text":"Eozinin bütün lipitleri fiziksel olarak çoğaltmasıyla","imageOnly":false,"image":null},{"label":"B","text":"Her boşluğun mutlaka canlı bir bakteri olmasıyla","imageOnly":false,"image":null},{"label":"C","text":"Yağların tamamının çekirdek DNA’sına dönüşmesiyle","imageOnly":false,"image":null},{"label":"D","text":"Dokuda başlangıçta kesinlikle hiç lipit bulunmamasıyla","imageOnly":false,"image":null},{"label":"E","text":"Lipitlerin takip sırasında organik çözücülerle uzaklaşmış olmasıyla","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Organik çözücüler lipitleri çözerek uzaklaştırabilir; bu nedenle parafin kesitte boş görünüm, başlangıçta yağ bulunmadığını kanıtlamaz. Bu soru görüntü tanıma değil, preparatın nasıl yorumlanacağını belirleyen kuramsal ilkeyi sorgular.","topic":"Histolojik yöntemin sınırları","slideSources":[{"file":"Histoloji/1-Histolojide Çalışma Metodları.pdf","pages":[37],"pageKind":"PDF sayfası","evidence":[{"page":37,"text":"Mikrotomlar\n■\nDondurma \nmikrotomu \nve \nKriyostat: \n■\nParafin mikrotomuyla kesitleri \nalınan \ndokuların \ntakibinde \nkullanılan şeffaflandırıcı Ksilen \nlipitleri eritir. \n■\nBu olayı önlemek için bu özel \nmikrotomlar kullanılır.\n■\nDuyarlı \nenzimler \nve \nmoleküllerin \nhistokimyasal \nçalışmasında kullanılır. \n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q070","number":70,"year":"Deneme 01","subject":"Histoloji ve Embriyoloji","stem":"Aynı dalga boyunda çalışan iki ışık mikroskobundan birinde sayısal açıklık (NA) daha yüksektir. Diğer koşullar uygunsa hangi sonuç beklenir?","options":[{"label":"A","text":"NA artışı yalnızca görüntünün fiziksel boyutunu büyütür.","imageOnly":false,"image":null},{"label":"B","text":"Ayırt edilebilir minimum mesafe artar ve ayrıntı kaybı olur.","imageOnly":false,"image":null},{"label":"C","text":"Işığın dalga boyu NA ile aynı oranda zorunlu olarak artar.","imageOnly":false,"image":null},{"label":"D","text":"Birbirine daha yakın iki nokta ayrı seçilebilir.","imageOnly":false,"image":null},{"label":"E","text":"Büyütme değişmezse çözünürlük hiçbir koşulda değişemez.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Çözünürlük sınırı yaklaşık olarak dalga boyuyla doğru, NA ile ters orantılıdır. NA yükselince ayırt edilebilir en küçük mesafe azalır; bu, daha iyi çözünürlük demektir. Büyütme tek başına bu sınırı aşamaz.","topic":"Çözünürlük","slideSources":[{"file":"Histoloji/2-Mikroskop Eğitimi.pdf","pages":[68,69,71],"pageKind":"PDF sayfası","evidence":[{"page":68,"text":"68\nÇözünürlük (Rezolüsyon)\n• Bir optik sistemin incelenen örneğin\n    detaylarını gösterebilme kapasitesidir.\n"},{"page":69,"text":"69\nÇözünürlük ve büyütmeyi sınırlayan \nfaktörler\nNA= (n) sin(U)\nn:Lamelle objektif arasındaki ortamın kırılma indeksi\nU: Merceğin optik ekseni ile merceğe giren en dış ışık \nışını arasındaki açı\nn hava: 1.00\nn su: 1.30\nn immersiyon yağı: 1.50\n- Sayısal açıklık (NA)\n- Işığı kırma katsayısı (n)\n- Işığın dalga boyu (λ)\n- Optik sapmalar\nNA değeri ne kadar büyükse,\nayırdetme gücü/çözünürlük o kadar artar.\n"},{"page":71,"text":"Optimum Çözünürlük\n\u0000 Mümkün olan en yüksek NA ‘lıobjektif lens \nkullanılmalı \n\u0000 Yüksek büyütme kullanılmalı \n\u0000 Objektif lens ile uyumlu oküler seçilmeli \n\u0000 Mümkün en kısa dalgaboyu kullanılmalı \n\u0000 Işık sistemini tam merkezde tutulmalı \n\u0000 Mümkünse yağ ortamlı lensler kullanılmalı \n\u0000 En iyi çözünürlük için parlaklık ayarlanmalı\n71\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q071","number":71,"year":"Deneme 01","subject":"Histoloji ve Embriyoloji","stem":"Bir görüntü daha büyük gösteriliyor; ancak daha önce birleşik görünen iki nokta hâlâ birbirinden ayrılamıyor. Hangi yorum doğrudur?","options":[{"label":"A","text":"Çözünürlük yalnızca oküler büyütmesinin sayısal değeridir.","imageOnly":false,"image":null},{"label":"B","text":"Büyütme artmış olabilir; çözünürlüğün arttığı gösterilmemiştir.","imageOnly":false,"image":null},{"label":"C","text":"İki noktanın ayrılamaması görüntünün hiç büyütülmediğini kanıtlar.","imageOnly":false,"image":null},{"label":"D","text":"Görüntüyü büyütmek dalga boyuna bağlı sınırlamayı ortadan kaldırır.","imageOnly":false,"image":null},{"label":"E","text":"Her büyütme artışı aynı oranda çözünürlük artışı sağlar.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Büyütme görüntünün boyutunu, çözünürlük ise yakın ayrıntıların ayrı seçilebilmesini anlatır. Çözümleme sınırı iyileşmeden büyütme artırılması yeni ayrıntı kazandırmayabilir.","topic":"Büyütme ve çözümleme","slideSources":[{"file":"Histoloji/2-Mikroskop Eğitimi.pdf","pages":[68,69,71],"pageKind":"PDF sayfası","evidence":[{"page":68,"text":"68\nÇözünürlük (Rezolüsyon)\n• Bir optik sistemin incelenen örneğin\n    detaylarını gösterebilme kapasitesidir.\n"},{"page":69,"text":"69\nÇözünürlük ve büyütmeyi sınırlayan \nfaktörler\nNA= (n) sin(U)\nn:Lamelle objektif arasındaki ortamın kırılma indeksi\nU: Merceğin optik ekseni ile merceğe giren en dış ışık \nışını arasındaki açı\nn hava: 1.00\nn su: 1.30\nn immersiyon yağı: 1.50\n- Sayısal açıklık (NA)\n- Işığı kırma katsayısı (n)\n- Işığın dalga boyu (λ)\n- Optik sapmalar\nNA değeri ne kadar büyükse,\nayırdetme gücü/çözünürlük o kadar artar.\n"},{"page":71,"text":"Optimum Çözünürlük\n\u0000 Mümkün olan en yüksek NA ‘lıobjektif lens \nkullanılmalı \n\u0000 Yüksek büyütme kullanılmalı \n\u0000 Objektif lens ile uyumlu oküler seçilmeli \n\u0000 Mümkün en kısa dalgaboyu kullanılmalı \n\u0000 Işık sistemini tam merkezde tutulmalı \n\u0000 Mümkünse yağ ortamlı lensler kullanılmalı \n\u0000 En iyi çözünürlük için parlaklık ayarlanmalı\n71\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q072","number":72,"year":"Deneme 01","subject":"Histoloji ve Embriyoloji","stem":"Salgı proteini üretimi yüksek bir hücrede granüllü ER’nin gelişmiş olmasının temel nedeni hangisidir?","options":[{"label":"A","text":"Üzerindeki ribozomların salgı yoluna girecek proteinleri sentezlemesi","imageOnly":false,"image":null},{"label":"B","text":"Granüllü ER’nin esas işlevinin nötral yağ depolanması olması","imageOnly":false,"image":null},{"label":"C","text":"Salgı proteinlerinin yalnızca serbest ribozomlarda tamamlanıp Golgi’ye doğrudan geçmesi","imageOnly":false,"image":null},{"label":"D","text":"Ribozomların ER lümeninde DNA replikasyonu yapması","imageOnly":false,"image":null},{"label":"E","text":"Granüllü ER’nin steroid sentezinin tek merkezi olması","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Granüllü ER’nin sitozole bakan yüzündeki ribozomlar salgı ve endomembran sistemi proteinlerinin sentezine katılır. ER ayrıca katlanma ve bazı modifikasyonların başladığı yerdir; kendine ait bir genomu yoktur.","topic":"Granüllü ER","slideSources":[{"file":"Histoloji/3-Membranlı Organeller.pptx","pages":[14,15,16],"pageKind":"Slayt","evidence":[{"page":14,"text":"Granüllü \nEndoplazma\n Retikulum\nGranülü \nER’a\n ait kanalcık ve keseciklerin \nsitosole\n bakan yüzeylerinde aralıklarla oturmuş ribozom ve \npolizomlar\n bulunur.\nPolizomdakiler\n de dahil, tüm ribozomlar keseciklerin yüzeylerine büyük olan üniteleri aracılığı ile bağlanırlar.\nGranüllü ER boşluklarında görülen ve değişik türlerde olan proteinler \nmembranların\n yüzeylerindeki bu ribozom ve \npolizomlar\n tarafından sentezlenirler.\n Yapılan proteinlerin büyük çoğunluğu \nretikuluma\n ait keseciklerin boşluklarına geçer ve burada \nglobüler\n biçim kazanırlar.\nGeri kalanlar ise, \nsitosolde\n \nglobülleşerek\n yeniden \nşekilenmekte\n olan \norganellerin\n \nmembranlarında\n yapı malzemesi olarak kullanılırlar."},{"page":15,"text":"Granüllü \nEndoplazma\n Retikulum\nÜzerinde tüm transmembran proteinlerin sentezinden sorumlu olan ribozomları taşıyan GER  proteinlerin \nikincil ve üçüncül yapılarının katlandığı, birleştirildiği ve özel enzimlerle olgunlaştırıldığı organeldir. \nProtein sentezinde görevli olan hücrelerde\n GER daha yüksek oranlarda bulunmaktadır. \nProtein sentezi başladığında, GER genişler ve ribozomların işgal edeceği daha geniş yüzey alanı sağlayan dallanmış ER formuna dönüşmektedir. \nProtein sentezi sürecinde, yeni sentezlenen proteinler katlanmamış polipeptit zincirleri hâlinde ribozomdan çıkarak, \nER’nin\n derin \nsisternasına\n doğru itilmektedir. "},{"page":16,"text":"Granüllü \nEndoplazma\n Retikulum\n \nER’ye\n gelen yeni sentezlenmiş protein, çeşitli modifikasyonlara (N-glikozilasyon, disülfit oluşumu, hidroksilasyon, \noligomerizasyon\n) uğradıktan sonra katlanabilmektedir. \n Glikozilasyon sonucu \nproteine hidrofilik özellik kazandırılarak\n, sudaki \nçözünürlüğü arttırılmakta ve bir oligosakkaritin yardımıyla proteinin etrafını çevreleyen proteinlerle ilişkisi engellenmektedir. \nBöylece, bu oligosakkarit bir anlamda \n“\nşaperon\n” \nolarak görev yapmış olmaktadır.  Bu süreçler, özelleştirilmiş katlanma enzimleri ve \nşaperon\n proteinlerin yardımı ile gerçekleşmektedir."}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q073","number":73,"year":"Deneme 01","subject":"Histoloji ve Embriyoloji","stem":"Steroid hormon sentezleyen bir hücrede hangi organelin gelişmiş olması beklenir?","options":[{"label":"A","text":"Düz endoplazmik retikulum","imageOnly":false,"image":null},{"label":"B","text":"Nükleolus","imageOnly":false,"image":null},{"label":"C","text":"Primer lizozom","imageOnly":false,"image":null},{"label":"D","text":"Granüllü ER","imageOnly":false,"image":null},{"label":"E","text":"Erken endozom","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Düz ER lipit ve steroid metabolizmasıyla ilişkilidir. Granüllü ER ile karıştırılmamalıdır; üzerindeki ribozomlardan dolayı değil, membran enzimleri ve metabolik görevleri nedeniyle gelişmiştir.","topic":"Düz ER","slideSources":[{"file":"Histoloji/3-Membranlı Organeller.pptx","pages":[18,19,20],"pageKind":"Slayt","evidence":[{"page":18,"text":"Düz \nEndoplazmİK\n \nRetikulum\nAGER: \nGranülsüzdür\n. \nRibozomlara sahip olmamasıyla, \nGER’den\n ayrılır. \nÇevredeki \nsitoplazmik\n \nmatriksle\n aynı boyandığı için, ancak elektron mikroskobu altında görülebilirler. \nBunların \nmembranları\n düzgündür ve birbirleriyle irtibatı olan \ntübüler\n veya \nveziküler\n elemanlardan oluşmuşlardır. \nZar kalınlıkları, 6 – 7 nm, lümen genişliğiyse 50 nm kadardır. \nSER’de\n, lipit ve steroid yapısındaki hormonlar sentezlenmekte ve karbonhidrat metabolizması ve ilaç ve tüm diğer ksenobiyotiklerin biyotransformasyonu gerçekleşmektedir"},{"page":19,"text":"Düz \nEndoplazmİK\n \nRetikulum\nHer hücrede az yada çok miktarda bulunabilir.\nKaraciğer \nepitel\n \nhüc\n.,\nYağ bezleri ile \nsteroid\n hormon salgılayan iç salgı bezlerini oluşturan \nepitel\n \nhüc\n., ve kas \nhüc\n. de gelişmiş olarak bulunur. "},{"page":20,"text":"Düz \nEndoplazmİK\n \nRetikulum\nMidenin asit salgılayan hücresi asit salgılamayla ilgili olarak iyi gelişir.\nK.C DER kolesterol ,safra yapımı, zehirli maddelerin yok edilmeleri ve glikojenin değişim metabolizmasında rol alır.\n En önemli görevi; yağ asitlerini ve lipidleri sentezlemektir. \nSER’de\n, lipit ve steroid yapısındaki hormonlar sentezlenmekte ve karbonhidrat metabolizması ve ilaç ve tüm diğer ksenobiyotiklerin biyotransformasyonu gerçekleşmektedir.\nSteroid\n hormon salgılayan (\ntestis,ovaryum,böbreküstü\n bezlerinde)\nGranülsüz\n ER zengindir.\n Çizgili kas hücresinde \nsarkoplazmik\n \nretikulum\n olarak bilinir ve kasılma ve gevşemede rol alır.\nYağda eriyen ilaçların parçalanmasında (\ndetoksifikasyon\n) görev alan enzimler içerir. "}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q074","number":74,"year":"Deneme 01","subject":"Histoloji ve Embriyoloji","stem":"ER’de yanlış katlanmış proteinlerin birikmesine karşı UPR’nin ilk uyumsal amacı hangisidir?","options":[{"label":"A","text":"Her ER stresi durumunda uyumsal yanıt olmadan anında apoptoz başlatmak","imageOnly":false,"image":null},{"label":"B","text":"Yanlış katlanan proteinlerin tümünü hücre dışına doğrudan salgılamak","imageOnly":false,"image":null},{"label":"C","text":"ER’ye giren yeni protein yükünü sürekli artırmak","imageOnly":false,"image":null},{"label":"D","text":"Protein katlanma yükünü azaltıp ER’nin işleme kapasitesini yeniden dengelemek","imageOnly":false,"image":null},{"label":"E","text":"Katlanma kapasitesini azaltıp hatalı proteinlerin birikmesini hızlandırmak","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"UPR, yanlış katlanmış protein yüküne karşı sentez yükünü azaltma, katlanma kapasitesini artırma ve hatalı proteinleri uzaklaştırma gibi yanıtları koordine eder. Stres çözülemezse apoptoza giden yollar devreye girebilir.","topic":"ER stresi","slideSources":[{"file":"Histoloji/3-Membranlı Organeller.pptx","pages":[24,25,26],"pageKind":"Slayt","evidence":[{"page":24,"text":"ENDOPLAZMİK RETÜKULUM STRESİ VE İLİŞKİLİ HASTALIKLAR\n Bununla birlikte, güçlü ve uzun süreli hücresel \npertübasyonlar\n, aminoasit eksikliği, viral replikasyon, potansiyel toksisiteye sahip katlanmamış veya hatalı katlanmış proteinlerin varlığı gibi çok çeşitli koşullar ER homeostazını değiştirebilmekte ve \nER’de\n strese neden olabilmektedir. \nHücresel bir yanıt olan ER stresine karşı, organel normal işlevlerine dönmek için çeşitli stratejiler kullanarak \nfilogenetik\n olarak korunmuş, strese duyarlı bir sinyal yolağı olan \nUPR’yi\n aktive etmektedir.  \nUPR transkripsiyonel ve \ntranslasyonel\n olaylar zincirinin aktive olmasıyla gerçekleşen, hücresel stres ve ER stresi olduğunda ortaya çıkan koruyucu bir yanıttır. UPR, protein katlanma homeostazını ve proteinlerin düzgün işleyiş ve üretiminin ayarlanmasını sağlamaktadır."},{"page":25,"text":"ENDOPLAZMİK RETÜKULUM STRESİ VE İLİŞKİLİ HASTALIKLAR\nHatalı katlanmış proteinlerin birikiminin ve ER stresinin üstesinden gelmek için UPR yolağı aktive olmaktadır. \nEğer hatalı katlanmış protein miktarı çok fazla olur ve stres devam eder ise \nUPR’nin\n aktivasyonu ER stresiyle baş etmek için yetersiz kalabilmektedir. \nUzun süreli UPR aktivasyonunun ve \nER stres yanıtlarının oluşamamasının bir sonucu olarak, \notofajik\n programlar veya apoptoz aktivasyonu ile hücre ölümü gerçekleşebilmektedir\nKanser, diyabet, Alzheimer hastalığı gibi pek çok hastalık yanlış katlanan proteinlerle; damar sertliği ve obezite gibi birtakım hastalıklarda lipit metabolizmasıyla ilişkili olduğu için, ER tüm bu hastalıkların odağında yer almaktadır.  Bugün, ER stresinin tetiklediği birçok hastalık olduğu bilinmektedir. Bunların arasında nörodejeneratif hastalıkları, \niskemi\n/reperfüzyon hasarı nedeni ile ortaya çıkan hastalıkları ve metabolik hastalıkları (Tip 2 diyabet ve obezite) saymak mümkündür. "},{"page":26,"text":"ENDOPLAZMİK RETÜKULUM STRESİ VE İLİŞKİLİ HASTALIKLAR\nKronik ER stresi, insülin ve \nleptin\n direncine, inflamasyona, \nβ-\nhücrelerinin deformasyonuna ve apoptoza neden olarak obezite ve diyabet başta olmak üzere pek çok metabolik hastalığa yol açabilmektedir.\n ER stresi sonucu ektopik yağ depoları glukoz taşınımını ve insülin sinyallerini engellemekte ve insülindeki bu değişimle birlikte iskelet kasında yağ birikmektedir. \n \nLeptin\n, 16 \nkDa\n ağırlığında ve \nheliks\n yapıda bir protein olup, \nob\n geninin ürünüdür. \n \nLeptin\n, hipotalamustaki reseptörleri aracılığıyla yiyecek alımını ve enerji metabolizmasını negatif geri bildirim ile düzenlemekte ve obezite gelişimini engellemektedir. \nLeptinin\n plazma kolesterol, \ntrigliserid\n ve glukoz düzeyini azalttığı saptanmıştır. \nArtmış ER stres ve \nUPR’nin\n, obez farelerin hipotalamusunda \nleptin\n reseptör sinyalini inhibe ettiği gösterilmiştir. Son zamanlarda yapılan çalışmalarda, ER stresinin \nleptin\n direncine neden olarak obeziteye yol açtığı belirlenmiştir. \n Hem genetik, hem de diyete bağlı olarak geliştirilen obezite modellerinin hipotalamustaki ER stres protein ekspresyonlarının artışıyla ilişkili olduğu gösterilmiştir."}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q075","number":75,"year":"Deneme 01","subject":"Histoloji ve Embriyoloji","stem":"Bir hücrede çekirdek zarının iç yüzünü destekleyen nükleer lamina bozuluyor. Bu yapının temel proteinleri hangi hücre iskeleti ailesindendir?","options":[{"label":"A","text":"Mikrotübül motoru kinezinler","imageOnly":false,"image":null},{"label":"B","text":"Tübülin dimerleri","imageOnly":false,"image":null},{"label":"C","text":"Ara filaman ailesindeki laminler","imageOnly":false,"image":null},{"label":"D","text":"Aktin motoru miyozinler","imageOnly":false,"image":null},{"label":"E","text":"Aktin mikrofilamanları","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Nükleer lamina, iç çekirdek zarının altında destek ağı oluşturan laminlerden meydana gelir. Laminler ara filaman ailesindendir; aktin, tübülin ve motor proteinlerle karıştırılmamalıdır.","topic":"Nükleer lamina","slideSources":[{"file":"Histoloji/5-Sitoiskelet.ppt","pages":[138],"pageKind":"PPT metin kaydı (slayt numarası değildir)","evidence":[{"page":138,"text":"Lamina, Lamin proteinlerinden oluşur (Lamin A, Lamin B(1-2), Lamin C)\rLaminler araçapta filament ailesi üyesidir (60-80 kDa).\rLaminler birbiriyle bağlanarak önce ikili moleküller oluşturur daha sonra bunların da bir araya gelmesiyle ipliksi yapılar oluşur. \r• İpliksi proteinlerin yanyana düzenlenmesiyle nükleer laminanın kafesi andıran yapısı oluşur."}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q076","number":76,"year":"Deneme 01","subject":"Histoloji ve Embriyoloji","stem":"Bir sistem histolojik kesit görüntüsünü, hastanın klinik öyküsünü ve genetik raporunu birlikte değerlendiriyor. Bu yaklaşım nasıl adlandırılır?","options":[{"label":"A","text":"Yalnızca görüntü segmentasyonu","imageOnly":false,"image":null},{"label":"B","text":"Tek bir biyobelirtece dayalı eşikleme","imageOnly":false,"image":null},{"label":"C","text":"Çok modlu (multimodal) yapay zekâ","imageOnly":false,"image":null},{"label":"D","text":"Yalnızca görüntü boyutunun artırılması","imageOnly":false,"image":null},{"label":"E","text":"Tek modlu görüntü analizi","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Birbirinden farklı veri türlerinin birlikte kullanılması çok modlu yaklaşımdır. Burada görüntü, klinik metin ve genetik veri birleştirilir; yalnızca tek bir görüntünün büyütülmesiyle aynı işlem değildir.","topic":"Çok modlu yapay zekâ","slideSources":[{"file":"Histoloji/4-Histolojide Yapay Zeka.pptx","pages":[9,11],"pageKind":"Slayt","evidence":[{"page":9,"text":"YAPAY ZEKANIN TIPTA İŞLEDİĞİ TEMEL VERİ TİPLERİ\nMetin / Sayısal Veri\n: Hasta öyküsü, laboratuvar değerleri, \nESK \n(Elektronik Sağlık Kayıtları).\nGörsel Veri\n: Biyopsi slaytları (WSI), Röntgen, MR, BT, Ultrason (Bilgisayarlı Görü).\nSinyal Verisi\n: EKG, EEG, EMG kayıtları.\nOmik\n / Genetik Veri\n: DNA/RNA dizileme, \nProteomik\n."},{"page":11,"text":"ÇOK MODLU YZ NEDEN ŞART?\nİlke\n: Biyopsi görüntüsü + Hasta öyküsü + Genetik raporun aynı anda sentezlenmesi.\nAvantaj\n: Klinik kararda bütüncül bakış ve teşhis doğruluğunda \nartış.\nTIP EZBERLE DEĞİL BÜTÜNCÜL SENTEZLE ÖĞRENİLİR! "}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q077","number":77,"year":"Deneme 01","subject":"Histoloji ve Embriyoloji","stem":"Bir histoloji modeli tek merkezdeki boyamalarla başarılıyken farklı merkezden gelen kesitlerde belirgin hata yapıyor. İlk araştırılması gereken sorun hangisidir?","options":[{"label":"A","text":"Yeni merkezdeki düşüşün veri özellikleri incelenmeden yalnızca rastlantı sayılması","imageOnly":false,"image":null},{"label":"B","text":"Boyama farklarının görüntü verisini hiçbir biçimde etkileyemeyeceğinin varsayılması","imageOnly":false,"image":null},{"label":"C","text":"Modelin eğitim merkezindeki başarısının genellenebilirlik için tek başına yeterli olup olmadığına bakmadan kabul edilmesi","imageOnly":false,"image":null},{"label":"D","text":"Test verilerinin eğitim setine eklenerek bağımsız doğrulamanın kaldırılması","imageOnly":false,"image":null},{"label":"E","text":"Eğitim verisinin temsil gücü ve boyama/cihaz farklılıklarına bağlı dağılım değişimi","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Model eğitimdeki boyama ve görüntüleme özelliklerine aşırı bağımlı olabilir. Farklı merkez verisinde başarının düşmesi temsil ve genellenebilirlik sorunudur; dış doğrulama gerekir. Test verisinin eğitime karıştırılması güvenilir değerlendirmeyi bozar.","topic":"Algoritmik yanlılık","slideSources":[{"file":"Histoloji/4-Histolojide Yapay Zeka.pptx","pages":[22,23],"pageKind":"Slayt","evidence":[{"page":22,"text":"KARAKUTU PROBLEMİ VE AÇIKLANABİLİR YZ\nKara \nKutu\n: Derin öğrenmenin karar adımlarının insan zihniyle \nizlenememesi.\nAçıklanabilir \nYZ (XAI): \nTIPTA GEREKÇESİNİ AÇIKLAYAMADIĞIN KARARI VEREMEZSİN!\nGrad\n-CAM Yöntemi\n: \nMikroskop \ngörüntüsünün üstüne kırmızı/sarı bir ısı haritası düşürür. YZ biyopsiye \"\nMalign\n\" dediyse, \nGrad\n-CAM dokudaki \natipik\n mitoz veya çekirdek büyümesi olan alanı kırmızıya boyayarak hekime \"Ben buraya bakarak bu kararı verdim\" der.."},{"page":23,"text":"ALGORİTMİK YANLILIK VE ARTEFAKT RİSKİ\nVeri Yanlılığı\n: YZ sadece eğitildiği veri seti kadar akıllıdır (\"\nGarbage\n in, \ngarbage\n \nout\n\").\nHistolojik Risk\n: Farklı \nlaboratuvar \nboyama tonlarının (H&E) algoritmayı yanıltması"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q078","number":78,"year":"Deneme 01","subject":"Halk Sağlığı","stem":"Belirti vermeyen bireylerde kanser taraması yapılarak hastalığın erken yakalanması amaçlanıyor. Bu uygulama hangi korunma düzeyindedir?","options":[{"label":"A","text":"İkincil korunma","imageOnly":false,"image":null},{"label":"B","text":"Yalnızca palyatif bakım","imageOnly":false,"image":null},{"label":"C","text":"Sağlık hizmeti sayılmaz.","imageOnly":false,"image":null},{"label":"D","text":"Birincil korunma","imageOnly":false,"image":null},{"label":"E","text":"Yalnızca üçüncül korunma","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Tarama, hastalık oluşmadan riski engellemeyi değil, mevcut hastalığı erken yakalamayı amaçlar; ikincil korunmadır. Aşılama birincil, işlev kaybını azaltmaya yönelik rehabilitasyon üçüncül korunma örneğidir.","topic":"Korunma düzeyleri","slideSources":[{"file":"Halk Sağlığı/1-Halk Sağlığına Giriş.pdf","pages":[12,13,14],"pageKind":"PDF sayfası","evidence":[{"page":12,"text":" Birincil (primer) korunma\n❑ Hastalanmadan önce koruma   \n✔ Sağlık eğitimi\n✔ Sağlıklı beslenme\n✔ Egzersiz\n✔ Bağışıklama\n✔ Seroprofilaksi ve kemoprofilaksi\n✔ Aile planlaması                      \n"},{"page":13,"text":"İkincil (sekonder) korunma\n❑ Erken tanı ve tedavi   \n✔ Tarama testleri (Kanser, yenidoğan vb)\n✔  Kan basıncı ölçümleri   \n✔  Tüberkülin testi                   \n"},{"page":14,"text":"Üçüncül (tersiyer) korunma\n❑ Tedavi ve rehabilitasyon                           \n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q079","number":79,"year":"Deneme 01","subject":"Halk Sağlığı","stem":"Bir bölgede sağlık planı yalnızca pahalı hastane yatırımlarına ayrılırken temiz su, beslenme, aşılama ve toplum katılımı ihmal ediliyor. Bu plan temel sağlık hizmetlerinin hangi anlayışıyla çelişir?","options":[{"label":"A","text":"Bütün kaynakların yalnızca üçüncü basamak tedaviye ayrılmasıyla","imageOnly":false,"image":null},{"label":"B","text":"Toplum katılımının yalnızca mali katkı olarak tanımlanmasıyla","imageOnly":false,"image":null},{"label":"C","text":"Sağlık hizmetinde önceliğin yalnızca satın alma gücüyle belirlenmesiyle","imageOnly":false,"image":null},{"label":"D","text":"Koruyucu hizmetlerin bireysel başvuruya bütünüyle bırakılmasıyla","imageOnly":false,"image":null},{"label":"E","text":"Herkese erişen, korumayı ve toplumun temel gereksinimlerini önceleyen bütüncül yaklaşımla","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Temel sağlık hizmetleri temiz su, beslenme, bağışıklama, ana-çocuk sağlığı ve sık sorunların uygun tedavisi gibi alanları birlikte ele alır. Sosyal eşitlik ve toplum katılımı da esastır; tek başına hastane yatırımı bu kapsamı karşılamaz.","topic":"Temel sağlık hizmetleri","slideSources":[{"file":"Halk Sağlığı/Temel Sağlık Hizmetleri_2026_2027.pptx","pages":[14,24,37],"pageKind":"Slayt","evidence":[{"page":14,"text":"\nBir \nGörüş Olarak TSH\nSosyal \nEşitlik: \n\t\nSağlık \nhizmetleri, doğuştan kazanılmış insan hakkıdır. Bu hizmetler, yalnızca onu satın alabilecek sosyal sınıflara değil, toplumdaki herkese ve dahi sağlık hizmetlerine en uzak yerleşim yerlerinde oturanlara da, sosyal adalet anlayışı içinde eşitlik ve hakkaniyet ölçülerinde (\nequity\n) götürülmelidir\n."},{"page":24,"text":"Sağlık Hizmetine Toplumun Katılımı\nSağlık \nhizmetleri, topluma doğrudan götürülen sosyal hizmetlerdir. Sosyal hizmetler söz konusu olduğunda hizmeti alanlar, hizmeti verenler kadar önemlidir. Eğer hizmeti alanlar bu hizmetin ne olduğunu bilmiyorlarsa, hizmetin veriliş şeklini beğenmiyorlarsa, bu hizmetle ilgili olarak güdülenmemişlerse, hizmeti verenler ne kadar çaba gösterirlerse göstersinler; o hizmeti halka (alıcıya) ulaştıramazlar. O halde sosyal hizmetlerin topluma uyması ve toplum tarafından kabul edilir olması gerekmektedir. Bunu sağlamanın en iyi yolu; hem hizmeti planlama hem de uygulama sırasında bu hizmeti alacak kişilere danışmak ya da o kişilerle beraber çalışmaktır. Bu işbirliğine \"toplumun sağlık hizmetlerine katılımı\" denir. Bu yapıldığı takdirde planlama aşamasında halkın hizmetle ilgili talepleri değerlendirilebilir. Elbette bu taleplerin hepsi karşılanamaz. Ama toplumun gerçek gereksinimini bilebilmek için bu talepler de göz önüne alınmalıdır. Sosyal hizmetlerde halkın hizmete sahip çıkması başarının temel unsurlarından birisidir. Hizmetin nasıl olması gerektiğine karar verenler, o hizmete herkesten daha fazla sahip çıkarlar, işte toplumun katılımı bunu sağlar. Çünkü hizmetin biçiminde ve uygulanmasında onlar da karara katılmışlardır. Bir de halkın hizmetlere para ya da işgücü ile katkı vermesi konusu vardır ki, bu durum “katılım” olarak değerlendirilmemelidir. Ancak bu iki konuyu ayırmanın güçlüğü ve her ikisinin de önemli olduğu göz önüne alınarak bir arada ele alınıp “halkın sağlık hizmetlerine katkı ve katılımı” şeklinde adlandırılması yaygın bir anlayıştır."},{"page":37,"text":"\nFaaliyetler \nolarak TSH\n“En az bakım\n” \n(Minimal \nCare\n) \nHalkın \nsağlık eğitimi \nBeslenme \ndurumunun geliştirilmesi \nTemiz \nsu sağlanması ve \nsanitasyon\nAna-çocuk \nsağlığı ve aile planlaması \nBaşlıca \nbulaşıcı hastalıklara karşı bağışıklama \nEndemik \nhastalıkların kontrolü \nSık \ngörülen hastalıkların uygun tedavisi \nTemel \nilaçların sağlanması "}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q080","number":80,"year":"Deneme 01","subject":"Halk Sağlığı","stem":"Sigaranın zararlarını bilen bir kişi “bırakmayı denedim ama yapabileceğime inanmıyorum” diyor. Eğitimde hangi boyutun desteklenmesi özellikle gereklidir?","options":[{"label":"A","text":"Yalnızca riskin daha yüksek sayısal değerle tekrar edilmesi","imageOnly":false,"image":null},{"label":"B","text":"Öz-yeterlilik","imageOnly":false,"image":null},{"label":"C","text":"Yalnızca hastalık adını ezberleme","imageOnly":false,"image":null},{"label":"D","text":"Davranışın tümüyle bilgi miktarına indirgenmesi","imageOnly":false,"image":null},{"label":"E","text":"Çevresel engellerin davranışla ilişkisiz olduğunun kabul edilmesi","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Öz-yeterlilik kişinin bir davranışı gerçekleştirebileceğine ilişkin inancıdır. Bilgi gerekli olsa da tek başına yeterli değildir; beceri, motivasyon, destek ve çevresel engeller de değerlendirilmelidir.","topic":"Davranış değişikliği","slideSources":[{"file":"Halk Sağlığı/Sağlık_Egitimi_2026-2027_.pptx","pages":[7,10,19,21],"pageKind":"Slayt","evidence":[{"page":7,"text":"SOR\n \n↓\nDİNLE\n↓\nANLA\n↓\nDESTEKLE\n“\nÖnce\n \ndavranışı\n \ndeğil\n, \ndavranışın\n \narkasındaki\n \nkişiyi\n \nanlamaya\n \nçalış\n.”\nBilgi\n + \nmotivasyon\n + \nbeceri\n + \ndestekleyici\n \nçevre\n → \ndavranış\n \ndeğişikliğini\n \nkolaylaştırabilir\n."},{"page":10,"text":"Bilgi gerekli tek başına yeterli değil!\nBİLGİ\nDAVRANIŞ\n“\nSağlık\n \ndavranışı\n, \nbirey\n ile \nçevrenin\n \netkileşiminin\n \nsonucudur\n.”"},{"page":19,"text":"BİLGİ\n＋\nMOTİVASYON\n＋\nBECERİ\n＋\nÖZ-YETERLİLİK\n＋\nETKİLİ İLETİŞİM\n↓\nSAĞLIK OKURYAZARLIĞI\n↓\nBİLİNÇLİ SAĞLIK KARARLARI VE EYLEMLERİ\nSağlık\n \neğitimi\n \nneden\n \nönemlidir\n?"},{"page":21,"text":"Health\n \nBelief\n \nModel\n (\nSağlık\n \nİnanç\n \nModeli\n)\n:\n \nKişinin\n \nbir\n \nsağlık\n \ntehdidini\n ne \nkadar\n \nciddi\n \nve\n \nkendisi\n \niçin\n \nolası\n \ngördüğü\n, \ndavranışın\n \nyarar\n \nve\n \nengellerine\n \nilişkin\n \nalgısı\n ile \nöz-yeterliliği\n \nsağlık\n \ndavranışını\n \netkiler\n.\n“\nTehdidi\n \nnasıl\n \nalgılıyorum\n \nve\n \ndeğişmenin\n \nyararı\n/\nengeli\n \nnedir\n?”"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q081","number":81,"year":"Deneme 01","subject":"Halk Sağlığı","stem":"Bir eğitim hedefi, kişinin inhaler kullanım basamaklarını doğru uygulayabilmesidir. Bu hedefe en uygun yöntem hangisidir?","options":[{"label":"A","text":"Gösterme, kişiye uygulatma ve geri bildirim verme","imageOnly":false,"image":null},{"label":"B","text":"Yalnızca kuramsal tanımları içeren uzun bir konferans","imageOnly":false,"image":null},{"label":"C","text":"Geri bildirim olmadan tek seferlik broşür dağıtımı","imageOnly":false,"image":null},{"label":"D","text":"Kişiye uygulama fırsatı vermeden yalnızca cihazın tarihini anlatma","imageOnly":false,"image":null},{"label":"E","text":"Beceri gözlenmeden yalnızca çoktan seçmeli bilgi testi","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Psikomotor beceri hedefinde gösterip yaptırma ve uygulamaya geri bildirim verme uygundur. Yalnızca bilgi aktarımı, kişinin işlemi doğru yapabildiğini göstermez; yöntem hedefe göre seçilmelidir.","topic":"Sağlık eğitimi yöntemi","slideSources":[{"file":"Halk Sağlığı/Sağlık_Egitimi_2026-2027_.pptx","pages":[55,62,83],"pageKind":"Slayt","evidence":[{"page":55,"text":"\n\tEĞİTİM YÖNTEMLERİ\n1.Bireysel \nve Küçük Grup Eğitimleri\nAnlatım-Sunum\nGöstererek yaptırma- demonstrasyon\n\t(\nyap-göster-yaptır-tekrarlat-alıştır)\nSoru-cevap. \n\t"},{"page":62,"text":"EĞİTİM YÖNTEMLERİ\n6. Gösterip yaptırma: \nAnlatılacak konunun uygulamaya \nyönelik olması durumunda \nkonunun gösterilerek \nanlatılması ve sonrasında \nkatılımcılara da \naynı uygulamanın yaptırılmasıdır."},{"page":83,"text":"6\n. \nEğitim\n \nyöntemini\n \nve\n \nmateryalini\n \nseç\n“\nNasıl\n \nöğreteceğiz\n?”\nHedefe\n \ngöre\n \nyöntem\n \ndeğişir\n.\nBilgi\n \nkazandırmak\nKısa\n \nanlatım\n, \nvideo\n, \nbroşür\nTutumu\n \ntartışmak\nGrup\n \ntartışması\n, \nvaka\nBeceri\n \nkazandırmak\nGösterim\n + \nuygulama\nProblem\n \nçözmek\nVaka\n \nçalışması\nDavranış\n \ndeğişikliğini\n \ndesteklemek\nBireysel\n \ngörüşme\n, \nhedef\n \nbelirleme"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q082","number":82,"year":"Deneme 01","subject":"Halk Sağlığı","stem":"Bir ilçede bir yılda 1200 canlı doğum ve 15 ölü doğum vardır. Aynı yıl 7 erken neonatal, 5 geç neonatal ve 12 postneonatal ölüm kaydedilmiştir. Derslerde kullanılan kaba hesapla bebek ölüm hızı kaçtır?","options":[{"label":"A","text":"Binde 12,5","imageOnly":false,"image":null},{"label":"B","text":"Binde 20","imageOnly":false,"image":null},{"label":"C","text":"Binde 10","imageOnly":false,"image":null},{"label":"D","text":"Binde 19,75","imageOnly":false,"image":null},{"label":"E","text":"Binde 32,5","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"B","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Bir yaş altındaki ölümler 7+5+12=24’tür. Bebek ölüm hızı = (24/1200)×1000 = binde 20. Ölü doğumlar ne bebek ölümü payına ne de canlı doğum paydasına eklenir. Verilen sayılar eğitim amaçlı örnektir.","topic":"Bebek ölüm hızı","slideSources":[{"file":"Halk Sağlığı/Sağlık ölçütleri^J Türkiye ve Dünyada sağlık göstergeleri.pptx","pages":[15],"pageKind":"Slayt","evidence":[{"page":15,"text":"Bebek Ölüm Hızı (BÖH)\n Bir toplumda genel sağlık, özellikle çocuk sağlığı düzeyini belirlemek, bu konuda sunulan hizmetlerin etkinliğini değerlendirmek için kullanılan \nen anlamlı ve önemli \nölçütlerden birisi bebek ölüm hızlarıdır            \n           \n   \n "}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q083","number":83,"year":"Deneme 01","subject":"Halk Sağlığı","stem":"Yıl başında hastalıksız 2000 kişi bir yıl eksiksiz izleniyor ve 40 yeni vaka gelişiyor. Bu grupta bir yıllık kümülatif insidans kaçtır?","options":[{"label":"A","text":"%20","imageOnly":false,"image":null},{"label":"B","text":"%0,2","imageOnly":false,"image":null},{"label":"C","text":"%40","imageOnly":false,"image":null},{"label":"D","text":"%2","imageOnly":false,"image":null},{"label":"E","text":"%4","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Kümülatif insidans = dönem içindeki yeni vaka sayısı / başlangıçta hastalıksız risk altındaki kişi sayısıdır. 40/2000=0,02=%2. Eski vakalar yeni vaka sayısına eklenmez.","topic":"İnsidans ve prevalans","slideSources":[{"file":"Halk Sağlığı/Sağlık ölçütleri^J Türkiye ve Dünyada sağlık göstergeleri.pptx","pages":[28],"pageKind":"Slayt","evidence":[{"page":28,"text":"İnsidans\n Belirli bir süre içinde bir toplumdaki “sağlam” kişilerin belirli bir hastalığa yakalanma olasılığıdır\n Bir toplumda belirli bir süre içinde saptanan \nyeni vaka \nsayısıdır\n           \n           \n   \n "}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q084","number":84,"year":"Deneme 01","subject":"Halk Sağlığı","stem":"Bir salgında tanımlanmış 250 vakanın 10’u bu hastalık nedeniyle ölüyor. Vaka fatalite oranı kaçtır?","options":[{"label":"A","text":"%4","imageOnly":false,"image":null},{"label":"B","text":"%2,5","imageOnly":false,"image":null},{"label":"C","text":"%25","imageOnly":false,"image":null},{"label":"D","text":"%0,4","imageOnly":false,"image":null},{"label":"E","text":"%10","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Vaka fatalite oranı hastalıktan ölenlerin o hastalığa yakalananlara oranıdır: 10/250×100=%4. Toplam toplum nüfusu bu ölçütün paydası değildir; bu yüzden toplum ölüm hızıyla karıştırılmamalıdır.","topic":"Fatalite","slideSources":[{"file":"Halk Sağlığı/Sağlık ölçütleri^J Türkiye ve Dünyada sağlık göstergeleri.pptx","pages":[14],"pageKind":"Slayt","evidence":[{"page":14,"text":"Fatalite Hızı\n Belirli bir hastalığa yakalananlar içinden ne kadarının öldüğünü, yani bu hastalığın ne kadar \nfatal\n-öldürücü olduğunu gösteren ölçüttür           \n           \n   \n "}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q085","number":85,"year":"Deneme 01","subject":"Tıbbi Biyokimya","stem":"5,85 g NaCl kullanılarak son hacmi 500 mL olan çözelti hazırlanıyor. NaCl’nin mol kütlesi 58,5 g/mol olduğuna göre molarite kaçtır?","options":[{"label":"A","text":"2,0 mol/L","imageOnly":false,"image":null},{"label":"B","text":"1,17 mol/L","imageOnly":false,"image":null},{"label":"C","text":"0,20 mol/L","imageOnly":false,"image":null},{"label":"D","text":"0,02 mol/L","imageOnly":false,"image":null},{"label":"E","text":"0,10 mol/L","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Mol sayısı 5,85/58,5=0,10 mol. Molarite mol/çözelti hacmi (L) olduğundan 0,10/0,500=0,20 mol/L. Paydada çözücünün değil, son çözeltinin hacmi kullanılır.","topic":"Molarite","slideSources":[{"file":"Biyokimya/3-Çözeltiler ve Kons..pdf","pages":[35,36,37],"pageKind":"PDF sayfası","evidence":[{"page":35,"text":"2) Molarite (M) (2. Ders)\n35\n• Molarite, 1 L çözeltideki, çözünmüş maddenin mol \nsayısıdır.\n• Molaritenin ölçüm birimi mol/litre ve sembolü M’dir.\n1 M çözelti; deyince çözeltinin 1 litresinde 1 mol çözünen \nbulunduğu anlaşılır.\n1 M= 1 mol/L= 1000 mM= 1000000 μM\n1 mM= 1 mmol/L= 0,001 M\n1μM= 1 µmol/L= 0,001 mM\n"},{"page":36,"text":"36\n• 1 mol glukoz = 180 g glukoz.\n• 1 mol NaCl = 58,5 g NaCl\n \n• 1mol CaCl2 = 111 g CaCl2\n       İçerir.\nYukarıdaki 1 mol glukoz, NaCl ve CaCl2 yi alıp, ayrı ayrı \nbalonlar içine koyup, su ile 1 L ye (balonların boynundaki \nçizgiye kadar) tamamlarsak, her birinin 1 M’ lık ve bir litre \nhacimde çözeltileri hazırlanmış olur.\n"},{"page":37,"text":"• Örnek: Litresinde 36 gr glukoz bulunan çözeltinin \nmolaritesini bulalım:\nGlukozun molekül ağırlığı yaklaşık 180 g dır. \nMolarite;  çözünen maddenin litredeki mol sayısı idi. \nBuna göre,\nM= 36/180= 0,2 M bulunur\n37\nKATI BİR MADDEDEN MOLAR ÇÖZELTİ HAZIRLANMASI\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q086","number":86,"year":"Deneme 01","subject":"Tıbbi Biyokimya","stem":"NaCl’nin tam ayrıştığı ideal varsayımı altında 0,15 mol/L NaCl çözeltisinin hesaplanan osmolaritesi kaçtır?","options":[{"label":"A","text":"300 mOsm/L","imageOnly":false,"image":null},{"label":"B","text":"75 mOsm/L","imageOnly":false,"image":null},{"label":"C","text":"30 mOsm/L","imageOnly":false,"image":null},{"label":"D","text":"150 mOsm/L","imageOnly":false,"image":null},{"label":"E","text":"15 mOsm/L","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"A","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"NaCl ideal olarak Na⁺ ve Cl⁻ olmak üzere iki parçacık oluşturur. 0,15×2=0,30 Osm/L=300 mOsm/L. Gerçek çözeltilerde idealden sapma olabilir; soru tam ayrışma varsayımını açıkça vermektedir.","topic":"Osmolarite","slideSources":[{"file":"Biyokimya/3-Çözeltiler ve Kons..pdf","pages":[52],"pageKind":"PDF sayfası","evidence":[{"page":52,"text":"52\nOsmolarite (Osmol)\n• 1 litre solusyondaki çözünmüş partiküllerin (osmotik aktif parçacık) \nmiktarıdır. Osmol/Lt = 1000 mOsmol/L\n• 1 molar Glukoz= 1 osmol dür. Çünkü Glukoz suda, 1 molu 1 partikül olarak \nçözünür.\n• 1 molar NaCl= 2 osmol NaCl (NaCl, çözünürken Na ve Cl olarak 2 partikül \nşeklinde çözünür. Bu durumda 1 mol NaCl = 2 osmol olacaktır.\n• 1 Molar CaCl2  ise= çözündüğünde 3 partikül (2 Cl, 1 Ca) oluşturacağından= \n3 osmol dür.\n•Plazma osmolaritesi hesaplanırken plazmadaki tüm partiküller hesaplanır; \n(Plasma mOsmol / Lt ) = (2xNa) + Glc/18 + BUN/2.8 (sodyumun 2 ile \nçarpılma sebebi plazmadaki anyonları (Cl, HCO3 vb) da formüle dahil \netmektir.) Yani\nNormal Plazma osmolaritesi 280 (275 -295) mosmol/Lt dir.\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q087","number":87,"year":"Deneme 01","subject":"Tıbbi Biyokimya","stem":"2,0 mol/L stok çözeltiden 250 mL 0,40 mol/L çözelti hazırlamak için kaç mL stok alınmalıdır?","options":[{"label":"A","text":"125 mL","imageOnly":false,"image":null},{"label":"B","text":"100 mL","imageOnly":false,"image":null},{"label":"C","text":"50 mL","imageOnly":false,"image":null},{"label":"D","text":"20 mL","imageOnly":false,"image":null},{"label":"E","text":"40 mL","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"C","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"C₁V₁=C₂V₂: 2,0×V₁=0,40×250; V₁=50 mL. Stok alındıktan sonra son hacim 250 mL’ye tamamlanır. Bu ifade 250 mL çözücü eklemekle aynı değildir.","topic":"Seyreltme","slideSources":[{"file":"Biyokimya/3-Çözeltiler ve Kons..pdf","pages":[54,55,59,60],"pageKind":"PDF sayfası","evidence":[{"page":54,"text":"54\nÇÖZELTİLERİN SEYRELTİLMESİ\n• Konsantre \nbir \nçözeltiden \ndilüe \nbir \nçözelti \nhazırlanmasına, seyreltme (dilusyon) denir. \n"},{"page":55,"text":"• Biyokimyada yapılan \nseyreltmeler, toplam \nçözeltinin bütün \nözelliklerini içerecek \nşekilde hazırlanır. \n• 1:100’luk seyreltme \nyapılırken konsantre \nçözeltiden 1 birim \nalınarak üzerine 99 birim  \nsıvı (su) eklenerek son \nhacim 100 birim olur.\n55\n"},{"page":59,"text":"Çözeltilerde C molarite veya normalite olarak ifade \nedildiği zaman:\n59\n"},{"page":60,"text":"60\n% 98’lik alkol ile 250 mL % 70 lik alkol çözeltisi \nhazırlayalım.\nV1 x C1 = V2 x C2 \nV1 = 98 = 250 x 70\nV1 = 250 x 70 / 98\nV1 = 178,57 mL \n178, 57 mL % 98 lik alkolden alınarak üzerine saf su \neklenerek son hacim 250 mL ye tamamlanırsa; % 70’lik \nalkol çözeltisi hazıerlamış oluruz.\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q088","number":88,"year":"Deneme 01","subject":"Tıbbi Biyokimya","stem":"Suda çözünmüş Na⁺ iyonu çevresindeki su moleküllerinin hangi kısmı katyona yönelme eğilimindedir?","options":[{"label":"A","text":"Oksijenin kısmi pozitif, hidrojenin kısmi negatif tarafı","imageOnly":false,"image":null},{"label":"B","text":"İyon-dipol etkileşimi olmadan tamamen rastgele yönelim","imageOnly":false,"image":null},{"label":"C","text":"Kısmi pozitif yük taşıyan hidrojen tarafı","imageOnly":false,"image":null},{"label":"D","text":"Oksijen ve hidrojen taraflarının eşit ölçüde yönelmesi","imageOnly":false,"image":null},{"label":"E","text":"Kısmi negatif yük taşıyan oksijen tarafı","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"E","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"Oksijen daha elektronegatif olduğu için suyun oksijen tarafı kısmi negatif yüklüdür. Pozitif iyonlara bu taraf yönelir. Anyonlar çevresinde ise kısmi pozitif hidrojen taraflarının yönelmesi beklenir.","topic":"Suyun polaritesi","slideSources":[{"file":"Biyokimya/4-Su.pdf","pages":[6,10,18],"pageKind":"PDF sayfası","evidence":[{"page":6,"text":"•Oksijen hidrojene oranla daha elektronegatif bir atom \nolduğu için paylaşılan elektron çifti oksijene daha yakın \ndurur ve oluşan bağda simetrik olmayan bir elektron \ndağılımı sonucu bir yük kutuplaşması meydana gelir.\n•Bu durumda oksijen atomları üzerinde negatif yük ve \nhidrojen atomları üzerinde pozitif yük oluşur.\n•Bu durum su molekülüne dipolar özellik kazandırır.\n"},{"page":10,"text":"Hidrojen Bağı\n• Dipolar yapı su molekülleri arasındaki çekim \nkuvvetinden sorumludur.\n• Su molekülündeki oksijen atomu üzerindeki kısmi \nnegatif yük ile diğer hidrojen atomları arasındaki \nkısmi pozitif yük arasında elektrostatik çekim \nmeydana gelir.\n• Bu tip elektrostatik etkileşmeye HİDROJEN BAĞI denir.\n"},{"page":18,"text":"18\nSulu çözeltide katyonlar su molekülünün negatif yük \nmerkezini çekerler; anyonlar da su molekülünün pozitif \nyük merkezini çekerler. \n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q089","number":89,"year":"Deneme 01","subject":"Tıbbi Biyokimya","stem":"Bir zayıf asit/konjuge baz tamponunda [A⁻]=[HA] ve pKa=6,8 ise pH kaçtır?","options":[{"label":"A","text":"13,6","imageOnly":false,"image":null},{"label":"B","text":"5,8","imageOnly":false,"image":null},{"label":"C","text":"7,8","imageOnly":false,"image":null},{"label":"D","text":"6,8","imageOnly":false,"image":null},{"label":"E","text":"3,4","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"pH=pKa+log([A⁻]/[HA]). Derişimler eşitse oran 1, log1=0 olur; pH=pKa=6,8. Eşit derişim, ortamın zorunlu olarak pH 7 olduğu anlamına gelmez.","topic":"Tampon ve Henderson–Hasselbalch","slideSources":[{"file":"Biyokimya/4-Su.pdf","pages":[58,59],"pageKind":"PDF sayfası","evidence":[{"page":58,"text":"                                        \n              \n                       \n      [A-]    \n                 pH  =  pK  +  log  ⎯⎯⎯\n                                       \n     [HA]      \n \nHenderson-Hasselbach eşitliği olarak bilinen bu denklem \ngerek zayıf bir asitin gerekse tamponların pH sını incelemek \niçin son derece yararlıdır. Henderson-Hasselbach denklemi \ndikkatlice incelenecek olursa ( pK sabit bir değer olduğuna \ngöre) bir zayıf asitin pH sının [A-] / [HA] oranı veya \nkonjuge baz / asit oranına bağlı olduğu görülür \n"},{"page":59,"text":"Bir asit tam olarak yarısı nötralize edilirse\nyani [A-] =  [HA] olursa:\n \n     pH  =  pK  +  log [A-]   ⇒  pH = pK + log1/1\n                         [HA]  \n                \n                                                      pH = pK olur. \n \nO halde pK yı şöyle tanımlayabiriz:\nBir zayıf asitin konsantrasyonun konjuge bazına eşit olduğu \npH, pK dır.\n"}]}],"sourceNotes":""},{"id":"d1k1-deneme01-q090","number":90,"year":"Deneme 01","subject":"Tıbbi Biyokimya","stem":"Bir çözeltinin pH’sı 7’den 5’e düşüyor. Hidrojen iyonu derişimi nasıl değişir?","options":[{"label":"A","text":"10 kat azalır.","imageOnly":false,"image":null},{"label":"B","text":"Değişmez.","imageOnly":false,"image":null},{"label":"C","text":"100 kat azalır.","imageOnly":false,"image":null},{"label":"D","text":"100 kat artar.","imageOnly":false,"image":null},{"label":"E","text":"2 kat artar.","imageOnly":false,"image":null}],"origin":"generated","authoredKey":"D","sourceKeys":[],"verifiedKeys":null,"recommendedKeys":null,"status":"generated_practice","rationale":null,"references":[],"correctionNotes":[],"completeness":"text_available","needsVisual":false,"pages":[],"sourceImages":[],"visuals":[],"visualCaptions":[],"aiExplanation":"pH=−log₁₀[H⁺] olduğundan her bir pH düşüşü [H⁺]’ın 10 kat artmasına karşılık gelir. İki birim düşüş 10²=100 kat artış demektir.","topic":"pH ölçeği","slideSources":[{"file":"Biyokimya/4-Su.pdf","pages":[30,35,38],"pageKind":"PDF sayfası","evidence":[{"page":30,"text":"Her iki iyonun konsantrasyonları eşit olduğu için \n[H+]=1x10-7 ve [OH-]=1x10-7 olur.\nBir çözeltinin H+ iyonları konsantrasyonunun eksi \nlogaritmasına o çözeltinin pH değeri denir.\n Su için pH=-log [H+]\n                   =-log10-7 \n            pH=7                    olur.\n"},{"page":35,"text":"H+ iyon konsantrasyonları ifade etmede kullanılan bu uzun \nfraksiyonlar ve negatif üslü değerler yerine 1909 yılında \nDanimarkalı biyokimyacı Sörensen pH terimini öne sürmüştür. \nBuna göre pH hidrojen iyon konsantrasyonunun negatif \nlogaritması olarak tarif edilmiştir. \n                                     pH =  -log [H+]\n"},{"page":38,"text":"• Bu tanımlama, tam olmasa da birçok biyokimyasal amaç \niçin yeterlidir. Bir çözeltinin pH’ sını hesaplamak için:\n1. Hidrojen iyon derişimi, [H+] hesaplanır.\n2. [H+]’in 10 tabanına göre logaritması bulunur.\n3. pH, 2.basamakta bulunan değerin eksi değerlisidir.\nÖrneğin; 25°C’ da saf su için,\n• pH = -log [H+] = -log 10-7 = -(-7) = 7.0\n"}]}],"sourceNotes":""}];
